"use strict";(globalThis.webpackChunkmy_tech_blog=globalThis.webpackChunkmy_tech_blog||[]).push([[8724],{8296:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"kotlin-lsp-extension-10","metadata":{"permalink":"/blog/posts/kotlin-lsp-extension-10","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-16-kotlin-lsp-extension-10/index.mdx","source":"@site/blog/2026-10-16-kotlin-lsp-extension-10/index.mdx","title":"Cursor\xb7VS Code\uc5d0\uc11c IntelliJ\uae09 Kotlin \ubd84\uc11d\uc774 \uc628\ub2e4 \u2014 \\"Java and Kotlin by IntelliJ IDEA\\" 1.0","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-16T00:00:00.000Z","tags":[{"inline":true,"label":"kotlin","permalink":"/blog/posts/tags/kotlin"},{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"intellij","permalink":"/blog/posts/tags/intellij"},{"inline":true,"label":"cursor","permalink":"/blog/posts/tags/cursor"},{"inline":true,"label":"vscode","permalink":"/blog/posts/tags/vscode"},{"inline":true,"label":"ide","permalink":"/blog/posts/tags/ide"}],"readingTime":3.06,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kotlin-lsp-extension-10","title":"Cursor\xb7VS Code\uc5d0\uc11c IntelliJ\uae09 Kotlin \ubd84\uc11d\uc774 \uc628\ub2e4 \u2014 \\"Java and Kotlin by IntelliJ IDEA\\" 1.0","authors":["way"],"tags":["kotlin","android","intellij","cursor","vscode","ide"]},"unlisted":false,"nextItem":{"title":"Kotlin Toolchain 0.13 \u2014 kotlin new \uba85\ub839\uacfc Android SDK \uc790\ub3d9 \uc124\uc815\uc73c\ub85c KMP \uc2dc\uc791\uc774 \uc26c\uc6cc\uc9c4\ub2e4","permalink":"/blog/posts/kotlin-toolchain-013"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n10\uc8fc \uc804 \ud504\ub9ac\ubdf0\ub85c \uacf5\uac1c\ub410\ub358 JetBrains\uc758 LSP \uae30\ubc18 \ud655\uc7a5 **\\"Java and Kotlin by IntelliJ IDEA\\"**\uac00 \ub4dc\ub514\uc5b4 **1.0 \uc815\uc2dd \ub9b4\ub9ac\uc2a4**\ub97c \ub9de\uc558\uc2b5\ub2c8\ub2e4. \uc774\uc81c VS Code\uc640 Cursor\uc5d0\uc11c\ub3c4 IntelliJ IDEA \ub370\uc2a4\ud06c\ud1b1 IDE\uc758 Java\xb7Kotlin \ubd84\uc11d \uc5d4\uc9c4\uc744 \uadf8\ub300\ub85c \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. JetBrains\uc758 \ubc1c\ud45c \uae00 \\"IntelliJ IDEA\'s Java and Kotlin for Cursor and VS Code Hits 1.0\\"(2026\ub144 10\uc6d4)\uc744 \uc2e4\ubb34 \uad00\uc810\uc5d0\uc11c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- IntelliJ IDEA\uc758 Java\xb7Kotlin \uc5b8\uc5b4 \uc9c0\ub2a5\uc744 LSP(\uc5b8\uc5b4 \uc11c\ubc84 \ud504\ub85c\ud1a0\ucf5c)\ub85c \ubf51\uc544\ub0b4 VS Code\xb7Cursor\uc5d0 \uadf8\ub300\ub85c \uc62c\ub9b0 \ud655\uc7a5\uc785\ub2c8\ub2e4. Cursor \ud300\uacfc \ud568\uaed8 \ud611\uc5c5\ud574 \uac1c\ubc1c\ub410\uc2b5\ub2c8\ub2e4.\\n- 1.0\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 \uae30\ub2a5: Java\xb7Kotlin\xb7\ud63c\ud569 \uc5b8\uc5b4 \ud504\ub85c\uc81d\ud2b8 \uc9c0\uc6d0, \uc2a4\ub9c8\ud2b8 \uc644\uc131\xb7\uc774\ub3d9\xb7\ucf54\ub4dc \ubd84\uc11d, \ub9ac\ud329\ud130\ub9c1, Maven\xb7Gradle\xb7Bazel \ube4c\ub4dc \uc9c0\uc6d0, \ub300\uaddc\ubaa8 \ud504\ub85c\uc81d\ud2b8\xb7\ubaa8\ub178\ub808\ud3ec\uc5d0\uc11c\ub3c4 \ube60\ub978 \uc131\ub2a5, JUnit \ud14c\uc2a4\ud2b8 \ub7ec\ub108, \uc5d0\ubbac\ub808\uc774\ud2b8 \ube0c\ub808\uc774\ud06c\ud3ec\uc778\ud2b8\xb7\ube44\ub3d9\uae30 \uc2a4\ud0dd \ud2b8\ub808\uc774\uc2a4 \uc9c0\uc6d0 \ub514\ubc84\uae45\uc785\ub2c8\ub2e4.\\n- Cursor\uc5d0\uc11c\ub294 *Agents Window* \uc804\uc6a9 \uc9c0\uc6d0\uc774 \uc788\uc2b5\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8 \uc708\ub3c4\uc6b0\uac00 \uc790\uccb4 Language Server \uc778\uc2a4\ud134\uc2a4\ub97c \ub744\uc6cc IntelliJ \uc778\uc2a4\ud399\uc158 \uae30\ubc18 \ubd84\uc11d(JSpecify \ub110\ub7ec\ube4c\ub9ac\ud2f0, Spring \ud2b9\ud654 \ubd84\uc11d \ud3ec\ud568)\uc744 \uc218\ud589\ud569\ub2c8\ub2e4.\\n- **\ub77c\uc774\uc120\uc2a4\uac00 \uc720\ub8cc\ub85c \uc804\ud658\ub410\uc2b5\ub2c8\ub2e4.** \ud504\ub9ac\ubdf0 \uae30\uac04\uc758 \ubb34\ub8cc\uac00 \ub05d\ub098\uace0, 30\uc77c \ud3c9\uac00\ud310\uc744 \uc9c0\ub098\uba74 IntelliJ IDEA Ultimate \uad6c\ub3c5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4. \uac19\uc740 \ub77c\uc774\uc120\uc2a4\ub85c \ub370\uc2a4\ud06c\ud1b1 IDE\xb7VS Code \uacc4\uc5f4 \uc5d0\ub514\ud130\ub97c \ubaa8\ub450 \ucee4\ubc84\ud569\ub2c8\ub2e4.\\n- \uc124\uce58\ub294 Visual Studio Marketplace \ub610\ub294 Open VSX Registry\uc5d0\uc11c \ud569\ub2c8\ub2e4. Red Hat\xb7Oracle\uc758 Java \ud655\uc7a5\uacfc \ubd84\uc11d \uae30\ub2a5\uc774 \uacb9\uce58\ubbc0\ub85c JetBrains\ub294 \ud574\ub2f9 \ud655\uc7a5\uc744 \ub044\uace0 \uc4f8 \uac83\uc744 \uad8c\uc7a5\ud569\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### LSP \ud55c \ubc88\uc73c\ub85c \uc5d0\ub514\ud130 \uac00\ub9ac\uc9c0 \uc54a\ub294 \ubd84\uc11d \uc5d4\uc9c4\\n\\n\ud575\uc2ec \uc544\uc774\ub514\uc5b4\ub294 \ub2e8\uc21c\ud569\ub2c8\ub2e4. \uc5b8\uc5b4 \uc9c0\uc6d0(LSP)\uc744 \ud55c \ubc88\ub9cc \uad6c\ud604\ud558\uace0, \uc5b4\ub5a4 \uc5d0\ub514\ud130\uc5d0\uc11c\ub4e0 \uc7ac\uc0ac\uc6a9\ud558\ub294 \uac83\uc785\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8\uac00 LSP\ub97c \uc9c1\uc811 \ud638\ucd9c\ud558\uba74 \ub354 \ube60\ub974\uace0 \uacb0\uc815\uc801\uc778 \uacb0\uacfc\ub97c \uc5bb\uace0, \ud1a0\ud070 \uc18c\ubaa8\ub3c4 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub294 Cursor\xb7VS Code\uc758 *Agents* \ubdf0\uc5d0\uc11c \uc5d0\uc774\uc804\ud2b8\uac00 LSP\ub97c \uc9c1\uc811 \ud638\ucd9c\ud574 \ucf54\ub4dc\ub97c \uc791\uc131\ud558\ub294 \ud750\ub984\uae4c\uc9c0 \uc5f4\ub9b4 \uc608\uc815\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \ud130\ubbf8\ub110 \uae30\ubc18 \uc5d0\uc774\uc804\ud2b8(Claude Code, Codex \ub4f1)\uac00 IntelliJ\uc758 Kotlin \uc774\ud574\ub97c \uc9c1\uc811 \ud638\ucd9c\ud558\ub294 \uc2e4\ud5d8\ub3c4 \ubcd1\ud589 \uc911\uc785\ub2c8\ub2e4.\\n\\n#### \uc720\ub8cc \uc804\ud658\uc774 \uc2e4\ubb34\uc5d0 \uc8fc\ub294 \uc758\ubbf8\\n\\n10\uc8fc \ub3d9\uc548 \ubb34\ub8cc \ud504\ub9ac\ubdf0\ub85c \uc4f0\ub358 \ud300\uc774 \uc788\ub2e4\uba74 \uc774\uc81c \uad6c\ub3c5 \ube44\uc6a9\uc744 \uc608\uc0b0\uc5d0 \ub123\uc5b4\uc57c \ud569\ub2c8\ub2e4. \uac1c\uc778 \ucde8\ubbf8\uc6a9\uc73c\ub85c Cursor\uc5d0\uc11c Kotlin\uc744 \uac74\ub4dc\ub9ac\ub358 \uac1c\ubc1c\uc790\uc5d0\uac8c\ub294 \ub2e4\uc18c \ubd80\ub2f4\uc2a4\ub7ec\uc6b4 \uac00\uaca9 \uc815\ucc45\uc785\ub2c8\ub2e4. \ub2e4\ub9cc \ub77c\uc774\uc120\uc2a4 \ud558\ub098\uac00 IntelliJ IDEA \ub370\uc2a4\ud06c\ud1b1 + VS Code/Cursor\ub97c \ubaa8\ub450 \ucee4\ubc84\ud558\ubbc0\ub85c, \uc774\ubbf8 Ultimate\ub97c \uc4f0\ub294 \uac1c\ubc1c\uc790\uc5d0\uac8c\ub294 \ucd94\uac00 \ube44\uc6a9 \uc5c6\uc774 \uc5d0\ub514\ud130 \uc120\ud0dd\uc9c0\uac00 \ub298\uc5b4\ub098\ub294 \uc148\uc785\ub2c8\ub2e4.\\n\\n#### \\"\uc778\uac04\uc6a9 \ub77c\uc774\uc120\uc2a4\\"\ub77c\ub294 \ub2e8\uc11c\\n\\n\uacf5\uc9c0\uc5d0\uc11c \ud765\ubbf8\ub85c\uc6b4 \ub300\ubaa9\uc774 \ud558\ub098 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \ub77c\uc774\uc120\uc2a4\ub294 **\uc778\uac04 \uc0ac\uc6a9\uc744 \uc804\uc81c\ub85c \uc124\uacc4\ub410\uc73c\uba70, \uc21c\uc218 \uc5d0\uc774\uc804\ud2b8 \uc6a9\ub3c4(purely agentic use)\uc758 \ub77c\uc774\uc120\uc2a4 \ubaa8\ub378\uc740 \ubcc4\ub3c4\ub85c \ubc1c\ud45c**\ud558\uaca0\ub2e4\uace0 \ud588\uc2b5\ub2c8\ub2e4. \ud300\uc5d0\uc11c \ube4c\ub4dc \uc11c\ubc84\ub098 CI \uc5d0\uc774\uc804\ud2b8\uc5d0 \uc774 \ud655\uc7a5\uc744 \uae54\uc544 \ucf54\ub4dc \ubd84\uc11d\uc744 \ub3cc\ub9b4 \uacc4\ud68d\uc774\ub77c\uba74, \ub2f9\ubd84\uac04\uc740 \uae30\ub2e4\ub838\ub2e4\uac00 \uc0c8 \ubaa8\ub378\uc744 \ud655\uc778\ud558\ub294 \ucabd\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5/\uc8fc\uc758\uc810\\n\\n- **\uae30\uc874 Java \ud655\uc7a5\uacfc \ucda9\ub3cc\ud569\ub2c8\ub2e4.** Red Hat\uc758 Java \ud655\uc7a5\uc744 \ucf20 \ucc44\ub85c \uc4f0\uba74 \ubd84\uc11d \uacb0\uacfc\uac00 \uc911\ubcf5\ub418\uac70\ub098 \uc5c7\uac08\ub9bd\ub2c8\ub2e4. \uc870\uc9c1 \ub2e8\uc704\ub85c \ub3c4\uc785\ud55c\ub2e4\uba74 settings \uc218\uc900\uc5d0\uc11c \ube44\ud65c\uc131\ud654 \uc815\ucc45\uc744 \uac19\uc774 \ubc30\ud3ec\ud558\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.\\n- **Android \uac1c\ubc1c\uc790 \uc785\uc7a5\uc5d0\uc11c\ub294** \uc8fc \uc5d0\ub514\ud130\uac00 Android Studio\ub77c \ub2f9\uc7a5 \ubc14\uafc0 \uc774\uc720\ub294 \uc5c6\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \uacf5\uc720 Kotlin \ubaa8\ub4c8(\uba40\ud2f0\ud50c\ub7ab\ud3fc common \ucf54\ub4dc, \uc11c\ubc84 \ucf54\ub4dc)\uc744 Cursor\ub098 VS Code\uc5d0\uc11c \ub9cc\uc9c0\ub294 \uc77c\uc774 \uc788\ub2e4\uba74, \uc774\uc81c \\"IDE \uae30\ub2a5\uc774 \ub5a8\uc5b4\uc9c4\ub2e4\\"\ub294 \uc774\uc720\ub85c IntelliJ\ub97c \ub530\ub85c \uc5f4 \ud544\uc694\uac00 \uc5c6\uc5b4\uc9d1\ub2c8\ub2e4.\\n- Gradle\xb7Bazel \uae30\ubc18 \ud504\ub85c\uc81d\ud2b8\ub97c \uc790\ub3d9\uc73c\ub85c \uc784\ud3ec\ud2b8\ud558\ubbc0\ub85c, \uae30\uc874 IntelliJ \ud504\ub85c\uc81d\ud2b8\ub97c VS Code\uc5d0\uc11c \uc5ec\ub294 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ube44\uc6a9\uc740 \ub0ae\uc740 \ud3b8\uc785\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc \uc608\uc2dc\\n\\n```jsonc\\n// .vscode/settings.json \u2014 JetBrains \ud655\uc7a5\uacfc \ud568\uaed8 \uc4f8 \ub54c \uad8c\uc7a5 \uc124\uc815\\n{\\n  // Red Hat Java \ud655\uc7a5\uacfc \ubd84\uc11d\uc774 \uc911\ubcf5\ub418\ubbc0\ub85c \ube44\ud65c\uc131\ud654 (\uc815\ud655\ud55c ID\ub294 \uc124\uce58 \ubaa9\ub85d\uc5d0\uc11c \ud655\uc778)\\n  // \\"redhat.java\\" \ud655\uc7a5\uc744 \ub044\uace0 \\"Java and Kotlin by IntelliJ IDEA\\"\ub9cc \ucf2d\ub2c8\ub2e4.\\n}\\n```\\n\\n\uc124\uc815\uc740 \ud55c \uc904\uc9dc\ub9ac\uc9c0\ub9cc \uc758\ubbf8\ub294 \ubd84\uba85\ud569\ub2c8\ub2e4. \uc774 \ud655\uc7a5 \ud558\ub098\ub85c \ubd84\uc11d \uccb4\uacc4\ub97c \ud1b5\uc77c\ud558\uace0, \ub2e4\ub978 \ud655\uc7a5\ub4e4\uc740 \ub044\ub294 \uac83\uc774 \uad8c\uc7a5 \uad6c\uc131\uc785\ub2c8\ub2e4. \ud300 \uc704\ud0a4\uc5d0 \\"Kotlin \ubd84\uc11d\uc740 JetBrains \ud655\uc7a5\uc73c\ub85c \ud1b5\uc77c\\"\uc774\ub77c\ub294 \ud55c \uc904\ub9cc \uc801\uc5b4\ub46c\ub3c4 \uc628\ubcf4\ub529 \ud63c\ub780\uc774 \uc904\uc5b4\ub4ed\ub2c8\ub2e4.\\n\\n### \ucd9c\ucc98\\n\\n- [IntelliJ IDEA\'s Java and Kotlin for Cursor and VS Code Hits 1.0 \u2014 JetBrains Blog (2026\ub144 10\uc6d4)](https://blog.jetbrains.com/idea/2026/10/intellij-idea-s-java-and-kotlin-for-cursor-and-vs-code-hits-1-0/) \u2014 1.0 \uc815\uc2dd \ub9b4\ub9ac\uc2a4, Cursor \ud611\uc5c5, \ub77c\uc774\uc120\uc2a4(30\uc77c \ud3c9\uac00\ud310 \ud6c4 Ultimate \ud544\uc694), \ub85c\ub4dc\ub9f5(\uc5d0\uc774\uc804\ud2b8 LSP \uc9c1\uc811 \ud638\ucd9c\xb7\ud130\ubbf8\ub110 \uc6cc\ud06c\ud50c\ub85c)"},{"id":"kotlin-toolchain-013","metadata":{"permalink":"/blog/posts/kotlin-toolchain-013","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-16-kotlin-toolchain-013/index.mdx","source":"@site/blog/2026-10-16-kotlin-toolchain-013/index.mdx","title":"Kotlin Toolchain 0.13 \u2014 kotlin new \uba85\ub839\uacfc Android SDK \uc790\ub3d9 \uc124\uc815\uc73c\ub85c KMP \uc2dc\uc791\uc774 \uc26c\uc6cc\uc9c4\ub2e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-16T00:00:00.000Z","tags":[{"inline":true,"label":"kotlin","permalink":"/blog/posts/tags/kotlin"},{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"kmp","permalink":"/blog/posts/tags/kmp"},{"inline":true,"label":"toolchain","permalink":"/blog/posts/tags/toolchain"},{"inline":true,"label":"cli","permalink":"/blog/posts/tags/cli"}],"readingTime":3.33,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kotlin-toolchain-013","title":"Kotlin Toolchain 0.13 \u2014 kotlin new \uba85\ub839\uacfc Android SDK \uc790\ub3d9 \uc124\uc815\uc73c\ub85c KMP \uc2dc\uc791\uc774 \uc26c\uc6cc\uc9c4\ub2e4","authors":["way"],"tags":["kotlin","android","kmp","toolchain","cli"]},"unlisted":false,"prevItem":{"title":"Cursor\xb7VS Code\uc5d0\uc11c IntelliJ\uae09 Kotlin \ubd84\uc11d\uc774 \uc628\ub2e4 \u2014 \\"Java and Kotlin by IntelliJ IDEA\\" 1.0","permalink":"/blog/posts/kotlin-lsp-extension-10"},"nextItem":{"title":"\uc548\ub4dc\ub85c\uc774\ub4dc \uac1c\ubc1c\uc790\uc5d0\uac8c \uc5f4\ub9b0 Gemini 4 Argon \u2014 \uc790\uac00 \ubcf5\uad6c \ube4c\ub4dc\uc640 AGSL \uc170\uc774\ub354","permalink":"/blog/posts/gemini-4-argon-android"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\nKotlin Toolchain **0.13**\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4. \uc774\uc81c JetBrains\ub294 \ub300\ubd80\ubd84\uc758 \uc2e0\uaddc Kotlin Multiplatform \ud504\ub85c\uc81d\ud2b8\uc5d0 Kotlin Toolchain \uc0ac\uc6a9\uc744 \uacf5\uc2dd \uad8c\uc7a5\ud569\ub2c8\ub2e4. \uc0c8 \ud504\ub85c\uc81d\ud2b8 \uc0dd\uc131 \uba85\ub839 `kotlin new`, IDE \uc784\ud3ec\ud2b8 \uc2dc Android SDK \uc790\ub3d9 \ud504\ub85c\ube44\uc800\ub2dd \ub4f1 \\"\ucc98\uc74c \uc2dc\uc791\\"\uc758 \ub9c8\ucc30\uc744 \uc904\uc774\ub294 \ubcc0\ud654\uac00 \ud575\uc2ec\uc785\ub2c8\ub2e4. Kotlin \ube14\ub85c\uadf8\uc758 \ubc1c\ud45c \uae00 \\"Start Your Next KMP App With Kotlin Toolchain 0.13\\"(2026\ub144 10\uc6d4)\uc744 \uc2e4\ubb34 \uad00\uc810\uc5d0\uc11c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- `kotlin new` \uba85\ub839\uc774 \uc0c8\ub85c \uc0dd\uacbc\uc2b5\ub2c8\ub2e4. Kotlin Multiplatform Wizard\uc640 \ube44\uc2b7\ud55c \ub300\ud654\ud615 \ud50c\ub85c\uc6b0\ub85c \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \ud0c0\uc785\uacfc \ud0c0\uae43 \ud50c\ub7ab\ud3fc\uc744 \uace0\ub974\uba74 \ud504\ub85c\uc81d\ud2b8\uac00 \ub9cc\ub4e4\uc5b4\uc9d1\ub2c8\ub2e4. \uae30\uc874 `kotlin init`\uc740 \uc720\uc9c0\ub418\uc9c0\ub9cc, \uc774\uc81c \ud604\uc7ac \ub514\ub809\ud130\ub9ac\uc5d0 \ubc14\ub85c \ud30c\uc77c\uc744 \uc0dd\uc131\ud558\ub294 \ub3d9\uc791\uc73c\ub85c \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4.\\n- **Android \uac1c\uc120:** \uc774\uc804\uc5d0\ub294 `kotlin build`\xb7`kotlin run`\uc744 \uc2e4\ud589\ud560 \ub54c\ub9cc Android SDK\uac00 \uc790\ub3d9 \uc124\uce58\ub410\uace0, IDE\uc5d0\uc11c \ud504\ub85c\uc81d\ud2b8\ub97c \uba3c\uc800 \uc5f4\uba74 SDK \ub204\ub77d\uc73c\ub85c \uc124\uc815 \uc624\ub958\uac00 \ub0ac\uc2b5\ub2c8\ub2e4. 0.13\ubd80\ud130\ub294 CLI\uc640 IDE \ub3d9\uc791\uc774 \ud1b5\uc77c\ub3fc **\ud504\ub85c\uc81d\ud2b8 \uc784\ud3ec\ud2b8 \uc2dc\uc810\uc5d0 \ubd80\uc871\ud55c Android SDK \ucef4\ud3ec\ub10c\ud2b8\ub97c \uc790\ub3d9\uc73c\ub85c \uc124\uce58**\ud569\ub2c8\ub2e4.\\n- namespace\xb7applicationId \uac80\uc99d\uc744 \uac15\ud654\ud588\uc2b5\ub2c8\ub2e4. `com.example.app` \uac19\uc740 \uc0d8\ud50c ID\uac00 \uadf8\ub300\ub85c \uc571\xb7\ub77c\uc774\ube0c\ub7ec\ub9ac \ube4c\ub4dc\uc5d0 \uc2e4\ub824 \ubc30\ud3ec\ub418\ub294 \uc2e4\uc218\ub97c \ub9c9\uc544\uc90d\ub2c8\ub2e4.\\n- IDE \uc5d0\ub514\ud130 \uc548\uc5d0\uc11c \uc2f1\ud06c \uc0c1\ud0dc\ub97c \ubcfc \uc218 \uc788\uac8c \ub410\uace0, Apple \ud50c\ub7ab\ud3fc\uc6a9 Swift Package Manager \uc758\uc874\uc131\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4(`swiftPackage` \uc120\uc5b8, `swiftPMImport` \uc811\ub450\uc0ac\ub85c import).\\n- \uba40\ud2f0\ud50c\ub7ab\ud3fc \ub77c\uc774\ube0c\ub7ec\ub9ac \ubc30\ud3ec \uc2dc Compose Resources\uc640 SwiftPM \uc758\uc874\uc131 \uba54\ud0c0\ub370\uc774\ud130\uac00 \ud568\uaed8 \ubc1c\ud589\ub418\uace0, \uc11c\ub4dc\ud30c\ud2f0 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\uc11c\ub3c4 Compose Resources\ub97c \uac00\uc838\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- Kotlin/Native \ucef4\ud30c\uc77c \uce90\uc2dc(KTC-5422)\ub85c \ub124\uc774\ud2f0\ube0c \uc758\uc874\uc131 \ube4c\ub4dc\uac00 \ube68\ub77c\uc84c\uc2b5\ub2c8\ub2e4. \ube4c\ub4dc\xb7\ud504\ub85c\uc81d\ud2b8\ub97c \uac00\ub85c\uc9c8\ub7ec \uce90\uc2dc\ub97c \uc7ac\uc0ac\uc6a9\ud558\uace0, \ud504\ub85c\uc81d\ud2b8 \ucf54\ub4dc\ub294 \ud30c\uc77c \ub2e8\uc704 \uce90\uc2dc\ub85c \ubc14\ub010 \ubd80\ubd84\ub9cc \ub2e4\uc2dc \ucef4\ud30c\uc77c\ud569\ub2c8\ub2e4.\\n- \uc5c5\ub370\uc774\ud2b8\ub294 \ud130\ubbf8\ub110\uc5d0\uc11c `kotlin update` \ud55c \uc904\uc774\uba74 \ub429\ub2c8\ub2e4. \ucd5c\uc2e0 \uae30\ub2a5\uc744 IDE\uc5d0\uc11c \uc4f0\ub824\uba74 IntelliJ IDEA 2026.2.3 \ub610\ub294 Android Studio Rabbit 1 | 2026.2.1 \uc774\uc0c1 + Kotlin Toolchain \ud50c\ub7ec\uadf8\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### Android \uac1c\ubc1c\uc790\uac00 \uccb4\uac10\ud558\ub294 \ubcc0\ud654 \ub450 \uac00\uc9c0\\n\\n\uccab\uc9f8, IDE \uc784\ud3ec\ud2b8 \uc2dc SDK \uc790\ub3d9 \uc124\uce58\uc785\ub2c8\ub2e4. \ud300\uc5d0 \uc0c8 \uba64\ubc84\uac00 \ub4e4\uc5b4\uc640\uc11c \ub808\ud3ec\ub97c \ucc98\uc74c \uc5f4\uc5c8\uc744 \ub54c \\"SDK\uac00 \uc5c6\uc5b4\uc694\\"\ub85c \uc2dc\uc791\ud558\ub358 \uc628\ubcf4\ub529\uc774 \uc870\uc6a9\ud574\uc9d1\ub2c8\ub2e4. \ube4c\ub4dc \uc804\uc5d0 SDK \ub9e4\ub2c8\uc800\ub97c \uc190\uc73c\ub85c \uc5ec\ub294 \ub2e8\uacc4\uac00 \ud558\ub098 \uc904\uc5b4\ub4ed\ub2c8\ub2e4.\\n\\n\ub458\uc9f8, \uc0d8\ud50c applicationId \uac80\uc99d\uc785\ub2c8\ub2e4. \ub370\ubaa8\ub85c \ub9cc\ub4e4\ub358 \ud504\ub85c\uc81d\ud2b8\uac00 \uc5b4\ub290 \ub0a0 \uadf8\ub300\ub85c \uc2a4\ud1a0\uc5b4\uc5d0 \uc62c\ub77c\uac00\ub294 \uc0ac\uace0\ub294 \uc0dd\uac01\ubcf4\ub2e4 \ud754\ud569\ub2c8\ub2e4. \uc774\uc81c `com.example.app` \uac19\uc740 \ud50c\ub808\uc774\uc2a4\ud640\ub354\uac00 \ube4c\ub4dc \uc0b0\ucd9c\ubb3c\uc5d0 \uc2e4\ub9ac\uba74 \uac80\uc99d\uc744 \uac78\uc5b4 \uc7a1\uc544\uc90d\ub2c8\ub2e4. \ub9b4\ub9ac\uc2a4 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\uc5d0 \\"applicationId \ud655\uc778\\"\uc744 \uc190\uc73c\ub85c \uc801\uc5b4\ub450\ub358 \ud300\uc774\ub77c\uba74, \uadf8 \ud55c \uc904\uc744 \ub3c4\uad6c\uac00 \ub300\uc2e0\ud574\uc90d\ub2c8\ub2e4.\\n\\n#### CLI \ub2e4\uc6b4\ub85c\ub4dc \uc9c4\ud589\ub960 \ud45c\uc2dc\\n\\nTUI\uc5d0 \ub2e4\uc6b4\ub85c\ub4dc \uc9c4\ud589\ub960 \ubc14\uac00 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4. JDK\xb7Android SDK \ucef4\ud3ec\ub10c\ud2b8\xb7iOS \ub7f0\ud0c0\uc784\xb7\ucef4\ud30c\uc77c\ub7ec\ub97c \ubc1b\uc744 \ub54c \\"\uba48\ucd98 \uac74\uc9c0 \ubc1b\ub294 \uac74\uc9c0\\"\ub97c \uad6c\ubd84\ud560 \uc218 \uc788\uac8c \ub410\uc2b5\ub2c8\ub2e4. CI \ub85c\uadf8\uc5d0\uc11c\ub3c4 \uc9c4\ud589 \uc0c1\ud669\uc744 \uc77d\uae30 \uc26c\uc6cc\uc9d1\ub2c8\ub2e4.\\n\\n#### \uc5d0\uc774\uc804\ud2b8 \uce5c\ud654 \uc124\uacc4\\n\\n\ubc1c\ud45c \uae00\uc5d0\uc11c \uac15\uc870\ud55c \ub300\ubaa9\uc774 \ud558\ub098 \ub354 \uc788\uc2b5\ub2c8\ub2e4. \uc790\ub3d9 \ud658\uacbd \uc124\uc815, \uc120\uc5b8\uc801 \uad6c\uc131, \uba85\ud655\ud55c \uc5d0\ub7ec \uba54\uc2dc\uc9c0\uac00 AI \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c\ub3c4 \uc774\uc0c1\uc801\uc778 \uae30\ubc18\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. Hot Reload MCP \uc11c\ubc84\uc640 Kotlin \uc5d0\uc774\uc804\ud2b8 \uc2a4\ud0ac(`npx skills add kotlin/kotlin-agent-skills`)\ub3c4 \uc81c\uacf5\ub429\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub294 Kotlin Toolchain\uc774 \uc2a4\ud0ac\uc744 \uc9c1\uc811 \ub0b4\uc7a5\ud560 \uacc4\ud68d\uc774\ub77c\uace0 \ud569\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c KMP \ud504\ub85c\uc81d\ud2b8\ub97c \ub9e1\uae30\ub294 \ud300\uc774\ub77c\uba74 \ud55c \ubc88 \uc0b4\ud3b4\ubcfc \ub9cc\ud55c \uc9c0\uc810\uc785\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5/\uc8fc\uc758\uc810\\n\\n- **\\"\uc2e0\uaddc \ud504\ub85c\uc81d\ud2b8\uc5d0 \uad8c\uc7a5\\"\uc774\uc9c0 \\"\uae30\uc874 \ud504\ub85c\uc81d\ud2b8 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uad8c\uc7a5\\"\uc774 \uc544\ub2d9\ub2c8\ub2e4.** JetBrains\ub3c4 \uba85\uc2dc\ud588\ub4ef, \uae30\uc874 Gradle \ud504\ub85c\uc81d\ud2b8\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc740 \uc544\uc9c1 \uacf5\ubc31\uc774 \uc788\uace0 \ud53c\ub4dc\ubc31\uc744 \ubaa8\uc73c\ub294 \ub2e8\uacc4\uc785\ub2c8\ub2e4. \uc6b4\uc601 \uc911\uc778 \uc571\uc744 \ub2f9\uc7a5 \uc62e\uae38 \ud544\uc694\ub294 \uc5c6\uc2b5\ub2c8\ub2e4.\\n- SwiftPM \uc9c0\uc6d0\uc740 Apple \ud50c\ub7ab\ud3fc \ubaa8\ub4c8(`kmp/lib`, `ios/app` \ub4f1)\uc5d0\uc11c\ub9cc \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4. Android \uc804\uc6a9 \ud504\ub85c\uc81d\ud2b8\ub77c\uba74 \uc774\ubc88 \ub9b4\ub9ac\uc2a4\uc758 \uccb4\uac10\uc740 SDK \uc790\ub3d9 \uc124\uce58\uc640 \uac80\uc99d \uac15\ud654\uac00 \uc804\ubd80\uc785\ub2c8\ub2e4.\\n- \ub124\uc774\ud2f0\ube0c \ucef4\ud30c\uc77c \uce90\uc2dc\ub294 `settings.kotlin.compileIncrementally` \uc124\uc815\uc744 \uc0ac\uc6a9\ud558\uace0, \ub514\ubc84\uadf8 \ubc14\uc774\ub108\ub9ac(\ube44\ucd5c\uc801\ud654) \ub300\uc0c1\uc5d0\uc11c \ub3d9\uc791\ud569\ub2c8\ub2e4. `.klib` \ucef4\ud30c\uc77c\uc740 \uc5ec\uc804\ud788 \uc804\uccb4 \ube4c\ub4dc\uc785\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc \uc608\uc2dc\\n\\n```yaml\\n# Apple \ud50c\ub7ab\ud3fc \ubaa8\ub4c8\uc5d0\uc11c SwiftPM \uc758\uc874\uc131 \uc120\uc5b8 (Kotlin Toolchain 0.13~)\\nproduct: ios/app\\n\\ndependencies:\\n  - swiftPackage:\\n      repository: \\"https://github.com/firebase/firebase-ios-sdk.git\\"\\n      version: \\"12.17.0\\"\\n      products: [ \\"FirebaseCore\\", \\"FirebaseFirestore\\", \\"FirebaseAnalytics\\" ]\\n```\\n\\n```kotlin\\n// app/src/app.kt \u2014 \uac00\uc838\uc628 Objective-C API \uc0ac\uc6a9\\nimport swiftPMImport.app.FIRAnalytics\\nimport swiftPMImport.app.FIRApp\\n\\nfun initAnalytics() {\\n    FIRApp.configure()\\n    FIRAnalytics.logEventWithName(\\"app_open\\", parameters = null)\\n}\\n```\\n\\niOS \ucabd\uc5d0\uc11c Firebase\ub97c \uc4f0\ub294 KMP \ud504\ub85c\uc81d\ud2b8\ub77c\uba74, \uc774\uc81c CocoaPods \uc5c6\uc774 \uc120\uc5b8\uc801 \uc124\uc815 \ud55c \uc904\ub85c iOS \ub124\uc774\ud2f0\ube0c SDK\ub97c \ub04c\uc5b4\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4. Android \ucabd \uc2e4\ubb34 \ud301 \ud558\ub098 \ub354: \uc0c8 KMP \ubaa8\ub4c8\uc744 \ub9cc\ub4e4 \ub54c `kotlin new`\ub85c \ubf08\ub300\ub97c \ubf51\uace0, \uccab \ube4c\ub4dc \uc804\uc5d0 `applicationId`\uac00 \uc0d8\ud50c \uac12\uc778\uc9c0 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \ub4e4\uc774\uba74 \uc704\uc5d0\uc11c \ub9d0\ud55c \uac80\uc99d\uacfc \uacb9\uacb9\uc774 \ubc29\uc5b4\uac00 \ub429\ub2c8\ub2e4.\\n\\n### \ucd9c\ucc98\\n\\n- [Start Your Next KMP App With Kotlin Toolchain 0.13 \u2014 Kotlin Blog (JetBrains, 2026\ub144 10\uc6d4)](https://blog.jetbrains.com/kotlin/2026/10/start-your-next-kmp-app-with-kotlin-toolchain-0-13/) \u2014 `kotlin new` \uba85\ub839, IDE \uc784\ud3ec\ud2b8 \uc2dc Android SDK \uc790\ub3d9 \ud504\ub85c\ube44\uc800\ub2dd, namespace/applicationId \uac80\uc99d, SwiftPM \uc9c0\uc6d0, \ub124\uc774\ud2f0\ube0c \ucef4\ud30c\uc77c \uce90\uc2dc, \ub85c\ub4dc\ub9f5"},{"id":"gemini-4-argon-android","metadata":{"permalink":"/blog/posts/gemini-4-argon-android","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-15-gemini-4-argon-android/index.mdx","source":"@site/blog/2026-10-15-gemini-4-argon-android/index.mdx","title":"\uc548\ub4dc\ub85c\uc774\ub4dc \uac1c\ubc1c\uc790\uc5d0\uac8c \uc5f4\ub9b0 Gemini 4 Argon \u2014 \uc790\uac00 \ubcf5\uad6c \ube4c\ub4dc\uc640 AGSL \uc170\uc774\ub354","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud55c\ud22c \uc571 \uac1c\ubc1c\uc790 way\uc785\ub2c8\ub2e4.","date":"2026-10-15T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"gemini","permalink":"/blog/posts/tags/gemini"},{"inline":true,"label":"ai","permalink":"/blog/posts/tags/ai"},{"inline":true,"label":"antigravity","permalink":"/blog/posts/tags/antigravity"},{"inline":true,"label":"compose","permalink":"/blog/posts/tags/compose"}],"readingTime":3.15,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"gemini-4-argon-android","title":"\uc548\ub4dc\ub85c\uc774\ub4dc \uac1c\ubc1c\uc790\uc5d0\uac8c \uc5f4\ub9b0 Gemini 4 Argon \u2014 \uc790\uac00 \ubcf5\uad6c \ube4c\ub4dc\uc640 AGSL \uc170\uc774\ub354","authors":["way"],"tags":["android","gemini","ai","antigravity","compose"]},"unlisted":false,"prevItem":{"title":"Kotlin Toolchain 0.13 \u2014 kotlin new \uba85\ub839\uacfc Android SDK \uc790\ub3d9 \uc124\uc815\uc73c\ub85c KMP \uc2dc\uc791\uc774 \uc26c\uc6cc\uc9c4\ub2e4","permalink":"/blog/posts/kotlin-toolchain-013"},"nextItem":{"title":"SQL LIKE \'%\uac80\uc0c9\uc5b4%\'\uac00 \uc571\uc744 \ub290\ub9ac\uac8c \ud55c\ub2e4 \u2014 Room @Fts4\ub85c \uac80\uc0c9 9.4\ubc30 \ube60\ub974\uac8c","permalink":"/blog/posts/room-fts4-search"}},"content":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c [\ud55c\ud22c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartpension&hl=ko) \uc571 \uac1c\ubc1c\uc790 way\uc785\ub2c8\ub2e4.\\n\\n\uad6c\uae00\uc774 10\uc6d4 13\uc77c Android Developers Blog\uc5d0\uc11c \ucd5c\uc2e0 \ud50c\ub798\uadf8\uc2ed \ubaa8\ub378 **Gemini 4 Argon**\uc744 \uc548\ub4dc\ub85c\uc774\ub4dc \uac1c\ubc1c \ud45c\uba74\uc5d0 \uac1c\ubc29\ud55c\ub2e4\uace0 \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4. \uc9c0\ub09c\uc8fc\uc5d0 \ub2e4\ub918\ub358 Android CLI/\ub514\ubc14\uc774\uc2a4 \uc2a4\ud2b8\ub9ac\ubc0d, BYOA(\uc6d0\ud558\ub294 \uc5d0\uc774\uc804\ud2b8 \uc4f0\uae30) \ud750\ub984\uc758 \uc5f0\uc7a5\uc120\uc774\ub77c \ud568\uaed8 \ubcf4\uba74 \uc88b\uc2b5\ub2c8\ub2e4. \ubaa8\ub378 \uc790\uccb4\ubcf4\ub2e4 \\"\uc5d0\uc774\uc804\ud2b8\uac00 \ube4c\ub4dc\ub97c \uc2a4\uc2a4\ub85c \uace0\uce58\uace0, \uc170\uc774\ub354\uae4c\uc9c0 \uc9dc\uc900\ub2e4\\"\ub294 \ubd80\ubd84\uc5d0 \uc8fc\ubaa9\ud574\uc11c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- **\uc811\uadfc \uacbd\ub85c 3\uac00\uc9c0**: \u2460 Google Antigravity(AI Ultra \uad6c\ub3c5, \ub370\uc2a4\ud06c\ud1b1 \uc571\xb7CLI\xb7Android Studio Canary \ub0b4) \u2461 Android Studio(Gemini API \uc720\ub8cc \ud2f0\uc5b4) \u2462 Google AI Studio(Playground/Build, AI Ultra \ub610\ub294 Gemini API \uc720\ub8cc \ud2f0\uc5b4)\\n- **\ud074\ub77c\uc774\uc5b8\ud2b8 \uc778\uc571 AI**: Firebase AI Logic \uacbd\uc720\ub85c Gemini API \uc720\ub8cc \ud2f0\uc5b4 \uac1c\ubc1c\uc790\uac00 \uc571 \uc548\uc5d0\uc11c Gemini 4 Argon\uc744 \uc9c1\uc811 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- **Self-Healing Build Loops**: \ube4c\ub4dc \uc2e4\ud328 \uc2dc Antigravity \ud558\ub124\uc2a4\uac00 Gradle \ub370\ubaac\xb7Kotlin \ucef4\ud30c\uc77c\ub7ec \ub85c\uadf8\ub97c \ubaa8\ub378\uc5d0 \uadf8\ub300\ub85c \ud53c\ub4dc\ubc31\ud558\uace0, \uadfc\ubcf8 \uc6d0\uc778\uc744 \ubc18\ubcf5 \uc9c4\ub2e8\ud574 \uc218\uc815\uc548\uc744 \ub0c5\ub2c8\ub2e4. \ud3b8\uc9d1 \ub77c\uc6b4\ub4dc\ub9c8\ub2e4 \uac00\uc124\uc744 \uc77c\uad00\ub418\uac8c \uc720\uc9c0\ud558\uace0 AST \uc778\uc9c0\ub97c \ud65c\uc6a9\ud574 \ud45c\uba74 \uc99d\uc0c1\uc774 \uc544\ub2cc \uc9c4\uc9dc \uc6d0\uc778\uc5d0 \ub3c4\ub2ec\ud558\ub3c4\ub85d \ud6c8\ub828\ub410\ub2e4\ub294 \uc124\uba85\uc785\ub2c8\ub2e4.\\n- **Compose \uc170\uc774\ub354 \uc0dd\uc131**: AGSL(Android Graphics Shading Language)\uc744 Compose `Modifier.graphicsLayer`\ub098 \uc170\uc774\ub354 \ube0c\ub7ec\uc2dc\uc5d0 \uc9c1\uc811 \uc791\uc131\ud569\ub2c8\ub2e4. 120fps Compose \uc560\ub2c8\uba54\uc774\uc158\uacfc \ud568\uaed8 \ub3c4\ub294 \uacbd\ub7c9 GPU \uc170\uc774\ub354(\ud504\ub85c\uc2a4\ud2b8\ub4dc \uae00\ub798\uc2a4\xb7\ub3d9\uc801 \uc870\uba85\xb7\ud30c\ubb38 \ub4f1)\ub97c \ubca1\ud130\xb7\ub80c\ub354\ub9c1 \uc218\ud559\uae4c\uc9c0 \ucc98\ub9ac\ud574 \ubf51\uc544\ub0b8\ub2e4\uace0 \ud569\ub2c8\ub2e4.\\n- \uc778\ud2b8\ub85c \uac00\uaca9 \uc801\uc6a9\uc740 **2026\ub144 11\uc6d4 30\uc77c\uae4c\uc9c0**\uc785\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n\uc9c0\uae08\uae4c\uc9c0 \uc5d0\uc774\uc804\ud2b8 \ucf54\ub529\uc740 \\"\ucf54\ub4dc \uc790\ub3d9\uc644\uc131\uc758 \uc5f0\uc7a5\\"\uc5d0 \uac00\uae4c\uc6e0\uc2b5\ub2c8\ub2e4. \uc774\ubc88 \ubc1c\ud45c\uac00 \ub9d0\ud558\ub294 \ubc29\ud5a5\uc740 **\ud074\ub85c\uc988\ub4dc \ub8e8\ud504 \uc2e4\ud589**\uc785\ub2c8\ub2e4. \ube4c\ub4dc \u2192 \uc2e4\ud328 \ub85c\uadf8 \uc218\uc9d1 \u2192 \uc6d0\uc778 \uc9c4\ub2e8 \u2192 \uc218\uc815 \u2192 \uc7ac\ube4c\ub4dc\ub97c \uc0ac\ub78c\uc774 \uc544\ub2c8\ub77c \ud558\ub124\uc2a4+\ubaa8\ub378\uc774 \ub3cc\ub9ac\ub294 \uad6c\uc870\uc8e0. Gradle \ub370\ubaac\uacfc Kotlin \ucef4\ud30c\uc77c\ub7ec\uc758 \uc5d0\ub7ec \uc2a4\ud2b8\ub9bc\uc744 \uadf8\ub300\ub85c \uba39\ub294\ub2e4\ub294 \uc810\uc774 \ud575\uc2ec\uc785\ub2c8\ub2e4. \ub85c\uadf8\ub97c \uc77d\ub294 \uc0ac\ub78c\uc774 \uc544\ub2c8\ub77c \ube4c\ub4dc \uc2dc\uc2a4\ud15c\uc744 \uc77d\ub294 \uc5d0\uc774\uc804\ud2b8\uc778 \uc148\uc785\ub2c8\ub2e4.\\n\\nUI \ucabd\ub3c4 \ub208\uc5d0 \ub755\ub2c8\ub2e4. Compose \uc170\uc774\ub354\ub294 \uc2e4\ubb34\uc5d0\uc11c \uc9c4\uc785 \uc7a5\ubcbd\uc774 \ub192\uc740 \uc601\uc5ed\uc778\ub370(AGSL \ubb38\ubc95 + \ub80c\ub354\ub9c1 \uc218\ud559 + \uc131\ub2a5 \uc608\uc0b0), \ubaa8\ub378\uc774 \uc774\ub97c \\"\ud504\ub85c\ub355\uc158\uae09\\"\uc73c\ub85c \ubf51\uc544\ub0b8\ub2e4\ub294 \uc8fc\uc7a5\uc785\ub2c8\ub2e4. 120fps \uc560\ub2c8\uba54\uc774\uc158\uacfc \uacf5\uc874\ud558\ub294 \uacbd\ub7c9 \uc170\uc774\ub354\ub77c\ub294 \ud45c\ud604\uc5d0\uc11c \ud0c0\uae43\uc774 \uba85\ud655\ud569\ub2c8\ub2e4. \uac80\uc99d\uc740 \uc9c1\uc811 \ud574\ubd10\uc57c\uaca0\uc9c0\ub9cc, \uc170\uc774\ub354 \ube0c\ub7ec\uc2dc\uae4c\uc9c0 \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \ub9e1\uae30\ub294 \uc6cc\ud06c\ud50c\ub85c\uac00 \uc0dd\uae34\ub2e4\ub294 \uac74 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ud300\uc5d0\uac90 \uc758\ubbf8 \uc788\ub294 \ubcc0\ud654\uc785\ub2c8\ub2e4.\\n\\n\ud130\ubbf8\ub110 \uc5d0\uc774\uc804\ud2b8 \uc5f0\uacb0\uc740 \uacf5\uc2dd Android CLI \ud50c\ub7ec\uadf8\uc778\uc774 \ub9e1\uc2b5\ub2c8\ub2e4. `android init` \ud55c \uc904\uc774\uba74 \uc5b4\ub5a4 \ud130\ubbf8\ub110 \uc5d0\uc774\uc804\ud2b8\ub4e0 \ub85c\uceec Android \ub3c4\uad6c\uc640 \uc5f0\uacb0\ub418\uace0, Antigravity\ub77c\uba74 \ud50c\ub7ec\uadf8\uc778 \uc124\uce58\ub85c \ub05d\ub0a9\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **\ube4c\ub4dc \ub85c\uadf8\uac00 \uace7 \uc5d0\uc774\uc804\ud2b8\uc758 \uc785\ub825\uc785\ub2c8\ub2e4.** Self-Healing\uc774 \uc704\ub825\uc744 \ub0b4\ub824\uba74 \ube4c\ub4dc \uc2e4\ud328 \ub85c\uadf8\uac00 \uc798 \uc77d\ud600\uc57c \ud569\ub2c8\ub2e4. \ub09c\ub3c5\ud654\ub41c \uba40\ud2f0\ubaa8\ub4c8 \ube4c\ub4dc\uc5d0\uc11c \uc5d0\uc774\uc804\ud2b8\uac00 \uc6d0\uc778\uc5d0 \ub2ff\uc73c\ub824\uba74, \uc9c0\uae08\ubd80\ud130\ub77c\ub3c4 Gradle \ube4c\ub4dc \uc2a4\ud06c\ub9bd\ud2b8\uc640 \uc5d0\ub7ec \uba54\uc2dc\uc9c0\ub97c \uc0ac\ub78c\uc774 \uc77d\uc744 \uc218 \uc788\uac8c \uc815\ub9ac\ud574 \ub450\ub294 \uac8c \uc774\ub4dd\uc785\ub2c8\ub2e4.\\n- **\ube44\uc6a9 \uad6c\uc870\ub97c \ud655\uc778\ud558\uc138\uc694.** Antigravity\ub294 AI Ultra \uad6c\ub3c5 \uc804\uc81c, API \uacbd\ub85c\ub294 Gemini API \uc720\ub8cc \ud2f0\uc5b4 \uc804\uc81c\uc785\ub2c8\ub2e4. \uc778\ud2b8\ub85c \uac00\uaca9(2026-11-30\uae4c\uc9c0) \uc774\ud6c4 \uc815\uac00\ub97c \ubaa8\ub974\uba74 \ud300 \ub3c4\uc785 \ud310\ub2e8\uc774 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ub3c4\uc785 \uc804\uc5d0 Console\uc5d0\uc11c \uc2e4\uc81c \uacfc\uae08\uc744 \uba3c\uc800 \ud655\uc778\ud558\uc138\uc694.\\n- **\uc170\uc774\ub354 \ucf54\ub4dc\ub294 \ub9ac\ubdf0\uac00 \ud544\uc218\uc785\ub2c8\ub2e4.** \\"\ud504\ub85c\ub355\uc158\uae09\\"\uc774\ub77c\ub294 \ud45c\ud604\uc740 \ubaa8\ub378 \ubca4\ub354\uc758 \uc8fc\uc7a5\uc77c \ubfd0, AGSL \uc170\uc774\ub354\ub294 GPU\xb7\ub514\ubc14\uc774\uc2a4\ubcc4\ub85c \ub3d9\uc791\uc774 \ub2ec\ub77c \uc2e4\uae30 \uac80\uc99d \uc5c6\uc774\ub294 \ubabb \uc501\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8\uac00 \uc9e0 \uc170\uc774\ub354\ub294 \ucd08\uc548\uc73c\ub85c \ubcf4\uace0 \ud504\ub808\uc784 \ud0c0\uc784\xb7\ubc30\ud130\ub9ac\ubd80\ud130 \uc7ac\uc138\uc694.\\n- **Firebase AI Logic \uacbd\ub85c\ub294 \uc778\uc571 \uae30\ub2a5\uc6a9\uc785\ub2c8\ub2e4.** \uac1c\ubc1c \uc6cc\ud06c\ud50c\ub85c(\ube4c\ub4dc \ubcf5\uad6c\xb7\ucf54\ub4dc \uc0dd\uc131)\uc640 \uc571 \ub0b4 AI \uae30\ub2a5(\uc0ac\uc6a9\uc790 \ub300\uba74)\uc740 \uc811\uadfc \uacbd\ub85c\uac00 \ub2e4\ub985\ub2c8\ub2e4. \ud300\uc5d0\uc11c \ub458\uc744 \ud63c\ub3d9\ud558\uba74 \uacfc\uae08\xb7\uad8c\ud55c \uc124\uacc4\uac00 \uaf2c\uc785\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \uc801\uc6a9\ud560 \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uc77c\ub2e8 \ud130\ubbf8\ub110 \uc5d0\uc774\uc804\ud2b8\uc5d0 Android CLI\ub97c \ubd99\uc774\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud574 \ubcfc \ub9cc\ud569\ub2c8\ub2e4. \ubc1c\ud45c\uc5d0\uc11c \uc548\ub0b4\ud55c \uba85\ub839 \uadf8\ub300\ub85c\uc785\ub2c8\ub2e4.\\n\\n```bash\\n# \uc5b4\ub5a4 \ud130\ubbf8\ub110 \uc5d0\uc774\uc804\ud2b8\uc5d0\uc11c\ub4e0: \ub85c\uceec Android \ub3c4\uad6c\uc640 \uc5f0\uacb0\\nandroid init\\n\\n# Antigravity\ub97c \uc4f4\ub2e4\uba74: \uacf5\uc2dd Android CLI \ud50c\ub7ec\uadf8\uc778 \uc124\uce58\\nagy plugin install android-cli-plugin\\n```\\n\\nFirebase AI Logic\uc73c\ub85c \uc778\uc571\uc5d0 \ubd99\uc77c \ub54c\ub294 \ubaa8\ub378 \uc120\ud0dd\ub9cc \uc0c8 \ubaa8\ub378\ub85c \ubc14\uafb8\ub294 \uad6c\uc870\ub77c, \uae30\uc874 Vertex AI / Gemini Developer API \uc5f0\ub3d9 \ucf54\ub4dc\uc758 \ubaa8\ub378\uba85 \uad50\uccb4 \uc218\uc900\uc5d0\uc11c \uac80\ud1a0\uac00 \uac00\ub2a5\ud569\ub2c8\ub2e4. \uc815\ud655\ud55c \ubaa8\ub378 \uc2dd\ubcc4\uc790\ub294 Firebase AI Logic \ubb38\uc11c\ub97c \ud655\uc778\ud558\uace0, \ub9b4\ub9ac\uc2a4 \uc9c1\ud6c4\uc5d0\ub294 SDK \uc5c5\ub370\uc774\ud2b8\uac00 \ud544\uc694\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n\uc0d8\ud50c \ud504\ub85c\uc81d\ud2b8\ub3c4 \ud568\uaed8 \uacf5\uac1c\ub410\uc73c\ub2c8, \uc5d0\uc774\uc804\ud2b8 \uc6cc\ud06c\ud50c\ub85c\ub97c \ud300\uc5d0 \ub3c4\uc785\ud558\uae30 \uc804\uc5d0 \ud035\uc2a4\ud0c0\ud2b8\ub85c \uac10\uc744 \uc7a1\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n### \ucd9c\ucc98\\n\\n- [Bringing our latest frontier model to Android Developers](https://developer.android.com/blog/posts/bringing-gemini-4-argon-to-android-agentic-engineering-antigravity-cli) \u2014 Jason Buchel, Android Developers Blog, 2026\ub144 10\uc6d4 13\uc77c (\uc811\uadfc \uacbd\ub85c\xb7Self-Healing Build Loops\xb7AGSL \uc170\uc774\ub354\xb7\uc778\ud2b8\ub85c \uac00\uaca9 2026-11-30 \uc0ac\uc2e4 \uc778\uc6a9)\\n- [gemini-4-antigravity-quickstart](https://github.com/android-samples/gemini-4-antigravity-quickstart) \u2014 android-samples, \ud035\uc2a4\ud0c0\ud2b8 \uc0d8\ud50c"},{"id":"room-fts4-search","metadata":{"permalink":"/blog/posts/room-fts4-search","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-15-room-fts4-search/index.mdx","source":"@site/blog/2026-10-15-room-fts4-search/index.mdx","title":"SQL LIKE \'%\uac80\uc0c9\uc5b4%\'\uac00 \uc571\uc744 \ub290\ub9ac\uac8c \ud55c\ub2e4 \u2014 Room @Fts4\ub85c \uac80\uc0c9 9.4\ubc30 \ube60\ub974\uac8c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud55c\ud22c \uc571 \uac1c\ubc1c\uc790 way\uc785\ub2c8\ub2e4.","date":"2026-10-15T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"room","permalink":"/blog/posts/tags/room"},{"inline":true,"label":"sqlite","permalink":"/blog/posts/tags/sqlite"},{"inline":true,"label":"search","permalink":"/blog/posts/tags/search"},{"inline":true,"label":"performance","permalink":"/blog/posts/tags/performance"}],"readingTime":3.39,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"room-fts4-search","title":"SQL LIKE \'%\uac80\uc0c9\uc5b4%\'\uac00 \uc571\uc744 \ub290\ub9ac\uac8c \ud55c\ub2e4 \u2014 Room @Fts4\ub85c \uac80\uc0c9 9.4\ubc30 \ube60\ub974\uac8c","authors":["way"],"tags":["android","room","sqlite","search","performance"]},"unlisted":false,"prevItem":{"title":"\uc548\ub4dc\ub85c\uc774\ub4dc \uac1c\ubc1c\uc790\uc5d0\uac8c \uc5f4\ub9b0 Gemini 4 Argon \u2014 \uc790\uac00 \ubcf5\uad6c \ube4c\ub4dc\uc640 AGSL \uc170\uc774\ub354","permalink":"/blog/posts/gemini-4-argon-android"},"nextItem":{"title":"Compose\uc5d0\uc11c Flow \uc218\uc9d1\uc758 \uc9c4\ud654 \u2014 collectAsState()\uc5d0\uc11c collectAsStateWithLifecycle()\uae4c\uc9c0","permalink":"/blog/posts/flow-collection-lifecycle"}},"content":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c [\ud55c\ud22c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartpension&hl=ko) \uc571 \uac1c\ubc1c\uc790 way\uc785\ub2c8\ub2e4.\\n\\n\uc624\ud504\ub77c\uc778 \uac80\uc0c9(\uc885\ubaa9 \uba54\ubaa8, \uacf5\uc9c0 \ubaa9\ub85d, \ucd5c\uadfc \ubcf8 \uc0c1\ud488 \ub4f1)\uc744 \ub85c\uceec DB\uc5d0 `LIKE \'%\ucffc\ub9ac%\'`\ub85c \uad6c\ud604\ud55c \uacbd\ud5d8, \ub2e4\ub4e4 \ud55c \ubc88\ucbe4 \uc788\uc744 \uac81\ub2c8\ub2e4. \uac1c\ubc1c \uc911\uc5d0\ub294 \ub354\ubbf8 \ub370\uc774\ud130 \uba87\uc2ed \uac74\uc73c\ub85c 0.1\ucd08\ub3c4 \uc548 \uac78\ub824\uc11c \\"\ub41c\ub2e4\\"\uace0 \ub118\uc5b4\uac00\uae30 \uc27d\uc2b5\ub2c8\ub2e4. 10\uc6d4 ProAndroidDev\uc5d0 \uc62c\ub77c\uc628 \uae00 \\"Scaling Android Search: Room @Fts4 vs SQL LIKE\\"\uac00 \uc774 \uc548\uc77c\ud568\uc744 \uc22b\uc790\ub85c \uae68\uc90d\ub2c8\ub2e4. 5,000\uac74 \uae30\uc900\uc73c\ub85c LIKE\ub294 63.8ms, FTS4\ub294 6.8ms \u2014 9.4\ubc30 \ucc28\uc774\uc785\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- \uac80\uc0c9\uc5b4 \uc55e\uc5d0\ub3c4 `%`\ub97c \ubd99\uc774\ub294 \uc21c\uac04(`LIKE \'%\uac80\uc0c9\uc5b4%\'`), SQLite\uc758 B-Tree \uc778\ub371\uc2a4\ub294 \uc644\uc804\ud788 \ubb34\ub825\ud654\ub418\uace0 **\uc804\uccb4 \ud14c\uc774\ube14 \uc2a4\uce94**\uc73c\ub85c \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4.\\n- \uae00\uc4f4\uc774\uc758 \uc2e4\uce21\uc5d0\uc11c 2,000\uac74\ub9cc \ub3fc\ub3c4 LIKE\ub294 \uc57d 30ms\ub85c 60Hz \ud504\ub808\uc784 \uc608\uc0b0(16.6ms)\uc744 \ud6cc\uca4d \ub118\uacbc\uace0, 5,000\uac74\uc5d0\uc11c\ub294 FTS4 \ub300\ube44 9.4\ubc30 \ub290\ub838\uc2b5\ub2c8\ub2e4.\\n- Room\uc758 `@Fts4` + `contentEntity` \ud328\ud134\uc744 \uc4f0\uba74 \ub370\uc774\ud130\ub97c \uc911\ubcf5 \uc800\uc7a5\ud558\uc9c0 \uc54a\uace0 **\uc5ed\uc778\ub371\uc2a4(inverted index)\ub9cc \ubcc4\ub3c4 \uac00\uc0c1 \ud14c\uc774\ube14\uc5d0** \uc720\uc9c0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud2b8\ub9ac\uac70\uac00 \uc6d0\ubcf8 \ud14c\uc774\ube14\uc758 INSERT/UPDATE/DELETE\ub97c \uc778\ub371\uc2a4\uc5d0 \uc790\ub3d9 \ubc18\uc601\ud569\ub2c8\ub2e4.\\n\\n### \uc65c LIKE\uac00 \ub290\ub9b0\uc9c0\\n\\nB-Tree \uc778\ub371\uc2a4\ub294 \\"\uc811\ub450\uc0ac\\"\ub97c \uc54c \ub54c\ub9cc \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4. `WHERE sender LIKE \'alice%\'`\ub294 \uc778\ub371\uc2a4\ub97c \ud0c0\uc9c0\ub9cc, \uc2e4\uc81c \uac80\uc0c9 UI\ub294 \uc911\uac04 \ub9e4\uce6d\uc774 \ud544\uc694\ud558\ub2c8 `WHERE body LIKE \'%architecture%\'` \ud615\ud0dc\uac00 \ub429\ub2c8\ub2e4. \uc120\ud589 \uc640\uc77c\ub4dc\uce74\ub4dc\uac00 \ub4e4\uc5b4\uac00\ub294 \uc21c\uac04 \uc635\ud2f0\ub9c8\uc774\uc800\ub294 \uc778\ub371\uc2a4\ub97c \ubc84\ub9ac\uace0 \ubaa8\ub4e0 \ud589\uc744 \ubc14\uc774\ud2b8 \ub2e8\uc704\ub85c \ud6d1\uc2b5\ub2c8\ub2e4. 2,000\ud1b5\uc758 \uc774\uba54\uc77c\uc5d0 \ubcf8\ubb38 \ud3c9\uade0 1,500\ub2e8\uc5b4\ub77c\uba74, \ud0a4\uc2a4\ud2b8\ub85c\ud06c \ud55c \ubc88\uc5d0 \ucd5c\ub300 300\ub9cc \ub2e8\uc5b4\ub97c \ubb38\uc790 \ub2e8\uc704\ub85c \ube44\uad50\ud558\ub294 \uc148\uc785\ub2c8\ub2e4.\\n\\n\uac8c\ub2e4\uac00 LIKE\ub294 \\"\uba4d\uccad\ud569\ub2c8\ub2e4\\". \ub2e8\uc5b4 \uacbd\uacc4\ub97c \ubaa8\ub985\ub2c8\ub2e4(`\\"cat\\"` \uac80\uc0c9\uc5d0 `\\"catalog\\"`\xb7`\\"scatter\\"`\uae4c\uc9c0 \uac78\ub9bd\ub2c8\ub2e4). \uc5b4\uac04 \ucd94\ucd9c\uc774 \uc548 \ub429\ub2c8\ub2e4(`\\"optimize\\"`\ub85c `\\"optimized\\"`\ub97c \ubabb \ucc3e\uc2b5\ub2c8\ub2e4). \uad00\ub828\ub3c4 \uc21c\uc704\uac00 \uc5c6\uc2b5\ub2c8\ub2e4(\uc81c\ubaa9 \ub9e4\uce6d\uacfc \ubcf8\ubb38 4\ubc88\uc9f8 \ubb38\ub2e8 \ub9e4\uce6d\uc774 \ub3d9\uae09\uc785\ub2c8\ub2e4).\\n\\n### FTS4\uac00 \ub2e4\ub978 \uc774\uc720: \uc5ed\uc778\ub371\uc2a4\\n\\nFTS4\ub294 \ucffc\ub9ac \uc2dc\uc810\uc774 \uc544\ub2c8\ub77c **INSERT \uc2dc\uc810**\uc5d0 \uc77c\uc744 \ud569\ub2c8\ub2e4. \ud1a0\ud06c\ub098\uc774\uc800\uac00 \ud14d\uc2a4\ud2b8\ub97c \ub2e8\uc5b4\ub85c \ucabc\uac1c\uace0(\ud1a0\ud070\ud654), \ub300\uc18c\ubb38\uc790\ub97c \uc815\uaddc\ud654\ud558\uace0, \\"\ub2e8\uc5b4 \u2192 \ubb38\uc11c ID \ubaa9\ub85d\\"\uc774\ub77c\ub294 \uc5ed\uc778\ub371\uc2a4\ub97c \ub9cc\ub4ed\ub2c8\ub2e4.\\n\\n```\\nToken        | DocIDs (Posting List)\\narchitecture | [1, 14, 108, 492]\\nbenchmark    | [1, 7, 22, 108, 305]\\n```\\n\\n`MATCH \'benchmark*\'` \uac19\uc740 \ucffc\ub9ac\uac00 \ub4e4\uc5b4\uc624\uba74 FTS4\ub294 \ud1a0\ud070 \ub515\uc154\ub108\ub9ac\uc5d0\uc11c \ub2e8\uc5b4\ub97c \ucc3e\uc544 docid \ubaa9\ub85d\uc744 \ubc14\ub85c \ubf51\uc544\ub0c5\ub2c8\ub2e4. \uad00\uacc4\uc5c6\ub294 \ud14d\uc2a4\ud2b8 \ud55c \ubc14\uc774\ud2b8\ub3c4 \uc548 \uc77d\uc2b5\ub2c8\ub2e4. \ud589\uc774 100\uac1c\ub4e0 10\ub9cc \uac1c\ub4e0 \uc870\ud68c\ub294 \ubc00\ub9ac\ucd08 \ub2e8\uc704\ub85c \ub05d\ub0a9\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **LIKE\ub294 \ud504\ub85c\ud1a0\ud0c0\uc785\uc6a9\uc785\ub2c8\ub2e4.** \uc0ac\ub78c \ub9d0\uc774 \ub4e4\uc5b4\uac00\ub294 \ud14d\uc2a4\ud2b8 \uac80\uc0c9(\uba54\uc2dc\uc9c0\xb7\ubb38\uc11c\xb7\uba54\ubaa8\xb7\uc0c1\ud488 \uce74\ud0c8\ub85c\uadf8)\uc774\uba74, \ub370\uc774\ud130\uac00 \uc218\ucc9c \uac74\uc73c\ub85c \uc790\ub77c\uae30 \uc804\uc5d0 FTS\ub85c \uc62e\uae30\ub294 \uac8c \ub9de\uc2b5\ub2c8\ub2e4.\\n- **\uc4f0\uae30 \ube44\uc6a9\uc740 \uc788\uc2b5\ub2c8\ub2e4.** FTS \ud14c\uc774\ube14\uc740 INSERT/UPDATE \ub54c\ub9c8\ub2e4 \uc778\ub371\uc2a4\ub97c \uac31\uc2e0\ud558\ub2c8, \uc4f0\uae30\uac00 \ube48\ubc88\ud558\uace0 \uc77d\uae30\uac00 \ub4dc\ubb38 \uc6cc\ud06c\ub85c\ub4dc\ub77c\uba74 \uc774\ub4dd\uc774 \uc904\uc5b4\ub4ed\ub2c8\ub2e4. \uc4f0\uae30/\uc77d\uae30 \ube44\uc728\uc744 \ubcf4\uace0 \ud310\ub2e8\ud558\uc138\uc694.\\n- **\ucffc\ub9ac \uc704\uc0dd\uc774 \ud544\uc218\uc785\ub2c8\ub2e4.** `MATCH`\uc5d0 \uc0ac\uc6a9\uc790 \uc785\ub825\uc744 \uadf8\ub300\ub85c \ub123\uc73c\uba74 \ub530\uc634\ud45c \uac19\uc740 \ud2b9\uc218\ubb38\uc790\uac00 \ucffc\ub9ac \ubb38\ubc95\uc744 \uae68\ub728\ub9bd\ub2c8\ub2e4. \uc785\ub825\uc5d0\uc11c \ub530\uc634\ud45c\ub97c \uc81c\uac70\ud558\uace0, as-you-type \uac80\uc0c9\uc744 \uc704\ud574 \ud1a0\ud070\ub9c8\ub2e4 \uc811\ubbf8\uc0ac `*`\ub97c \ubd99\uc774\ub294 sanitize \ud568\uc218\ub97c \ub530\ub85c \ub450\uc138\uc694.\\n- **\ud55c\uad6d\uc5b4\ub294 \ud1a0\ud06c\ub098\uc774\uc800\ub97c \uace0\ub974\uc138\uc694.** FTS4 \uae30\ubcf8 \ud1a0\ud06c\ub098\uc774\uc800(simple)\ub294 \uacf5\ubc31 \uae30\uc900\uc774\ub77c \ud55c\uad6d\uc5b4 \uc870\uc0ac \ubd99\uc740 \ub2e8\uc5b4(\\"\uac80\uc0c9\uc5b4\ub97c\\")\ub294 \ud1a0\ud070 \ud558\ub098\uac00 \ub429\ub2c8\ub2e4. \uc601\uc5b4 \uc704\uc8fc \uc571\uc774 \uc544\ub2c8\ub77c\uba74 `unicode61` \uacc4\uc5f4 \ud1a0\ud06c\ub098\uc774\uc800\ub85c \ubc14\uafb8\uac70\ub098, \ud615\ud0dc\uc18c \ubd84\uc11d\uc774 \ud544\uc694\ud558\uba74 \ubcc4\ub3c4 \ud1a0\ud06c\ub098\uc774\uc800\ub97c \uac80\ud1a0\ud574\uc57c \ud569\ub2c8\ub2e4. Porter stemmer\ub3c4 \uc601\uc5b4\uc6a9\uc774\ub77c\ub294 \uc810\uc744 \uc78a\uc9c0 \ub9c8\uc138\uc694.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \uc801\uc6a9\ud560 \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uc6d0\ubcf8 \ud14c\uc774\ube14\uc740 \uadf8\ub300\ub85c \ub450\uace0, \uac80\uc0c9\uc6a9 FTS \uac00\uc0c1 \ud14c\uc774\ube14\uc744 `contentEntity`\ub85c \ubd99\uc774\ub294 \ud328\ud134\uc774 \ud45c\uc900\uc785\ub2c8\ub2e4.\\n\\n```kotlin\\n@Entity(tableName = \\"notices\\")\\ndata class NoticeEntity(\\n    @PrimaryKey(autoGenerate = true) val id: Long = 0,\\n    val title: String,\\n    val body: String,\\n    val pinned: Boolean = false,\\n)\\n\\n@Entity(tableName = \\"notices_fts\\")\\n@Fts4(contentEntity = NoticeEntity::class)\\ndata class NoticeFtsEntity(\\n    val title: String,\\n    val body: String,\\n)\\n```\\n\\n`contentEntity`\ub97c \uc9c0\uc815\ud558\uba74 FTS \ud14c\uc774\ube14\uc740 \uc5ed\uc778\ub371\uc2a4 \uad6c\uc870\ub9cc \uac16\uace0, \uc2e4\uc81c \ud14d\uc2a4\ud2b8\ub294 \uc6d0\ubcf8 `notices` \ud14c\uc774\ube14\uc5d0\uc11c \uac00\uc838\uc635\ub2c8\ub2e4. \ub370\uc774\ud130 \uc911\ubcf5\uc774 \uc5c6\uc2b5\ub2c8\ub2e4. Room\uc774 `AFTER INSERT/UPDATE/DELETE` \ud2b8\ub9ac\uac70\ub97c \uc790\ub3d9 \uc0dd\uc131\ud574\uc11c, \uc6d0\ubcf8\uc5d0 \uc4f0\uae30\ub9cc \ud558\uba74 \uc778\ub371\uc2a4\uac00 \ub530\ub77c\uc635\ub2c8\ub2e4. DAO\uc5d0\uc11c\ub294 `docid`\ub85c \uc870\uc778\ud574 `MATCH`\ub97c \uc501\ub2c8\ub2e4.\\n\\n```kotlin\\n@Dao\\ninterface NoticeDao {\\n    @Query(\\"\\"\\"\\n        SELECT notices.* FROM notices\\n        JOIN notices_fts ON notices.id = notices_fts.docid\\n        WHERE notices_fts MATCH :query\\n        ORDER BY notices.pinned DESC\\n    \\"\\"\\")\\n    suspend fun searchNoticesFts(query: String): List<NoticeEntity>\\n}\\n```\\n\\nas-you-type \uac80\uc0c9\uc774\ub77c\uba74 \uc785\ub825 sanitize\ub97c \uc78a\uc9c0 \ub9c8\uc138\uc694.\\n\\n```kotlin\\n// \\"\uc0bc\uc131 \uc804\uc790\\" -> \\"\uc0bc\uc131* \uc804\uc790*\\" : \ud1a0\ud070\ubcc4 \uc811\ub450\uc0ac \ub9e4\uce6d\uc73c\ub85c \uc790\ub3d9\uc644\uc131 \ub290\ub08c\uc758 \uac80\uc0c9\\nfun sanitizeFtsQuery(raw: String): String =\\n    raw.replace(\\"\\\\\\"\\", \\"\\").replace(\\"\'\\", \\"\\").trim()\\n        .split(\\"\\\\\\\\s+\\".toRegex())\\n        .filter { it.isNotEmpty() }\\n        .joinToString(\\" \\") { \\"$it*\\" }\\n```\\n\\n\uae30\uc874 \ud14c\uc774\ube14\uc5d0 FTS\ub97c \ubd99\uc774\ub294 \uac74 DB \ubc84\uc804 \uc5c5 + `AutoMigration` \ub610\ub294 \uc218\ub3d9 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc73c\ub85c \ucc98\ub9ac\ud569\ub2c8\ub2e4. \uac00\uc0c1 \ud14c\uc774\ube14\uc740 \uc6d0\ubcf8 \uc2a4\ud0a4\ub9c8 \ubcc0\uacbd\uacfc \ub3c5\ub9bd\uc801\uc774\ub2c8, \ub9c8\uc774\uadf8\ub808\uc774\uc158 \ubd80\ub2f4\ub3c4 \ud06c\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n### \ucd9c\ucc98\\n\\n- [Scaling Android Search: Room @Fts4 vs SQL LIKE](https://proandroiddev.com/scaling-android-search-room-fts4-vs-sql-like-b2a8232cbd12) \u2014 O\u011fuzhan Aslan, ProAndroidDev, 2026\ub144 10\uc6d4 (\ubca4\uce58\ub9c8\ud06c \uc218\uce58 \uc778\uc6a9: 5,000\uac74 \uae30\uc900 LIKE 63.762ms vs FTS4 6.811ms)"},{"id":"flow-collection-lifecycle","metadata":{"permalink":"/blog/posts/flow-collection-lifecycle","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-14-flow-collection-lifecycle/index.mdx","source":"@site/blog/2026-10-14-flow-collection-lifecycle/index.mdx","title":"Compose\uc5d0\uc11c Flow \uc218\uc9d1\uc758 \uc9c4\ud654 \u2014 collectAsState()\uc5d0\uc11c collectAsStateWithLifecycle()\uae4c\uc9c0","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud55c\ud22c \uc571 \uac1c\ubc1c\uc790 way\uc785\ub2c8\ub2e4.","date":"2026-10-14T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"compose","permalink":"/blog/posts/tags/compose"},{"inline":true,"label":"flow","permalink":"/blog/posts/tags/flow"},{"inline":true,"label":"lifecycle","permalink":"/blog/posts/tags/lifecycle"}],"readingTime":1.53,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"flow-collection-lifecycle","title":"Compose\uc5d0\uc11c Flow \uc218\uc9d1\uc758 \uc9c4\ud654 \u2014 collectAsState()\uc5d0\uc11c collectAsStateWithLifecycle()\uae4c\uc9c0","authors":["way"],"tags":["android","compose","flow","lifecycle"]},"unlisted":false,"prevItem":{"title":"SQL LIKE \'%\uac80\uc0c9\uc5b4%\'\uac00 \uc571\uc744 \ub290\ub9ac\uac8c \ud55c\ub2e4 \u2014 Room @Fts4\ub85c \uac80\uc0c9 9.4\ubc30 \ube60\ub974\uac8c","permalink":"/blog/posts/room-fts4-search"},"nextItem":{"title":"Google Play\uc5d0\uc11c \ubc14\uc774\ube0c\ucf54\ub529\ud55c \uac1c\uc778 \uc571\uc744 \ubc14\ub85c \uc2e4\ud589\ud560 \uc218 \uc788\uac8c \ub410\ub2e4","permalink":"/blog/posts/google-play-personal-apps"}},"content":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c [\ud55c\ud22c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartpension&hl=ko) \uc571 \uac1c\ubc1c\uc790 way\uc785\ub2c8\ub2e4.\\n\\n10\uc6d4 ProAndroidDev\uc5d0 \uc62c\ub77c\uc628 \uae00 \\"The Evolution of Flow Collection in Jetpack Compose\\"\uac00, Compose\uc5d0\uc11c Flow\ub97c \uc218\uc9d1\ud558\ub294 API\uac00 \uc5b4\ub5bb\uac8c \uc9c4\ud654\ud574 \uc654\ub294\uc9c0 \uae54\ub054\ud558\uac8c \uc815\ub9ac\ud588\uc2b5\ub2c8\ub2e4. \uc775\uc219\ud55c \ub0b4\uc6a9\uc774\uc9c0\ub9cc, \uc2e4\ubb34\uc5d0\uc11c \uc5ec\uc804\ud788 `collectAsState()`\ub97c \uad00\uc131\uc73c\ub85c \uc4f0\ub294 \ucf54\ub4dc\uac00 \ub9ce\uc544\uc11c \uc774\ubc88 \uae30\ud68c\uc5d0 \uc815\ub9ac\ud574 \ubd05\ub2c8\ub2e4.\\n\\n## \ud575\uc2ec \uc694\uc57d\\n\\n- Compose 1.0(2021\ub144 7\uc6d4)\uc758 `collectAsState()`\ub294 Flow\ub97c State\ub85c \ubc14\uafb8\ub294 \uac00\uc7a5 \ub2e8\uc21c\ud55c \ubc29\ubc95\uc774\uc9c0\ub9cc, **\ub77c\uc774\ud504\uc0ac\uc774\ud074\uc744 \ubaa8\ub978\ub2e4**\\n- \uc561\ud2f0\ube44\ud2f0\uac00 \ubc31\uadf8\ub77c\uc6b4\ub4dc\ub85c \uac00\ub3c4 composition\uc774 \uc0b4\uc544 \uc788\uc73c\uba74 \uc218\uc9d1\uc774 \uacc4\uc18d\ub41c\ub2e4\\n- \uc9c0\uae08\uc758 \uc815\ub2f5\uc740 `collectAsStateWithLifecycle()` \u2014 STARTED \ubbf8\ub9cc\uc774\uba74 \uc218\uc9d1\uc744 \uba48\ucd94\uace0, \ub3cc\uc544\uc624\uba74 \uc7ac\uac1c\ud55c\ub2e4\\n\\n## \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n### 1\ub2e8\uacc4: collectAsState() (Compose 1.0)\\n\\n```kotlin\\nval uiState by viewModel.uiState.collectAsState()\\n```\\n\\n\uc0c8 \uac12\uc774 emit\ub420 \ub54c\ub9c8\ub2e4 Compose\uac00 state\ub97c \uc5c5\ub370\uc774\ud2b8\ud558\uace0 \uad00\ub828 UI\ub97c \ub9ac\ucef4\ud3ec\uc988\ud569\ub2c8\ub2e4. \ucf54\ub4dc\ub294 \uac04\ub2e8\ud558\uc9c0\ub9cc, \uc911\uc694\ud55c \ucc28\uc774\uac00 \ud558\ub098 \uc788\uc2b5\ub2c8\ub2e4. `collectAsState()`\ub294 \ub77c\uc774\ud504\uc0ac\uc774\ud074\uc774 STARTED \uc544\ub798\ub85c \ub0b4\ub824\uac00\ub3c4 \uc218\uc9d1\uc744 \uc790\ub3d9\uc73c\ub85c \uba48\ucd94\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. composition\uc774 \uc0b4\uc544 \uc788\ub294 \ud55c \ubc31\uadf8\ub77c\uc6b4\ub4dc\uc5d0\uc11c\ub3c4 \uacc4\uc18d \uc218\uc9d1\ud569\ub2c8\ub2e4.\\n\\n### 2\ub2e8\uacc4: collectAsStateWithLifecycle()\\n\\n`lifecycle-runtime-compose`\uac00 \uc81c\uacf5\ud558\ub294 API\ub85c, \ub77c\uc774\ud504\uc0ac\uc774\ud074\uc744 \uc778\uc2dd\ud569\ub2c8\ub2e4. \uae30\ubcf8 `minActiveState`\ub294 STARTED\ub77c\uc11c, \ud654\uba74\uc774 \ubcf4\uc774\uc9c0 \uc54a\uc73c\uba74 \uc218\uc9d1\uc744 \uba48\ucdc4\ub2e4\uac00 \ub2e4\uc2dc \ubcf4\uc774\uba74 \uc7ac\uac1c\ud569\ub2c8\ub2e4.\\n\\n```kotlin\\nval uiState by viewModel.uiState.collectAsStateWithLifecycle()\\n```\\n\\n### 3\ub2e8\uacc4: \uc77c\ud68c\uc131 \uc774\ubca4\ud2b8\ub294 \ub2e4\ub978 \ud328\ud134\uc73c\ub85c\\n\\n\uc0c1\ud0dc\uac00 \uc544\ub2c8\ub77c \uc774\ubca4\ud2b8(\ub124\ube44\uac8c\uc774\uc158, \uc2a4\ub0b5\ubc14 \ub4f1)\ub97c \uc18c\ube44\ud560 \ub54c\ub294 `collectAsState*` \uacc4\uc5f4\uc774 \uc544\ub2c8\ub77c `LaunchedEffect` + `repeatOnLifecycle` \uc870\ud569\uc774 \ub9de\uc2b5\ub2c8\ub2e4.\\n\\n```kotlin\\nval lifecycle = LocalLifecycleOwner.current.lifecycle\\nLaunchedEffect(lifecycle) {\\n    lifecycle.repeatOnLifecycle(Lifecycle.State.STARTED) {\\n        viewModel.events.collect { event ->\\n            // \ub124\ube44\uac8c\uc774\uc158, \uc2a4\ub0b5\ubc14 \ub4f1 \uc77c\ud68c\uc131 \uc774\ubca4\ud2b8 \ucc98\ub9ac\\n        }\\n    }\\n}\\n```\\n\\n## \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- \ubdf0\ubaa8\ub378\uc758 `uiState` \uac19\uc740 StateFlow\ub294 **`collectAsStateWithLifecycle()`\ub97c \uae30\ubcf8\uac12**\uc73c\ub85c \ub450\ub294 \uac8c \uc548\uc804\ud569\ub2c8\ub2e4\\n- `collectAsState()`\ub294 upstream\uc774 \uac00\ubcbc\uc6b0\uba74 \ubb38\uc81c\uac00 \uc5c6\uc9c0\ub9cc, \uc18c\ucf13\xb7\uc704\uce58\xb7\uc13c\uc11c\ucc98\ub7fc \ube44\uc2fc \uc791\uc5c5\uc744 \ud558\ub294 Flow\uba74 \ubc31\uadf8\ub77c\uc6b4\ub4dc\uc5d0\uc11c \ub9ac\uc18c\uc2a4\ub97c \ub0ad\ube44\ud569\ub2c8\ub2e4\\n- `minActiveState` \ud30c\ub77c\ubbf8\ud130\ub85c \uae30\uc900\uc744 RESUMED\uae4c\uc9c0 \uc62c\ub9b4 \uc218\ub3c4 \uc788\uc73c\ub2c8, \ud654\uba74 \uc694\uad6c\uc0ac\ud56d\uc5d0 \ub9de\uac8c \uc870\uc815\ud558\uc138\uc694\\n- SharedFlow \uae30\ubc18 \uc77c\ud68c\uc131 \uc774\ubca4\ud2b8\uc5d0 `collectAsState`\ub97c \ubd99\uc774\ub294 \uc2e4\uc218\ub294 \uc5ec\uc804\ud788 \ud754\ud569\ub2c8\ub2e4. \uc774\ubca4\ud2b8\uba74 \uc218\uc9d1 \ud328\ud134\uc744 \ubc14\uafb8\uc138\uc694\\n\\n## \ucd9c\ucc98\\n\\n- [The Evolution of Flow Collection in Jetpack Compose](https://proandroiddev.com/the-evolution-of-flow-collection-in-jetpack-compose-e93416a9d52d?gi=f6de1321b4bc&source=post_page---post_publication_info--b2a8232cbd12-----------------------------------------) \u2014 chanzmao, ProAndroidDev, 2026\ub144 10\uc6d4"},{"id":"google-play-personal-apps","metadata":{"permalink":"/blog/posts/google-play-personal-apps","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-14-google-play-personal-apps/index.mdx","source":"@site/blog/2026-10-14-google-play-personal-apps/index.mdx","title":"Google Play\uc5d0\uc11c \ubc14\uc774\ube0c\ucf54\ub529\ud55c \uac1c\uc778 \uc571\uc744 \ubc14\ub85c \uc2e4\ud589\ud560 \uc218 \uc788\uac8c \ub410\ub2e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c \ud55c\ud22c \uc571 \uac1c\ubc1c\uc790 way\uc785\ub2c8\ub2e4.","date":"2026-10-14T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"google-play","permalink":"/blog/posts/tags/google-play"},{"inline":true,"label":"ai","permalink":"/blog/posts/tags/ai"}],"readingTime":1.82,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"google-play-personal-apps","title":"Google Play\uc5d0\uc11c \ubc14\uc774\ube0c\ucf54\ub529\ud55c \uac1c\uc778 \uc571\uc744 \ubc14\ub85c \uc2e4\ud589\ud560 \uc218 \uc788\uac8c \ub410\ub2e4","authors":["way"],"tags":["android","google-play","ai"]},"unlisted":false,"prevItem":{"title":"Compose\uc5d0\uc11c Flow \uc218\uc9d1\uc758 \uc9c4\ud654 \u2014 collectAsState()\uc5d0\uc11c collectAsStateWithLifecycle()\uae4c\uc9c0","permalink":"/blog/posts/flow-collection-lifecycle"},"nextItem":{"title":"\uad6c\uae00\ubd81 \ub9ac\ub205\uc2a4 \ud130\ubbf8\ub110 \ud504\ub9ac\ubdf0 \u2014 AI \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c sudo\ub97c \uc918\ub3c4 \ub418\ub294 VM \uc0cc\ub4dc\ubc15\uc2a4","permalink":"/blog/posts/googlebook-linux-terminal"}},"content":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c [\ud55c\ud22c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartpension&hl=ko) \uc571 \uac1c\ubc1c\uc790 way\uc785\ub2c8\ub2e4.\\n\\n\uad6c\uae00\uc774 10\uc6d4 13\uc77c Google Play \uc5c5\ub370\uc774\ud2b8\ub97c \ubc1c\ud45c\ud588\uc2b5\ub2c8\ub2e4. \uc5ec\ub7ec \uac8c\uc784\xb7\ubc1c\uacac \uae30\ub2a5 \uc18c\uc2dd\uc774 \ud568\uaed8 \ub098\uc654\ub294\ub370, \uac1c\ubc1c\uc790 \uc785\uc7a5\uc5d0\uc11c \uac00\uc7a5 \ub208\uc5ec\uaca8\ubcfc \uac74 **Google AI Studio\uc5d0\uc11c \ubc14\uc774\ube0c\ucf54\ub529\uc73c\ub85c \ub9cc\ub4e0 \ucee4\uc2a4\ud140 Android \uc571\uc744 Google Play\ub97c \ud1b5\ud574 \uac1c\uc778 \uc571(personal app)\uc73c\ub85c \ubc14\ub85c \uc2e4\ud589**\ud560 \uc218 \uc788\uac8c \ub41c \uc18c\uc2dd\uc785\ub2c8\ub2e4.\\n\\n## \ud575\uc2ec \uc694\uc57d\\n\\n- Google AI Studio\uc5d0\uc11c \ub9cc\ub4e0 \uc571\uc744 Google Play\uc5d0\uc11c \uac1c\uc778 \uc571\uc73c\ub85c \uc790\uc2e0\uc758 \uae30\uae30\uc5d0 \uc2e4\ud589 \uac00\ub2a5\\n- **\ubcc4\ub3c4\uc758 \uac1c\ubc1c\uc790 \uacc4\uc815 \uc5c6\uc774 \uc77c\ubc18 Google \uacc4\uc815**\uc73c\ub85c \uac00\ub2a5\\n- \uac1c\uc778 \uc571\uc740 \uacf5\uac1c \uc2a4\ud1a0\uc5b4 \uce74\ud0c8\ub85c\uadf8\uc640 \ubd84\ub9ac\ub418\uc5b4 private\ud558\uace0 \uc548\uc804\ud558\uac8c \uc720\uc9c0\\n- 10\uc6d4 13\uc77c\ubd80\ud130 \uc120\ubcc4 \uc2dc\uc7a5\uc5d0 \ub864\uc544\uc6c3 (\ubbf8\uad6d \ud3ec\ud568, 18\uc138 \uc774\uc0c1)\\n- \ud5a5\ud6c4 \uba87 \ub2ec \ub0b4 \uce5c\uad6c\xb7\uac00\uc871\uacfc\uc758 \uc18c\uaddc\ubaa8 \uacf5\uc720 \uc9c0\uc6d0 \uc608\uc815\\n\\n## \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n\uc608\uc804\uc5d0\ub294 AI\ub85c \ub69d\ub531 \ub9cc\ub4e0 \uc571\uc744 \uc2e4\uae30\uae30\uc5d0 \uc62c\ub9ac\ub824\uba74 APK\ub97c \uc9c1\uc811 \ube4c\ub4dc\ud574\uc11c \uc124\uce58\ud558\uac70\ub098, \ub0b4\ubd80 \ud14c\uc2a4\ud2b8 \ud2b8\ub799\uc6a9\uc73c\ub85c Play Console\uc5d0 \uc62c\ub9ac\ub294 \uc808\ucc28\uac00 \ud544\uc694\ud588\uc2b5\ub2c8\ub2e4. \uc774\uc81c \uadf8 \uacfc\uc815\uc744 Play\uac00 \uc9c1\uc811 \uac10\uc2f8\uc90d\ub2c8\ub2e4. \\"there\'s an app for that\\"\uc5d0\uc11c \\"there\'s an app for me\\"\ub85c,\ub77c\ub294 \uac8c \uad6c\uae00\uc758 \ud45c\ud604\uc785\ub2c8\ub2e4.\\n\\n\uc815\uc2dd\uc73c\ub85c \uc138\uc0c1\uc5d0 \uacf5\uac1c\ud558\uace0 \uc2f6\uc5b4\uc9c0\uba74 \ud504\ub85c \uac1c\ubc1c\uc790 \uacc4\uc815\uc73c\ub85c \uc804\ud658\ud558\uba74 \ub418\uace0, \uadf8 \uc2dc\uc810\ubd80\ud130\ub294 \ub2e4\ub978 \uc571\ub4e4\uacfc \ub3d9\uc77c\ud55c Trust & Safety \ub9ac\ubdf0\uc640 \ud488\uc9c8 \uae30\uc900\uc774 \uc801\uc6a9\ub429\ub2c8\ub2e4. \uc989, **\uc2e4\ud5d8 \uad6c\uac04\uacfc \ubc30\ud3ec \uad6c\uac04\uc758 \uacbd\uacc4\uac00 \uba85\ud655\ud574\uc84c\ub2e4**\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n\\n## \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- \uae30\ud68d\xb7QA\uc6a9 \ub0b4\ubd80 \uc2e4\ud5d8 \ube4c\ub4dc \uacbd\ub85c\uac00 \ub354 \uac00\ubcbc\uc6cc\uc9c8 \uc5ec\uc9c0\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub0b4\ubd80 \ud14c\uc2a4\ud2b8 \ud2b8\ub799\ubcf4\ub2e4\ub3c4 \uc9c4\uc785 \uc7a5\ubcbd\uc774 \ub0ae\uc740 \uac1c\uc778 \uc2e4\ud589 \uacbd\ub85c\uac00 \uc0dd\uae34 \uc148\uc785\ub2c8\ub2e4.\\n- \uacf5\uac1c \uc2a4\ud1a0\uc5b4 \ub9ac\ubdf0\uc640 \uc644\uc804\ud788 \ubd84\ub9ac\ub418\ubbc0\ub85c, \uc2e4\ud5d8\uc801\uc778 \uae30\ub2a5\uc744 \uac1c\uc778 \uae30\uae30\uc5d0\uc11c \ube60\ub974\uac8c \ub3cc\ub824\ubcf4\ub294 \uc6a9\ub3c4\ub85c \uc801\ud569\ud569\ub2c8\ub2e4.\\n- \ub2e8, \uc544\uc9c1\uc740 \uc120\ubcc4 \uc2dc\uc7a5 \uc911\uc2ec \ub864\uc544\uc6c3\uc774\ub77c \ud55c\uad6d\uc5d0\uc11c \ubc14\ub85c \uc0ac\uc6a9\ud560 \uc218 \uc788\ub294\uc9c0\ub294 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- \ud504\ub85c \uacc4\uc815 \uc804\ud658 \uc2dc\uc810\uc758 \ub9ac\ubdf0\ub294 \uae30\uc874\uacfc \ub3d9\uc77c\ud558\ub2c8, \\"\uc77c\ub2e8 \uc62c\ub9ac\uace0 \ubcf4\uc790\\"\uc2dd \uc811\uadfc\uc740 \uc5ec\uc804\ud788 \ud1b5\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n## \ud568\uaed8 \ubc1c\ud45c\ub41c \ub0b4\uc6a9\\n\\n- **Ask Play**: \uc9c8\ubb38\uc5d0 \ub9de\ub294 \uc571 \ucd94\ucc9c + \uc571 \uac04 \ube44\uad50(\uc8fc\uc694 \ucc28\uc774\uc810, \uc0ac\uc6a9\uc790 \ubc18\uc751) \uc0dd\uc131\\n- **Play in Gemini**: Gemini \ub300\ud654 \uc548\uc5d0\uc11c Play \uc571\xb7\uac8c\uc784\xb7\uac1c\ubc1c\uc790 \ucf58\ud150\uce20 \uc811\uadfc\\n- **Game Finder**: \ud50c\ub808\uc774 \ucde8\ud5a5 \ubd84\uc11d(Gamer DNA) \uae30\ubc18 \uac8c\uc784 \ucd94\ucc9c, \ubbf8\uad6d \uc601\uc5b4 \uc0ac\uc6a9\uc790\uc5d0\uac8c \uba3c\uc800 \uc81c\uacf5\\n- \uac8c\uc784 \uad00\ub828: 48\uc2dc\uac04 \ubbf8\ub2c8 \ucc4c\ub9b0\uc9c0 Sprints, Sidekick \uc624\ubc84\ub808\uc774\uc758 30\ucd08 Playbacks \ub179\ud654, \uac8c\uc784 \uc0c1\uc138 \ud398\uc774\uc9c0\uc758 Community Posts\\n- **Family Link**\ub97c \ud1b5\ud55c \uc5f0\ub839\ub300 \uc815\ubcf4 \uacf5\uc720\ub85c \uc5f0\ub839\uc5d0 \ub9de\ub294 \uacbd\ud5d8 \uc81c\uacf5\\n\\n## \ucd9c\ucc98\\n\\n- [New on Google Play: More ways to create, discover, and play](https://blog.google/products-and-platforms/platforms/google-play/google-play-updates-october-2026/) \u2014 Google, 2026-10-13"},{"id":"googlebook-linux-terminal","metadata":{"permalink":"/blog/posts/googlebook-linux-terminal","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-13-googlebook-linux-terminal/index.mdx","source":"@site/blog/2026-10-13-googlebook-linux-terminal/index.mdx","title":"\uad6c\uae00\ubd81 \ub9ac\ub205\uc2a4 \ud130\ubbf8\ub110 \ud504\ub9ac\ubdf0 \u2014 AI \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c sudo\ub97c \uc918\ub3c4 \ub418\ub294 VM \uc0cc\ub4dc\ubc15\uc2a4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-13T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"googlebook","permalink":"/blog/posts/tags/googlebook"},{"inline":true,"label":"linux","permalink":"/blog/posts/tags/linux"},{"inline":true,"label":"ai-agent","permalink":"/blog/posts/tags/ai-agent"},{"inline":true,"label":"devtools","permalink":"/blog/posts/tags/devtools"}],"readingTime":3.76,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"googlebook-linux-terminal","title":"\uad6c\uae00\ubd81 \ub9ac\ub205\uc2a4 \ud130\ubbf8\ub110 \ud504\ub9ac\ubdf0 \u2014 AI \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c sudo\ub97c \uc918\ub3c4 \ub418\ub294 VM \uc0cc\ub4dc\ubc15\uc2a4","authors":["way"],"tags":["android","googlebook","linux","ai-agent","devtools"]},"unlisted":false,"prevItem":{"title":"Google Play\uc5d0\uc11c \ubc14\uc774\ube0c\ucf54\ub529\ud55c \uac1c\uc778 \uc571\uc744 \ubc14\ub85c \uc2e4\ud589\ud560 \uc218 \uc788\uac8c \ub410\ub2e4","permalink":"/blog/posts/google-play-personal-apps"},"nextItem":{"title":"Kotlin 2.5.0\uc5d0 companion \ube14\ub85d\uc774 \uc628\ub2e4 \u2014 companion object\uc640 \ubb34\uc5c7\uc774 \ub2e4\ub978\uac00","permalink":"/blog/posts/kotlin-companion-blocks"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 12\uc77c, Android Developers Blog\uc5d0 \\"Introducing the Googlebook Linux Terminal Preview: A VM-Backed Environment for AI and Development\\"\ub77c\ub294 \uae00\uc774 \uc62c\ub77c\uc654\uc2b5\ub2c8\ub2e4. \uad6c\uae00\ubd81(Googlebook) \u2014 Android\uc640 Chrome OS\ub97c \ud569\uce5c \uc0c8 \ub178\ud2b8\ubd81 \uce74\ud14c\uace0\ub9ac \u2014 \uc5d0 Debian \uae30\ubc18 \ub9ac\ub205\uc2a4 \ud130\ubbf8\ub110\uc774 \ud504\ub9ac\ubdf0\ub85c \ub4e4\uc5b4\uc628\ub2e4\ub294 \uc18c\uc2dd\uc785\ub2c8\ub2e4. \ud575\uc2ec\uc740 \\"AI \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c sudo\ub97c \uc918\ub3c4 \uc2dc\uc2a4\ud15c\uc774 \uc548 \ub9dd\uac00\uc9c0\ub294 \uad6c\uc870\\"\uc785\ub2c8\ub2e4. Android \uac1c\ubc1c\uc790 \uc785\uc7a5\uc5d0\uc11c \ubb34\uc5c7\uc774 \uc758\ubbf8 \uc788\ub294\uc9c0 \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- \uad6c\uae00\ubd81\uc5d0 VM \uae30\ubc18 \ub9ac\ub205\uc2a4 \ud130\ubbf8\ub110\uc774 \ud504\ub9ac\ubdf0\ub85c \uc81c\uacf5\ub429\ub2c8\ub2e4. \ubaa8\ub4e0 \ud130\ubbf8\ub110 \uba85\ub839\uc740 \uaca9\ub9ac\ub41c Linux VM \uc548\uc5d0\uc11c\ub9cc \uc2e4\ud589\ub429\ub2c8\ub2e4.\\n- \uba85\ub839\uc774 VM\uc744 \ubc97\uc5b4\ub098\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0, Antigravity \uac19\uc740 AI \uc5d0\uc774\uc804\ud2b8\uc5d0 `sudo` \uad8c\ud55c\uc744 \uc918\ub3c4 \ud638\uc2a4\ud2b8 OS\ub098 \uac1c\uc778 \ud30c\uc77c\uc774 \uc624\uc5fc\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \ub514\ub809\ud130\ub9ac\ub294 \uc0ac\uc6a9\uc790\uac00 \uba85\uc2dc\uc801\uc73c\ub85c \ud5c8\uc6a9\ud55c \uac83\ub9cc VM\uc5d0 \ub9c8\uc6b4\ud2b8\ub429\ub2c8\ub2e4.\\n- \uc6d0\ud074\ub9ad VM \ub9ac\uc14b\uc73c\ub85c \uc2e4\ud5d8\uc744 \ub0a0\ub9b4 \uc218 \uc788\uace0, \ud30c\uc77c\uc740 \ud638\uc2a4\ud2b8 \ud30c\uc77c \uc2dc\uc2a4\ud15c\uc5d0 \uc720\uc9c0\ub429\ub2c8\ub2e4. \ub9ac\ub205\uc2a4 \ud30c\uc77c\uc740 \uad6c\uae00\ubd81 \ud30c\uc77c \uc571\uc5d0\uc11c\ub3c4 \ubcf4\uc785\ub2c8\ub2e4.\\n- \ub85c\ub4dc\ub9f5: Linux GUI \uc571 \uc9c0\uc6d0, USB \ud328\uc2a4\uc2a4\ub8e8 + ADB over USB(VM/Antigravity\uc5d0\uc11c \uc9c1\uc811 \uae30\uae30 \ub514\ubc84\uae45), GPU/NPU \uac00\uc18d, VM \uba54\ubaa8\ub9ac\xb7\uc2a4\ud1a0\ub9ac\uc9c0 \ub3d9\uc801 \uc2a4\ucf00\uc77c\ub9c1.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### \uc5d0\uc774\uc804\ud2b8 \uc2dc\ub300\uc758 \ud130\ubbf8\ub110: sudo\ub97c \uc918\ub3c4 \uc548\uc804\ud55c \uad6c\uc870\\n\\nAI \uc5d0\uc774\uc804\ud2b8\ub294 \ud130\ubbf8\ub110\ub85c \ud328\ud0a4\uc9c0\ub97c \uc124\uce58\ud558\uace0, \ud30c\uc77c\uc744 \uc4f0\uace0, \uc791\uc5c5\uc744 \uc790\ub3d9\ud654\ud569\ub2c8\ub2e4. \ubb38\uc81c\ub294 \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \uad00\ub9ac\uc790 \uad8c\ud55c\uc744 \uc8fc\ub294 \uc21c\uac04 \uc2dc\uc2a4\ud15c\uc774 \uc704\ud5d8\ud574\uc9c4\ub2e4\ub294 \uc810\uc774\uc5c8\uc8e0. \uad6c\uae00\ubd81 OS\ub294 defense-in-depth \uc6d0\uce59\uc73c\ub85c \uc124\uacc4\ub410\uace0, \ud130\ubbf8\ub110 \uba85\ub839\uc740 \uc804\ubd80 Linux VM \uc548\uc5d0\uc11c \uc2e4\ud589\ub418\ub294 \uaca9\ub9ac \uc0cc\ub4dc\ubc15\uc2a4\uc785\ub2c8\ub2e4. VM \uacbd\uacc4\uac00 \ud638\uc2a4\ud2b8 OS\uc640 \ub9c8\uc6b4\ud2b8\ub418\uc9c0 \uc54a\uc740 \ud30c\uc77c\uc744 \ubcf4\ud638\ud558\uace0, VM\uc5d0 \uacf5\uac1c\ud558\ub294 \ub514\ub809\ud130\ub9ac\ub294 \uc0ac\uc6a9\uc790\uc758 \uba85\uc2dc\uc801 \ud5c8\uac00\uac00 \uc788\uc5b4\uc57c\ub9cc \ub9c8\uc6b4\ud2b8\ub429\ub2c8\ub2e4. \uc6d0\ud074\ub9ad \ub9ac\uc14b\uc73c\ub85c VM\uc744 \ucd08\uae30\ud654\ud574\ub3c4 \ud638\uc2a4\ud2b8\uc758 \ud30c\uc77c\uc740 \uadf8\ub300\ub85c \ub0a8\uc2b5\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \uacfc\uac10\ud558\uac8c \uad8c\ud55c\uc744 \uc8fc\uace0, \ub9dd\uac00\uc9c0\uba74 \ub9ac\uc14b\ud558\uba74 \ub418\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.\\n\\n#### \uac1c\ubc1c\uc790\uc5d0\uac8c \uc775\uc219\ud55c Debian \ud658\uacbd\\n\\napt, git, ssh, \ucef4\ud30c\uc77c\ub7ec\xb7\ub7f0\ud0c0\uc784 \uac19\uc740 \uc775\uc219\ud55c \uc6cc\ud06c\ud50c\ub85c\uc6b0\uac00 \uadf8\ub300\ub85c \ub4e4\uc5b4\uc635\ub2c8\ub2e4. Node.js, Python, Ruby, Go, Rust \uac19\uc740 \ubaa8\ub358 \ub7f0\ud0c0\uc784\uc744 \uc9c0\uc6d0\ud558\uace0, localhost \ud3ec\ud2b8 \uc790\ub3d9 \ud3ec\uc6cc\ub529\uc73c\ub85c \ud638\uc2a4\ud2b8 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ubc14\ub85c \ud655\uc778\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. VM\uc5d0 \ud560\ub2f9\ud558\ub294 \uba54\ubaa8\ub9ac\ub294 \uc6cc\ud06c\ub85c\ub4dc\uc5d0 \ub9de\uac8c \uc870\uc808 \uac00\ub2a5\ud569\ub2c8\ub2e4. \uad6c\uae00 \uc5d4\uc9c0\ub2c8\uc5b4\ub4e4 \uc2a4\uc2a4\ub85c \uad6c\uae00\ubd81\uc73c\ub85c \ub9ac\ub205\uc2a4 \ucee4\ub110\uc744 \ube4c\ub4dc\ud558\uace0 \ud50c\ub7ab\ud3fc \uc5d4\uc9c0\ub2c8\uc5b4\ub9c1\uc5d0 \ud130\ubbf8\ub110\uc744 \uc4f0\uace0 \uc788\ub2e4\uace0 \ud558\ub2c8, \\"\ub370\ubaa8\uc6a9 \uac00\ubcbc\uc6b4 \ud130\ubbf8\ub110\\" \uc218\uc900\uc740 \uc544\ub2d9\ub2c8\ub2e4.\\n\\n#### \ub85c\ub4dc\ub9f5\uc774 Android \uac1c\ubc1c\uc790\uc5d0\uac8c \uc9c4\uc9dc \uc758\ubbf8 \uc788\ub294 \uc774\uc720\\n\\n\ub85c\ub4dc\ub9f5 \ud56d\ubaa9\uc744 \ubcf4\uba74 \ubc29\ud5a5\uc774 \ubd84\uba85\ud569\ub2c8\ub2e4.\\n\\n- **USB \ud328\uc2a4\uc2a4\ub8e8 + ADB over USB \uc9c0\uc6d0 \uc608\uc815**: \ud604\uc7ac \ub124\ud2b8\uc6cc\ud06c \ud328\uc2a4\uc2a4\ub8e8\uc640 \ubb34\uc120 ADB\ub294 \uc788\ub294\ub370, USB \ud328\uc2a4\uc2a4\ub8e8\uac00 \uc624\uba74 Linux VM(\uacfc Antigravity)\uc5d0\uc11c \uc9c1\uc811 \ub85c\uceec \uae30\uae30 \ub514\ubc84\uae45\uc774 \uac00\ub2a5\ud574\uc9d1\ub2c8\ub2e4. \ub178\ud2b8\ubd81 \ud55c \ub300\ub85c \ube4c\ub4dc\xb7\ub514\ubc84\uae45\xb7\uc5d0\uc774\uc804\ud2b8 \uc6cc\ud06c\ud50c\ub85c\uc6b0\ub97c \ub2e4 \ub3cc\ub9ac\ub294 \uadf8\ub9bc\uc785\ub2c8\ub2e4.\\n- **Linux GUI \uc571 \uc9c0\uc6d0 (\uc571 \ub7f0\ucc98 \ud1b5\ud569)**: \ud130\ubbf8\ub110\uc744 \ub118\uc5b4 GUI \uc571\uae4c\uc9c0 \ud488\uc73c\uba74, Android Studio \uac19\uc740 \ub3c4\uad6c\ub97c VM\uc5d0 \uc62c\ub9ac\ub294 \uc2dc\ub098\ub9ac\uc624\ub3c4 \uc5f4\ub9bd\ub2c8\ub2e4.\\n- **GPU/NPU \ud558\ub4dc\uc6e8\uc5b4 \uac00\uc18d**: \ub85c\uceec\uc5d0\uc11c \ubb34\uac70\uc6b4 AI \uc6cc\ud06c\ub85c\ub4dc\ub97c \ub3cc\ub9b4 \ub54c \uc804\uc6a9 \ud558\ub4dc\uc6e8\uc5b4\ub97c \uc4f8 \uc218 \uc788\uac8c \ub429\ub2c8\ub2e4. 40 TOPS\uae09 NPU\ub97c \ub2e8 \uad6c\uae00\ubd81 \uc2a4\ud399\uacfc \ub9de\ubb3c\ub9ac\ub294 \ubd80\ubd84\uc785\ub2c8\ub2e4.\\n- **VM \uc9c0\uc18d\uc131 + \ud130\ubbf8\ub110 \ucc3d \ubd84\ub9ac**: \uc7a5\uc2dc\uac04 \ub3c4\ub294 \uc5d0\uc774\uc804\ud2b8 \uc791\uc5c5\uc744 \uc704\ud55c \uc804\uc81c \uc870\uac74\uc785\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **\ub2f9\uc7a5 \ub0b4 \uac1c\ubc1c \uba38\uc2e0\uc774 \ub418\uc9c4 \uc54a\uc2b5\ub2c8\ub2e4**: \ud504\ub9ac\ubdf0 \ub2e8\uacc4\uc774\uace0, GUI \uc571 \uc9c0\uc6d0\xb7USB ADB\ub294 \ub85c\ub4dc\ub9f5\uc785\ub2c8\ub2e4. \\"\ud130\ubbf8\ub110 + \uc5d0\uc774\uc804\ud2b8\\" \uc6a9\ub3c4\ub85c\ub294 \uc4f8 \uc218 \uc788\uc9c0\ub9cc Android \uc571 \ube4c\ub4dc\uc758 \uc8fc\ub825 \uba38\uc2e0\uc73c\ub85c \ubcf4\uae30\uc5d4 \uc774\ub985\ub2c8\ub2e4.\\n- **\uc5d0\uc774\uc804\ud2b8 \uac1c\ubc1c \ud658\uacbd\uc758 \uc0c8 \uae30\uc900\uc774 \ub420 \uac00\ub2a5\uc131**: Antigravity\uac00 \uad6c\uae00\ubd81\uc6a9\uc73c\ub85c \ub530\ub85c \ub098\uc628\ub2e4\ub294 \uc810(\ud53d\uc5c5\ub41c \ubcf4\ub3c4)\uacfc \uacb0\ud569\ud558\uba74, \uad6c\uae00\uc740 \\"\ub178\ud2b8\ubd81 = \uc5d0\uc774\uc804\ud2b8\uc640 \ud568\uaed8 \uc77c\ud558\ub294 \uba38\uc2e0\\"\uc774\ub77c\ub294 \uadf8\ub9bc\uc744 \uadf8\ub9ac\uace0 \uc788\uc2b5\ub2c8\ub2e4. 10/9\uc5d0 \ub2e4\ub8ec Android CLI\uc758 Device Streaming + Android skills \ud750\ub984\uacfc \uac19\uc740 \ubc29\ud5a5\uc785\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8\uac00 \uacf5\uc2dd \uac00\uc774\ub4dc\ub97c \uc77d\uace0 \uae30\uae30\ub97c \ub9cc\uc9c0\ub294 \uc2dc\ub300\uc5d0, \uac1c\ubc1c \ud658\uacbd \uc790\uccb4\uac00 \uc5d0\uc774\uc804\ud2b8 \uce5c\ud654\uc801\uc73c\ub85c \ubc14\ub00c\uace0 \uc788\ub2e4\ub294 \uc2e0\ud638\ub85c \uc77d\uc5b4\uc57c \ud569\ub2c8\ub2e4.\\n- **\ubcf4\uc548 \ubaa8\ub378\uc740 \uc8fc\ubaa9\ud560 \ub9cc\ud569\ub2c8\ub2e4**: sudo\ub97c \uc918\ub3c4 \ub418\ub294 VM \uc0cc\ub4dc\ubc15\uc2a4, \ub514\ub809\ud130\ub9ac\ubcc4 \uba85\uc2dc\uc801 \ub9c8\uc6b4\ud2b8 \ud5c8\uac00, \uc6d0\ud074\ub9ad \ub9ac\uc14b. \uc0ac\ub0b4\uc5d0\uc11c AI \ucf54\ub529 \uc5d0\uc774\uc804\ud2b8 \ub3c4\uc785\uc744 \uac80\ud1a0\ud560 \ub54c \\"\uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \uc5b4\ub514\uae4c\uc9c0 \uad8c\ud55c\uc744 \uc904 \uac83\uc778\uac00\\"\uc5d0 \ub300\ud55c \ub808\ud37c\ub7f0\uc2a4 \uc544\ud0a4\ud14d\ucc98\ub85c \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- **\uc5b4\ub311\ud2f0\ube0c \uac1c\ubc1c\uacfc \uc5f0\uacb0\ub429\ub2c8\ub2e4**: 9/22\uc5d0 \uc62c\ub77c\uc628 \\"Land your apps on Googlebook with adaptive development\\" \uae00\uacfc \ud568\uaed8 \ubcf4\uba74, \uad6c\uae00\ubd81\uc740 Android \uc571\uc758 \uc0c8 \ud0c0\uae43 \ud3fc\ud329\ud130\uc774\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc6b0\ub9ac \uc571\uc774 \ub300\ud654\uba74\xb7\ub370\uc2a4\ud06c\ud1b1 \ud658\uacbd\uc5d0\uc11c \uc5b4\ub5bb\uac8c \ubcf4\uc774\ub294\uc9c0 \uc810\uac80\ud560 \uc774\uc720\uac00 \ud558\ub098 \ub354 \ub298\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c \uc774\ub807\uac8c \ud655\uc778\ud560 \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uc544\uc9c1 \uad6c\uae00\ubd81 \uc2e4\ubb3c\uc774 \uc5c6\uc5b4 \ucf54\ub4dc \uc2e4\ud5d8\uc740 \ubabb \ud558\uc9c0\ub9cc, \uc5d0\uc774\uc804\ud2b8 \uce5c\ud654 \uac1c\ubc1c \ud658\uacbd\uc774\ub77c\ub294 \uad00\uc810\uc5d0\uc11c \uc9c0\uae08 \ub2f9\uc7a5 \ud560 \uc218 \uc788\ub294 \uc815\ub9ac\ub294 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```bash\\n# 1) \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc5d0\uc774\uc804\ud2b8\uc6a9 \uac00\uc774\ub4dc\uac00 \uc788\ub294\uc9c0 \uc810\uac80 (Android CLI skills \ud750\ub984\uacfc \uc5f0\uacb0)\\nls .agent/ AGENTS.md CLAUDE.md 2>/dev/null\\n\\n# 2) \ubb34\uc120 ADB\ub85c \uc5d0\uc774\uc804\ud2b8\uac00 \uae30\uae30\ub97c \ub9cc\uc9c8 \uc218 \uc788\ub294\uc9c0 \ud655\uc778\\nadb devices -l          # \uae30\uae30\uac00 \ubcf4\uc774\ub294\uc9c0\\nadb shell settings get global adb_wifi_enabled\\n```\\n\\n\uad6c\uae00\ubd81\uc774 \uc190\uc5d0 \ub4e4\uc5b4\uc624\uba74 \uac00\uc7a5 \uba3c\uc800 \ud574\ubcfc \uac74 \uc774 \uc21c\uc11c\uc785\ub2c8\ub2e4: \ud130\ubbf8\ub110\uc5d0\uc11c `git clone` \u2192 \ud504\ub85c\uc81d\ud2b8 \ube4c\ub4dc \u2192 \ubb34\uc120 ADB\ub85c \uc2e4\uae30 \uc5f0\uacb0 \u2192 Antigravity\uc5d0\uac8c \ube4c\ub4dc\xb7\ud14c\uc2a4\ud2b8\ub97c \ub9e1\uae30\uace0 VM \ub9ac\uc14b \ud55c \ubc88 \ud574\ubcf4\uae30. \uadf8\ub54c \ub2e4\uc2dc \uc2e4\uce21 \uae00\ub85c \ub3cc\uc544\uc624\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n### \ucd9c\ucc98\\n\\n- [Introducing the Googlebook Linux Terminal Preview: A VM-Backed Environment for AI and Development \u2014 Android Developers Blog (2026-10-12)](https://android-developers.googleblog.com/2026/10/googlebook-linux-terminal-preview-vm.html) \u2014 VM \uc0cc\ub4dc\ubc15\uc2a4 \uad6c\uc870, sudo \ud5c8\uc6a9 \uc124\uacc4, Debian \ud658\uacbd, \ub85c\ub4dc\ub9f5\\n- [Device Streaming and Android skills - available in Android CLI \u2014 Android Developers Blog (2026-10-02)](https://android-developers.googleblog.com/) \u2014 \uc5d0\uc774\uc804\ud2b8 \uc2dc\ub300 Android \uac1c\ubc1c \ud750\ub984 (\ubcf8 \ube14\ub85c\uadf8 10/9 \uae00\uc5d0\uc11c\ub3c4 \ub2e4\ub8f8)"},{"id":"kotlin-companion-blocks","metadata":{"permalink":"/blog/posts/kotlin-companion-blocks","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-13-kotlin-companion-blocks/index.mdx","source":"@site/blog/2026-10-13-kotlin-companion-blocks/index.mdx","title":"Kotlin 2.5.0\uc5d0 companion \ube14\ub85d\uc774 \uc628\ub2e4 \u2014 companion object\uc640 \ubb34\uc5c7\uc774 \ub2e4\ub978\uac00","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-13T00:00:00.000Z","tags":[{"inline":true,"label":"kotlin","permalink":"/blog/posts/tags/kotlin"},{"inline":true,"label":"companion","permalink":"/blog/posts/tags/companion"},{"inline":true,"label":"language","permalink":"/blog/posts/tags/language"},{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"}],"readingTime":3.32,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kotlin-companion-blocks","title":"Kotlin 2.5.0\uc5d0 companion \ube14\ub85d\uc774 \uc628\ub2e4 \u2014 companion object\uc640 \ubb34\uc5c7\uc774 \ub2e4\ub978\uac00","authors":["way"],"tags":["kotlin","companion","language","android"]},"unlisted":false,"prevItem":{"title":"\uad6c\uae00\ubd81 \ub9ac\ub205\uc2a4 \ud130\ubbf8\ub110 \ud504\ub9ac\ubdf0 \u2014 AI \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c sudo\ub97c \uc918\ub3c4 \ub418\ub294 VM \uc0cc\ub4dc\ubc15\uc2a4","permalink":"/blog/posts/googlebook-linux-terminal"},"nextItem":{"title":"Remote Compose 1.0.0-alpha21 \u2014 10\uc6d4 AndroidX \ub9b4\ub9ac\uc2a4\uc5d0\uc11c \ubcf8 \uc11c\ubc84 \uad6c\ub3d9 UI\uc758 \ud604\uc7ac \uc704\uce58","permalink":"/blog/posts/androidx-remote-compose-alpha21"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\nKotlin 2.5.0\ubd80\ud130 `companion object`\uc640 \ubb38\ubc95\uc740 \uac70\uc758 \uac19\uc9c0\ub9cc \ucef4\ud30c\uc77c \ubc29\uc2dd\uc774 \uadfc\ubcf8\uc801\uc73c\ub85c \ub2e4\ub978 **companion \ube14\ub85d**\uacfc **companion \ud655\uc7a5(companion extension)**\uc774 \uc2e4\ud5d8 \uae30\ub2a5\uc73c\ub85c \ub4e4\uc5b4\uc635\ub2c8\ub2e4. `TAG` \ud558\ub098, `newInstance()` \ud558\ub098 \ucc0d\uc744 \ub54c\ub9c8\ub2e4 \ub530\ub77c\ub2e4\ub2c8\ub358 `Companion` \uc2f1\uae00\ud134\uc758 \uc138\uae08\uc744 \ub4dc\ub514\uc5b4 \ub35c \uc218 \uc788\uac8c \ub41c \uc148\uc785\ub2c8\ub2e4. JetBrains\uc758 \ubc1c\ud45c \uae00 \\"The Companions to Come\\"(2026-09-30)\uc744 \uc2e4\ubb34 \uad00\uc810\uc5d0\uc11c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- Kotlin 2.5.0-Beta1\ubd80\ud130 \uc2e4\ud5d8 \uae30\ub2a5\uc73c\ub85c companion \ube14\ub85d\uacfc companion \ud655\uc7a5\uc744 \uc0ac\uc6a9\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ucef4\ud30c\uc77c\ub7ec \ud50c\ub798\uadf8 `-Xcompanion-blocks` (\ube14\ub85d\ub9cc) \ub610\ub294 `-Xcompanion-blocks-and-extensions` (\ub458 \ub2e4)\ub97c \ub118\uaca8\uc57c \ud569\ub2c8\ub2e4.\\n- \ube14\ub85d\uc740 `companion object`\uc5d0\uc11c `object` \ud0a4\uc6cc\ub4dc\ub97c \ube80 \ud615\ud0dc\uc785\ub2c8\ub2e4. JVM\uc5d0\uc11c\ub294 \uc9c4\uc9dc static \uba64\ubc84\ub85c \ucef4\ud30c\uc77c\ub429\ub2c8\ub2e4.\\n- companion \ud655\uc7a5\uc740 `companion fun Vector.unit(angle: Double)`\ucc98\ub7fc, \ub0b4\uac00 \ub9cc\ub4e0 \ud074\ub798\uc2a4\uac00 \uc544\ub2c8\uc5b4\ub3c4 \\"\ud074\ub798\uc2a4 \uba64\ubc84\ucc98\ub7fc\\" \uc120\uc5b8\ud560 \uc218 \uc788\ub294 \uc0c8 \ubb38\ubc95\uc785\ub2c8\ub2e4. Java \ud074\ub798\uc2a4\uc5d0\ub3c4 \uc4f8 \uc218 \uc788\uace0, \uc6d0\ub798 companion object\uac00 \uc5c6\uc5b4\ub3c4 \ub429\ub2c8\ub2e4.\\n- \uae30\uc874 companion object\ub294 \uadf8\ub300\ub85c \uc9c0\uc6d0\ub418\uace0 \uac15\uc81c \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc740 \uc5c6\uc2b5\ub2c8\ub2e4. \uc778\ud130\ud398\uc774\uc2a4\ub97c \uad6c\ud604\ud574\uc57c \ud558\ub294 companion\uc740 \uc5ec\uc804\ud788 object\ub9cc \uac00\ub2a5\ud569\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### companion \ube14\ub85d: \uc9c4\uc9dc static\uc73c\ub85c \ucef4\ud30c\uc77c\\n\\n```kotlin\\ndata class Vector(val x: Double, val y: Double) {\\n    companion {\\n        val ZERO = Vector(0.0, 0.0)\\n    }\\n}\\n\\n// \uc0ac\uc6a9\uc740 \ub611\uac19\uc774\\nval v = Vector.ZERO\\n```\\n\\ncompanion object\ub294 \\"\uc2e4\uc81c \uac1d\uccb4\\"\ub77c\uc11c \uc7a5\uc810(\uc778\ud130\ud398\uc774\uc2a4 \uad6c\ud604, \uac12\uc73c\ub85c \uc804\ub2ec \uac00\ub2a5)\uc774 \uc788\uc9c0\ub9cc, \ub2e8\uc810\ub3c4 \uadf8 \uc2e4\uccb4\uc5d0\uc11c \uc635\ub2c8\ub2e4. \uc790\ubc14\uc5d0\uc11c \ud638\ucd9c\ud558\uba74 `Vector.Companion.getZERO()` \uc2dd\uc758 \uc774\ub984\uc774 \ud280\uc5b4\ub098\uc624\uace0, \ub9ac\ud50c\ub809\uc158\xb7\ubc14\uc774\ud2b8\ucf54\ub4dc \ud06c\uae30\uc5d0\ub3c4 \ubc1c\uc790\uad6d\uc774 \ub0a8\uc2b5\ub2c8\ub2e4. companion \ube14\ub85d\uc740 \ucef4\ud30c\uc77c \uc804\ub7b5\uc744 \ub2e4\ub978 \ud50c\ub7ab\ud3fc\uc758 static \uba64\ubc84\ucc98\ub7fc \ubc14\uafd4\uc11c, JVM\uc5d0\uc11c\ub294 \uc21c\uc218 static \uba64\ubc84\uac00 \ub429\ub2c8\ub2e4. \uac89\ubcf4\uae30\uc5d4 `object` \ud55c \ub2e8\uc5b4 \ucc28\uc774\uc778\ub370 \ubc14\uc774\ud2b8\ucf54\ub4dc \uad00\uc810\uc5d0\uc11c\ub294 \ub2e4\ub978 \uc138\uc0c1\uc785\ub2c8\ub2e4.\\n\\n#### companion \ud655\uc7a5: \ub0b4\uac00 \uc548 \ub9cc\ub4e0 \ud074\ub798\uc2a4\uc5d0\ub3c4 \\"static \ud568\uc218\\" \ucd94\uac00\\n\\n```kotlin\\ncompanion fun Vector.unit(angle: Double) = Vector(cos(angle), sin(angle))\\n```\\n\\n\uc774\uac8c \uc774\ubc88 \uae30\ub2a5 \uc911 \uac00\uc7a5 \ud30c\uae09\ub825\uc774 \ud070 \ubd80\ubd84\uc785\ub2c8\ub2e4. companion \ud655\uc7a5\uc740 **\ud074\ub798\uc2a4\ub97c \ub0b4\uac00 \ud1b5\uc81c\ud558\ub4e0 \ub9d0\ub4e0, Kotlin\uc774\ub4e0 Java\ub4e0, companion object\uac00 \uc6d0\ub798 \uc788\ub4e0 \uc5c6\ub4e0** \uc120\uc5b8\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\uc11c \ub0b4\ub824\uc900 \ud074\ub798\uc2a4\uc5d0 \ud329\ud1a0\ub9ac \ud568\uc218\ub97c \ubd99\uc774\uace0 \uc2f6\uc744 \ub54c, \uc720\ud2f8 \uc624\ube0c\uc81d\ud2b8\ub97c \ub530\ub85c \ub9cc\ub4e4\uc9c0 \uc54a\uace0\ub3c4 `SomeClass.myFactory()` \ud615\ud0dc\ub85c \ubd99\uc77c \uc218 \uc788\uac8c \ub429\ub2c8\ub2e4.\\n\\n#### KMP\uc640\uc758 \uc5f0\uacb0: expect/actual\uae4c\uc9c0\\n\\ncompanion \ube14\ub85d \uba64\ubc84\ub294 KMP\uc5d0\uc11c expect\ub85c \uc120\uc5b8\ud558\uace0, Java \ud074\ub798\uc2a4\uc758 static \uba64\ubc84\ub85c actualize\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uba40\ud2f0\ud50c\ub7ab\ud3fc \ub77c\uc774\ube0c\ub7ec\ub9ac\uc5d0\uc11c \ud50c\ub7ab\ud3fc \ub124\uc774\ud2f0\ube0c static API\ub97c companion \uba64\ubc84\ub85c \uac10\uc2f8\ub358 \ud328\ud134\uc774 \uc5b8\uc5b4 \ucc28\uc6d0\uc5d0\uc11c \uc815\uc2dd\uc73c\ub85c \uc9c0\uc6d0\ub418\ub294 \uc148\uc785\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **\uc9c0\uae08 \ub2f9\uc7a5 \uc4f8 \uc77c\uc740 \uc544\ub2d9\ub2c8\ub2e4**: \uc2e4\ud5d8 \uae30\ub2a5\uc774\uace0, \ud2b9\ud788 companion \ud655\uc7a5\uc744 \uc4f4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 pre-release \ubc14\uc774\ub108\ub9ac\uac00 \ub418\uc5b4 \uc548\uc815\ud654\ub420 \ub54c\uae4c\uc9c0 \uc758\uc874\uc131\uc73c\ub85c \uc18c\ube44\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4. companion \ube14\ub85d\uc740 \uc774 \uc81c\ud55c\uc774 \uc5c6\uc9c0\ub9cc, \uc18c\ube44\ud558\ub294 \ucabd\ub3c4 \ud50c\ub798\uadf8\ub97c \ucf1c\uc57c \ud569\ub2c8\ub2e4. \uc989, \uc0ac\ub0b4 \uacf5\ud1b5 \ubaa8\ub4c8\uc5d0 \uc2e4\ud5d8 \ubb38\ubc95\uc744 \ub123\uc73c\uba74 \uadf8 \ubaa8\ub4c8\uc744 \uc4f0\ub294 \ubaa8\ub4e0 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ud50c\ub798\uadf8\uac00 \uc804\uc5fc\ub429\ub2c8\ub2e4.\\n- **\ub9c8\uc774\uadf8\ub808\uc774\uc158\uc740 \uac15\uc81c\uac00 \uc544\ub2d9\ub2c8\ub2e4**: JetBrains\uac00 \uba85\uc2dc\uc801\uc73c\ub85c \ubc1d\ud614\uc2b5\ub2c8\ub2e4. companion object\ub294 Kotlin\uc758 \uc628\uc804\ud55c \uc77c\ubd80\ub85c \uacc4\uc18d \ubcf4\uc7a5\ub429\ub2c8\ub2e4. \uc0c8 \ucf54\ub4dc\uc5d0\uc11c \ub2e8\uc21c \uc0c1\uc218\xb7\ud329\ud1a0\ub9ac\ub294 \ube14\ub85d\uc744 \uc120\ud638\ud558\ub294 \ubc29\ud5a5\uc774 \ub418\uaca0\uc9c0\ub9cc, \uc11c\ub450\ub97c \uc774\uc720\uac00 \uc5c6\uc2b5\ub2c8\ub2e4.\\n- **interface \uad6c\ud604 companion\uc740 object \uc720\uc9c0**: companion\uc774 \uc778\ud130\ud398\uc774\uc2a4\ub97c \uad6c\ud604\ud574\uc57c \ud558\uba74(\uc608: \ucf5c\ubc31 \uc778\ud130\ud398\uc774\uc2a4 \uad6c\ud604) companion object\uac00 \uc720\uc77c\ud55c \uc120\ud0dd\uc9c0\uc785\ub2c8\ub2e4. \ube14\ub85d\uc740 \uac1d\uccb4\uac00 \uc544\ub2c8\ub77c\uc11c \uc548 \ub429\ub2c8\ub2e4.\\n- **\uc62e\uae30\ub824\uba74 \uc7ac\ucef4\ud30c\uc77c\uc774 \ud544\uc218**: `object` \ud0a4\uc6cc\ub4dc\ub97c \uc9c0\uc6b0\ub294 \uac8c \ub300\ubd80\ubd84 \ucda9\ubd84\ud558\uc9c0\ub9cc, \ud504\ub85c\uc81d\ud2b8\uc640 \uc758\uc874\ud558\ub294 \ucf54\ub4dc \uc804\uccb4\ub97c \ub2e4\uc2dc \ucef4\ud30c\uc77c\ud574\uc57c \ud569\ub2c8\ub2e4. R8/ProGuard \uaddc\uce59\uc5d0\uc11c `Companion`\uc744 \ucc38\uc870\ud558\ub358 \ub8f0\uc774 \uc788\ub2e4\uba74 \uac19\uc774 \uc810\uac80\ud574\uc57c \ud569\ub2c8\ub2e4. \uc0dd\ud0dc\uacc4 \ud234\ub9c1(\uc815\uc801 \ubd84\uc11d, \uc77c\ubd80 \ud50c\ub7ec\uadf8\uc778)\uc774 \uc544\uc9c1 \ube14\ub85d\uc744 \ubabb \uc54c\uc544\ubcfc \uc218 \uc788\ub2e4\ub294 \uc810\ub3c4 \ubc1c\ud45c\uc5d0\uc11c \uc5b8\uae09\ub410\uc2b5\ub2c8\ub2e4.\\n- **Android \uad00\uc810\uc758 \uad00\uc804 \ud3ec\uc778\ud2b8**: Activity/Fragment\uc758 `newInstance`, `TAG` \uc0c1\uc218, `CREATOR` \uac19\uc740 \uc0c1\uc6a9\uad6c\uc5d0\uc11c \ubc14\uc774\ud2b8\ucf54\ub4dc\uac00 \uae54\ub054\ud574\uc9d1\ub2c8\ub2e4. \ud6a8\uacfc\ub294 \uc791\uc9c0\ub9cc \uc571 \uc804\uccb4\uc5d0 \ud769\uc5b4\uc9c4 \uc0c1\uc6a9\uad6c\ub77c \ub204\uc801\ub418\uba74 \uc758\ubbf8\uac00 \uc788\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc DEX \uba54\uc11c\ub4dc \uc218\ub098 APK \ud06c\uae30\uc5d0\uc11c \ub4dc\ub77c\ub9c8\ud2f1\ud55c \ubcc0\ud654\ub294 \uae30\ub300\ud558\uc9c0 \uc54a\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c \uc774\ub807\uac8c \ud655\uc778\ud560 \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uc2e4\ud5d8 \ud50c\ub798\uadf8\ub97c \ucf1c\ub294 \ubc29\ubc95\uc740 \uc774\ub807\uc2b5\ub2c8\ub2e4. \uc544\uc9c1\uc740 \ud14c\uc2a4\ud2b8 \ubaa8\ub4c8\uc5d0\uc11c\ub9cc \uac74\ub4dc\ub824 \ubcfc \uc608\uc815\uc785\ub2c8\ub2e4.\\n\\n```kotlin\\n// app/build.gradle.kts (Kotlin DSL)\\nkotlin {\\n    compilerOptions {\\n        // companion \ube14\ub85d\ub9cc \ud5c8\uc6a9\\n        freeCompilerArgs.add(\\"-Xcompanion-blocks\\")\\n        // \ube14\ub85d + \ud655\uc7a5\uc744 \ubaa8\ub450 \ud5c8\uc6a9\\n        // freeCompilerArgs.add(\\"-Xcompanion-blocks-and-extensions\\")\\n    }\\n}\\n```\\n\\n```kotlin\\n// \uc2e4\ud5d8\ud574 \ubcfc \ud6c4\ubcf4 1: Fragment \ud329\ud1a0\ub9ac\\nclass DetailFragment : Fragment() {\\n    companion {\\n        private const val ARG_ID = \\"arg_id\\"\\n        fun newInstance(id: String) = DetailFragment().apply {\\n            arguments = bundleOf(ARG_ID to id)\\n        }\\n    }\\n}\\n\\n// \uc2e4\ud5d8\ud574 \ubcfc \ud6c4\ubcf4 2: \uc778\ud130\ud398\uc774\uc2a4 \uad6c\ud604\uc774 \ud544\uc694\ud558\uba74 object \uc720\uc9c0\\nclass AnalyticsTracker {\\n    companion object : EventSink {  // \ube14\ub85d\uc73c\ub85c\ub294 \uc548 \ub428\\n        override fun sink(event: Event) { /* ... */ }\\n    }\\n}\\n```\\n\\n### \ucd9c\ucc98\\n\\n- [The Companions to Come \u2014 Kotlin Blog (JetBrains, 2026-09-30)](https://blog.jetbrains.com/kotlin/2026/09/the-companions-to-come/) \u2014 companion \ube14\ub85d\xb7\ud655\uc7a5\uc758 \uc2e4\ud5d8 \ub3c4\uc785, \ucef4\ud30c\uc77c\ub7ec \ud50c\ub798\uadf8, companion object \uacf5\uc874 \uc815\ucc45\\n- KEEP-0449 \u2014 \uc804\uccb4 \uc124\uacc4 \uc81c\uc548\uc11c (\uc704 \uae00\uc5d0\uc11c \ub9c1\ud06c)"},{"id":"androidx-remote-compose-alpha21","metadata":{"permalink":"/blog/posts/androidx-remote-compose-alpha21","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-12-androidx-remote-compose-alpha21/index.mdx","source":"@site/blog/2026-10-12-androidx-remote-compose-alpha21/index.mdx","title":"Remote Compose 1.0.0-alpha21 \u2014 10\uc6d4 AndroidX \ub9b4\ub9ac\uc2a4\uc5d0\uc11c \ubcf8 \uc11c\ubc84 \uad6c\ub3d9 UI\uc758 \ud604\uc7ac \uc704\uce58","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-12T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"androidx","permalink":"/blog/posts/tags/androidx"},{"inline":true,"label":"compose","permalink":"/blog/posts/tags/compose"},{"inline":true,"label":"release","permalink":"/blog/posts/tags/release"}],"readingTime":4.45,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"androidx-remote-compose-alpha21","title":"Remote Compose 1.0.0-alpha21 \u2014 10\uc6d4 AndroidX \ub9b4\ub9ac\uc2a4\uc5d0\uc11c \ubcf8 \uc11c\ubc84 \uad6c\ub3d9 UI\uc758 \ud604\uc7ac \uc704\uce58","authors":["way"],"tags":["android","androidx","compose","release"]},"unlisted":false,"prevItem":{"title":"Kotlin 2.5.0\uc5d0 companion \ube14\ub85d\uc774 \uc628\ub2e4 \u2014 companion object\uc640 \ubb34\uc5c7\uc774 \ub2e4\ub978\uac00","permalink":"/blog/posts/kotlin-companion-blocks"},"nextItem":{"title":"Play \ud0c0\uae43 API 36 \uc81c\ucd9c \ucc28\ub2e8\uc774 \ud604\uc2e4\ud654\ub410\ub2e4 \u2014 11\uc6d4 1\uc77c \uc5f0\uc7a5 \uc2e0\uccad\uacfc \ub300\uc751 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","permalink":"/blog/posts/play-target-api-36-deadline"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 7\uc77c, AndroidX \uc815\uae30 \ub9b4\ub9ac\uc2a4 \ubc30\uce58\uac00 \ub098\uc654\uc2b5\ub2c8\ub2e4. \uadf8\uc911\uc5d0\uc11c\ub3c4 \ub208\uc5d0 \ub744\ub294 \uac74 `remote-compose 1.0.0-alpha21`\uacfc `compose.remote.foundation 1.0.0-alpha04`\uc785\ub2c8\ub2e4. Remote Compose\ub294 \uc11c\ubc84 \uad6c\ub3d9 UI(Server-Driven UI)\ub97c \uc704\ud55c Jetpack \ub77c\uc774\ube0c\ub7ec\ub9ac\uc778\ub370, \ub9b4\ub9ac\uc2a4 \ub178\ud2b8\ub97c \uc77d\ub2e4 \ubcf4\uba74 \\"\uc5d0\uc774\uc804\ud2b8\uac00 \ub9cc\ub4e0 UI\ub97c \uc571 \uc5c5\ub370\uc774\ud2b8 \uc5c6\uc774 \ub0b4\ub824\ubc1b\uc544 \uadf8\ub9ac\ub294\\" \ud750\ub984\uc774 \uc810\uc810 \ud604\uc2e4\ud654\ub418\uace0 \uc788\ub2e4\ub294 \ub290\ub08c\uc744 \ubc1b\uc2b5\ub2c8\ub2e4. \uc774\ubc88 \uae00\uc5d0\uc11c\ub294 Remote Compose \uc54c\ud30c21\uc758 \ubcc0\uacbd\uc810\uc744 \uc911\uc2ec\uc73c\ub85c, \uac19\uc774 \ubb36\uc5ec \ub098\uc628 10\uc6d4 \ubc30\uce58\uc758 \uc2e4\ubb34 \ud3ec\uc778\ud2b8\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- Remote Compose 1.0.0-alpha21: \ub77c\uc774\ud2b8/\ub2e4\ud06c \ud14c\ub9c8 \uc778\uc2dd \uc0c9\uc0c1, \ud14d\uc2a4\ud2b8 \ud06c\uae30 \uce21\uc815 API, `RemoteDocumentPreview` \uc124\uc815 \ud655\uc7a5, \uc6d0\ud615 \ud14d\uc2a4\ud2b8 \ub80c\ub354\ub9c1 \uc9c0\uc6d0, DEFLATE \uc555\ucd95 \ubb38\uc11c \ub85c\ub529 \ub4f1.\\n- \uc0c8\ub85c \ub4f1\uc7a5\ud55c `compose.remote.foundation 1.0.0-alpha04`\uae4c\uc9c0 \ud569\uce58\uba74, \\"\uc11c\ubc84\uc5d0\uc11c UI \ubb38\uc11c\ub97c \ub0b4\ub824\ubc1b\uc544 \uadf8\ub300\ub85c \uadf8\ub9b0\ub2e4\\"\ub294 \uadf8\ub9bc\uc774 Jetpack \ub808\ubca8\uc5d0\uc11c \uc815\ube44\ub418\ub294 \uc911\uc785\ub2c8\ub2e4.\\n- \uac19\uc740 \ubc30\uce58\uc758 Compose 1.13.0-beta01\uc740 \uc774\uc81c Kotlin 2.2\ub97c \ud0c0\uae43\uc73c\ub85c \ud558\uba70 kotlinc 2.2\ub97c \uc694\uad6c\ud569\ub2c8\ub2e4. \ubca0\ud0c0\ub97c \uc62c\ub9b4 \uacc4\ud68d\uc774\ub77c\uba74 \ucef4\ud30c\uc77c\ub7ec \ubc84\uc804\ub3c4 \uac19\uc774 \ubd10\uc57c \ud569\ub2c8\ub2e4.\\n- `appfunctions 1.0.0-alpha13`\uc740 API \ub9ac\ub124\uc784\uc774 \uc788\uc2b5\ub2c8\ub2e4. `AppFunction` \uc5b4\ub178\ud14c\uc774\uc158\uc774 `AppFunctionDeclaration`\uc73c\ub85c \ubc14\ub00c\uc5c8\uc73c\ub2c8, \uc54c\ud30c\ub97c \uc2e4\ud5d8 \uc911\uc778 \ud504\ub85c\uc81d\ud2b8\ub294 \ub9b4\ub9ac\uc2a4 \ub178\ud2b8\ub97c \ud655\uc778\ud558\uace0 \uc62c\ub9ac\uc138\uc694.\\n- `collection 1.7.0` \uc2a4\ud14c\uc774\ube14\uc5d0\ub294 `ScatterMap` \uc131\ub2a5 \uac1c\uc120\uacfc \uc6d0\uc2dc \ud0c0\uc785 \ub9ac\uc2a4\ud2b8 \uc815\ub82c/\uc774\uc9c4 \ud0d0\uc0c9 \ucd94\uac00\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### Remote Compose 1.0.0-alpha21\\n\\n**\ud14c\ub9c8 \uc778\uc2dd \uc6d0\uaca9 \uc0c9\uc0c1**\\n\\n`RemoteColor.Companion`\uc5d0 `createThemedRemoteColor`\uac00 \ucd94\uac00\ub410\uc2b5\ub2c8\ub2e4. \uc11c\ubc84\uc5d0\uc11c \ub0b4\ub824\ubc1b\uc740 \ubb38\uc11c\uac00 \ud074\ub77c\uc774\uc5b8\ud2b8\uc758 \ub77c\uc774\ud2b8/\ub2e4\ud06c \ud14c\ub9c8\ub97c \ub530\ub77c \uc0c9\uc0c1\uc744 \ubc14\uafc0 \uc218 \uc788\uac8c \ub418\ub294 \uac81\ub2c8\ub2e4. \uc11c\ubc84 \uad6c\ub3d9 UI\uc5d0\uc11c \uac00\uc7a5 \uc790\uc8fc \uc694\uad6c\ub418\ub294 \\"\ub2e4\ud06c \ubaa8\ub4dc \ub300\uc751\\"\uc744 \ud50c\ub808\uc774\uc5b4 \ucabd\uc774 \ud574\uacb0\ud574 \uc8fc\ub2c8, \ubb38\uc11c \uc0dd\uc131 \ub85c\uc9c1\uc5d0\uc11c \ubd84\uae30\ud560 \ud544\uc694\uac00 \uc904\uc5b4\ub4ed\ub2c8\ub2e4.\\n\\n**\ud14d\uc2a4\ud2b8 \uce21\uc815 API**\\n\\n`RemoteTextMeasurer`\uc640 `rememberRemoteTextMeasurer`\uac00 \uc0c8\ub85c \ub4e4\uc5b4\uc654\uc2b5\ub2c8\ub2e4. Remote Compose \ubb38\uc11c \uc548\uc5d0\uc11c \ud14d\uc2a4\ud2b8\uc758 \uc2e4\uc81c \ub80c\ub354\ub9c1 \ud06c\uae30\ub97c \uc7b4 \uc218 \uc788\uac8c \ub41c \uac83\uc73c\ub85c, \ubb38\uc11c \uc0dd\uc131 \uc2dc\uc810\uc5d0 \ud14d\uc2a4\ud2b8 \uae38\uc774\uc5d0 \ub530\ub77c \ub808\uc774\uc544\uc6c3\uc744 \uc870\uc815\ud574\uc57c \ud558\ub294 \uacbd\uc6b0(\uc608: \ubc30\uc9c0, \ub3d9\uc801 \ub77c\ubca8) \uc720\uc6a9\ud569\ub2c8\ub2e4. `Float.rsp`/`RemoteFloat.rsp` \ud655\uc7a5 \ud504\ub85c\ud37c\ud2f0\ub3c4 \ucd94\uac00\ub3fc\uc11c Sp \ub2e8\uc704\uc758 `RemoteTextUnit`\uc744 \ub9ac\ud130\ub7f4\uc774\ub098 \ub3d9\uc801 \ud45c\ud604\uc2dd\uc5d0\uc11c \ubc14\ub85c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n**\ubb38\uc11c \uc0dd\uc131\xb7\ubbf8\ub9ac\ubcf4\uae30 \uac1c\uc120**\\n\\n- `RemoteDocumentPreview`\uc5d0 `profile` \ud30c\ub77c\ubbf8\ud130\uac00 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4. \ubb38\uc11c \ubc84\ud37c\ub97c \ud33d\ucc3d\uc2dc\ud0a4\uae30 \uc804\uc5d0 \uc124\uc815\uc744 \uc870\uc815\ud560 \uc218 \uc788\uc5b4, \ud14c\uc2a4\ud2b8\xb7\ub514\ubc84\uae45 \ud658\uacbd\uc5d0\uc11c \ubb38\uc11c \uc0dd\uc131\uc744 \uc138\ubc00\ud558\uac8c \uc81c\uc5b4\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- \ud50c\ub808\uc774\uc5b4\uc640 \ud14c\uc2a4\ud2b8 \ud504\ub85c\ud30c\uc77c\uc774 `DrawTextOnCircle`\uc744 \uc9c0\uc6d0\ud569\ub2c8\ub2e4. \uc6d0\ud615 \uacbd\ub85c\uc5d0 \ud14d\uc2a4\ud2b8\ub97c \uadf8\ub9ac\ub294 \uc5f0\ucd9c\uc774 \uc774\uc81c \uc6d0\uaca9 \ubb38\uc11c\uc5d0\uc11c\ub3c4 \uae68\uc9c0\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n- DEFLATE\ub85c \uc555\ucd95\ub41c \ubb38\uc11c\ub97c \ud50c\ub808\uc774\uc5b4\uac00 \ub85c\ub4dc\ud560 \uc218 \uc788\uac8c \ub410\uc2b5\ub2c8\ub2e4. \ubb38\uc11c \ud06c\uae30\uac00 \ud06c\ub2e4\uba74 \uc804\uc1a1\ub7c9\uc744 \uc904\uc774\ub294 \ubc29\ud5a5\uc73c\ub85c \uc124\uacc4\ud560 \uc5ec\uc9c0\uac00 \uc0dd\uae41\ub2c8\ub2e4.\\n- `captureSingleRemoteDocument`/`captureRemoteDocument`\uc758 \ub77c\uc774\ud504\uc0ac\uc774\ud074\uacfc \uc2a4\ub0c5\uc0f7 \ucc98\ub9ac\uac00 \ub2e4\uc838\uc84c\uace0, \uc218\uc9d1 \uc18d\ub3c4\uac00 \ub9ac\ucef4\ud3ec\uc9c0\uc158\uc744 \ub530\ub77c\uac00\uc9c0 \ubabb\ud560 \ub54c \uc5c5\ub370\uc774\ud2b8\uac00 \uc870\uc6a9\ud788 \ub204\ub77d\ub418\ub358 \ubc84\uadf8\ub3c4 \uc218\uc815\ub410\uc2b5\ub2c8\ub2e4. \uc11c\ubc84 \uad6c\ub3d9 UI\uc5d0\uc11c \\"\uac00\ub054 \ud654\uba74\uc774 \uc548 \ubc14\ub00c\ub294\\" \uc2dd\uc758 \uac04\ud5d0\uc801 \uc774\uc288\uac00 \uc904\uc5b4\ub4e4 \uac83\uc73c\ub85c \ubcf4\uc785\ub2c8\ub2e4.\\n- \ucee4\uc2a4\ud140 \uc9c4\uc785/\uc885\ub8cc \uac00\uc2dc\uc131 \uc560\ub2c8\uba54\uc774\uc158 \uc9c0\uc6d0, \uc2a4\ud504\ub9c1 \uc560\ub2c8\uba54\uc774\uc158\uc758 \uc2a4\ub0c5\xb7\ubc94\uc704 \uc774\ud0c8 \ubc84\uadf8 \uc218\uc815 \ub4f1 \ub80c\ub354\ub9c1 \ud488\uc9c8 \ucabd\ub3c4 \uc5ec\ub7ec \uac74 \uc7a1\ud614\uc2b5\ub2c8\ub2e4.\\n\\n**compose.remote.foundation 1.0.0-alpha04**\\n\\n\uac19\uc740 \ubc30\uce58\uc5d0 `androidx.compose.remote.foundation`\uc758 \uc0c8 \uc54c\ud30c\uac00 \uac19\uc774 \ub098\uc654\uc2b5\ub2c8\ub2e4. \uc758\uc874\uc131\uc740 \ub2e4\uc74c\uacfc \uac19\uc774 \uc120\uc5b8\ud569\ub2c8\ub2e4.\\n\\n```kotlin\\ndependencies {\\n    implementation(\\"androidx.compose.remote.foundation:foundation:1.0.0-alpha04\\")\\n}\\n```\\n\\n#### \uac19\uc774 \ub098\uc628 \uac83\ub4e4\\n\\n- **Compose 1.13.0-beta01 (animation/foundation/material/runtime)**: \uc774\ubc88 \ubc30\uce58\ubd80\ud130 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 Kotlin 2.2\ub97c \ud0c0\uae43\uc73c\ub85c \ud558\uace0 kotlinc 2.2\ub97c \uc694\uad6c\ud569\ub2c8\ub2e4. \ubca0\ud0c0\ub97c \uc62c\ub9b4 \ub54c\ub294 Kotlin \ubc84\uc804\uc744 2.2 \uc774\uc0c1\uc73c\ub85c \uc62c\ub824\uc57c \ucef4\ud30c\uc77c\uc774 \ub429\ub2c8\ub2e4.\\n- **appfunctions 1.0.0-alpha13**: `@AppFunction` \u2192 `@AppFunctionDeclaration`, `ObserveAppFunctionsEvent` \u2192 `AppFunctionsChangeEvent`\ub85c \ub9ac\ub124\uc784\ub410\uace0, \uc811\uadfc \ub808\ubca8 \uc81c\ud55c\uc744 \uc704\ud55c `@AppFunctionAccessLevel`\uc774 \ucd94\uac00\ub410\uc2b5\ub2c8\ub2e4. \uc5d0\uc774\uc804\ud2b8\xb7Gemini \uc2dc\ub300\uc758 \uc571 \uae30\ub2a5 \ub178\ucd9c \uc778\ud130\ud398\uc774\uc2a4\ub77c \uc2e4\ud5d8 \uc911\uc774\ub77c\uba74 \uc774\ub984 \ubc14\ub010 \uac83\ub9cc \ud655\uc778\ud558\uba74 \ub429\ub2c8\ub2e4.\\n- **collection 1.7.0 (\uc2a4\ud14c\uc774\ube14)**: `toOrderedScatterSet()` \ud655\uc7a5(\ube48 \uc18c\uc2a4\uc5d0\uc120 \ud560\ub2f9 \uc5c6\ub294 \uc2f1\uae00\ud134 \ubc18\ud658), `ScatterMap.getOrPut()` \ucd5c\uc801\ud654, `Float` \ud0a4 \ud574\uc2dc \ucda9\ub3cc \uac1c\uc120, \uc6d0\uc2dc \ud0c0\uc785 \ub9ac\uc2a4\ud2b8(`IntList`/`LongList` \ub4f1)\uc5d0 `sortWith`/`sortBy`/`binarySearch` \ucd94\uac00. \ud37c\ud3ec\uba3c\uc2a4\uc5d0 \ubbfc\uac10\ud55c \ub370\uc774\ud130 \uad6c\uc870\ub97c \uc4f0\ub294 \ud300\uc740 \ubcc4\ub3c4 \ubcc0\uacbd \uc5c6\uc774 \uc774\ub4dd\uc744 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- **benchmark 1.6.0-alpha01**: `:lockClocks` \ud0dc\uc2a4\ud06c\uac00 root \uc5c6\uc774\ub3c4 \uace0\uc815 \uc131\ub2a5 \ubaa8\ub4dc\ub97c \uc4f8 \uc218 \uc788\uac8c \ub3fc\uc11c, \ub354 \ub9ce\uc740 \uc2e4\uae30\uae30\uc5d0\uc11c \uc548\uc815\uc801\uc778 \ub9c8\uc774\ud06c\ub85c\ubca4\uce58\ub9c8\ud06c\uac00 \uac00\ub2a5\ud569\ub2c8\ub2e4. \ud788\ud504 \ud504\ub85c\ud30c\uc77c\ub9c1\uc6a9 `MemoryProfilingConfig`\ub3c4 \ucd94\uac00\ub410\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **Remote Compose\ub294 \uc544\uc9c1 \uc54c\ud30c\uc785\ub2c8\ub2e4.** API\uac00 \ubc14\ub014 \uc218 \uc788\ub2e4\ub294 \uc804\uc81c\ub85c \uc2e4\ud5d8\xb7\ud504\ub85c\ud1a0\ud0c0\uc785 \uc218\uc900\uc5d0\uc11c \uc811\uadfc\ud558\ub294 \uac8c \ub9de\uc2b5\ub2c8\ub2e4. \ub2e4\ub9cc \ud14c\ub9c8 \uc778\uc2dd, \ud14d\uc2a4\ud2b8 \uce21\uc815, \uc555\ucd95 \ubb38\uc11c \ub85c\ub529\ucc98\ub7fc \\"\uc6b4\uc601\uc5d0 \uc4f0\ub824\uba74 \uaf2d \uc788\uc5b4\uc57c \ud560\\" \uae30\ub2a5\ub4e4\uc774 \ucc28\ub840\ub85c \ub4e4\uc5b4\uc624\uace0 \uc788\uc5b4\uc11c, \ubc29\ud5a5\uc131 \uc790\uccb4\ub294 \uaf64 \uc9c4\uc9c0\ud558\uac8c \ubcf4\uc785\ub2c8\ub2e4.\\n- **\uc5d0\uc774\uc804\ud2b8 \uc2dc\ub300\uc758 SDUI**: \ucd5c\uadfc Android CLI\uc640 \uc5d0\uc774\uc804\ud2b8 \uc2a4\ud0ac \ud750\ub984\uacfc \ub9de\ubb3c\ub824, \\"\uc5d0\uc774\uc804\ud2b8\uac00 \uc0dd\uc131\ud55c UI\ub97c \uc5b4\ub5bb\uac8c \uc571\uc5d0 \uadf8\ub9b4 \uac83\uc778\uac00\\"\uac00 \uc2e4\ubb34 \uc9c8\ubb38\uc774 \ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. Remote Compose\ub294 \uadf8 \ub2f5 \uc911 \ud558\ub098\uc785\ub2c8\ub2e4. \ub2f9\uc7a5 \ub3c4\uc785\ud558\uc9c0 \uc54a\ub354\ub77c\ub3c4 \uac1c\ub150\uacfc \ud50c\ub808\uc774\uc5b4 \uad6c\uc870\ub294 \ud55c \ubc88 \ud6d1\uc5b4\ub458 \ub9cc\ud569\ub2c8\ub2e4.\\n- **Compose 1.13 \ubca0\ud0c0 + Kotlin 2.2**: \ucef4\ud30c\uc77c\ub7ec \ubc84\uc804 \uc694\uad6c\uc0ac\ud56d\uc774 \uac19\uc774 \uc62c\ub77c\uac04 \ub9b4\ub9ac\uc2a4\ub77c\uc11c, \ubc84\uc804\ub9cc \uc62c\ub838\ub2e4\uac00 \ube4c\ub4dc\uac00 \uae68\uc9c0\ub294 \uacbd\uc6b0\uac00 \uc0dd\uae38 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ubca0\ud0c0\ub97c \uc4f8 \uac70\uba74 `libs.versions.toml`\uc758 Kotlin \ubc84\uc804\ub3c4 \ud568\uaed8 \uc62c\ub9bd\ub2c8\ub2e4.\\n- **appfunctions \ub9ac\ub124\uc784**: \uc54c\ud30c \uc2e4\ud5d8 \uc911\uc774\ub77c\uba74 \ucef4\ud30c\uc77c \uc5d0\ub7ec\uac00 \ub098\ub294 \uac8c \uc815\uc0c1\uc774\ub2c8, \uc774\ub984\ub9cc \ubc14\uafd4 \uc8fc\uba74 \ub429\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c \uc774\ub807\uac8c \uc368\ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\ub2f9\uc7a5\uc740 \ud504\ub85c\ub355\uc158 \ub3c4\uc785\uc774 \uc544\ub2c8\ub77c \uad00\uce21 \ubaa8\ub4dc\uc785\ub2c8\ub2e4. SDK 36 \ub300\uc751 \uac19\uc740 \uae09\ud55c \uc77c\uc5d0 \ubc00\ub824 \uc190\uc774 \uc548 \uac00\uaca0\uc9c0\ub9cc, \uc2a4\ud504\ub9b0\ud2b8 \uc0ac\uc774\uc5d0 \uc791\uc740 \uc2e4\ud5d8 \ud504\ub85c\uc81d\ud2b8 \ud558\ub098\ub85c Remote Compose \ud50c\ub808\uc774\uc5b4\uc5d0 \ubb38\uc11c \ud558\ub098 \ub744\uc6cc \ubcf4\ub294 \uac74 \ud574\ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4. \uad00\uc804 \ud3ec\uc778\ud2b8\ub294 \ub450 \uac00\uc9c0\uc785\ub2c8\ub2e4.\\n\\n1. \uc11c\ubc84\uc5d0\uc11c \ubcf4\ub0b8 \ubb38\uc11c\uac00 \ub2e4\ud06c \ud14c\ub9c8\uc5d0\uc11c \uae68\uc9c0\uc9c0 \uc54a\ub294\uc9c0 (`createThemedRemoteColor` \uc0ac\uc6a9)\\n2. \ud14d\uc2a4\ud2b8 \uae38\uc774 \uac00\ubcc0\uc801\uc778 \ubc30\uc9c0 UI\ub97c `RemoteTextMeasurer`\ub85c \uc81c\ub300\ub85c \uadf8\ub9b4 \uc218 \uc788\ub294\uc9c0\\n\\n```kotlin\\n// gradle/libs.versions.toml\\n[versions]\\nandroidxRemoteCompose = \\"1.0.0-alpha21\\"\\ncomposeRemoteFoundation = \\"1.0.0-alpha04\\"\\n```\\n\\n\uc5d0\uc774\uc804\ud2b8\uac00 UI\ub97c \ub9cc\ub4dc\ub294 \uc2dc\ub300\uac00 \uc624\uace0 \uc788\ub294\ub370, \\"\uc5b4\ub5bb\uac8c \uadf8\ub9b4 \uac83\uc778\uac00\\"\ub294 \uc5ec\uc804\ud788 \uc571 \uac1c\ubc1c\uc790\uc758 \ubaab\uc785\ub2c8\ub2e4. Remote Compose\uac00 \uadf8 \ubaab\uc744 \ub098\ub220 \uac00\uc9c8 \ud6c4\ubcf4 \uc911 \ud558\ub098\ub77c\ub294 \uc810\uc5d0\uc11c, \uc774\ubc88 \ub9b4\ub9ac\uc2a4\ub294 \uc9c0\ucf1c\ubcfc \uac00\uce58\uac00 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\n10\uc6d4 AndroidX \ubc30\uce58\ub294 \\"UI\ub97c \ucf54\ub4dc\uac00 \uc544\ub2c8\ub77c \ubb38\uc11c\ub85c \ub2e4\ub8e8\ub294\\" \ucabd\uc73c\ub85c \ucd95\uc774 \uc774\ub3d9\ud558\uace0 \uc788\uc74c\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4. Remote Compose \uc54c\ud30c21\uc758 \ubcc0\uacbd\uc810 \ub300\ubd80\ubd84\uc774 \ub80c\ub354\ub9c1 \ud488\uc9c8\uacfc \uc6b4\uc601 \ud3b8\uc758(\ud14c\ub9c8, \uc555\ucd95, \uce21\uc815)\uc5d0 \uc9d1\uc911\ub3fc \uc788\ub2e4\ub294 \uc810\uc774 \uadf8 \uc2e0\ud638\uc785\ub2c8\ub2e4. \ubc14\ub85c \uc4f8 \ud544\uc694\ub294 \uc5c6\uc9c0\ub9cc, \ub2e4\uc74c\uc5d0 SDUI\ub97c \uace0\ubbfc\ud560 \ub54c \uc120\ud0dd\uc9c0\uc5d0 \ub123\uc5b4\ub450\uae30 \uc88b\uc740 \ud0c0\uc774\ubc0d\uc785\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [AndroidX latest release notes](https://mahozad.ir/androidx-release-notes/) (2026-10-07 \ubc30\uce58: remote-compose 1.0.0-alpha21, compose.remote.foundation 1.0.0-alpha04, appfunctions 1.0.0-alpha13, collection 1.7.0, Compose 1.13.0-beta01 \ub4f1)\\n> \ucd9c\ucc98: [Compose Remote Foundation \u2014 developer.android.com](https://developer.android.com/jetpack/androidx/releases/compose-remote-foundation)"},{"id":"play-target-api-36-deadline","metadata":{"permalink":"/blog/posts/play-target-api-36-deadline","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-12-play-target-api-36-deadline/index.mdx","source":"@site/blog/2026-10-12-play-target-api-36-deadline/index.mdx","title":"Play \ud0c0\uae43 API 36 \uc81c\ucd9c \ucc28\ub2e8\uc774 \ud604\uc2e4\ud654\ub410\ub2e4 \u2014 11\uc6d4 1\uc77c \uc5f0\uc7a5 \uc2e0\uccad\uacfc \ub300\uc751 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-12T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"play","permalink":"/blog/posts/tags/play"},{"inline":true,"label":"target-sdk","permalink":"/blog/posts/tags/target-sdk"},{"inline":true,"label":"release","permalink":"/blog/posts/tags/release"}],"readingTime":4.35,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"play-target-api-36-deadline","title":"Play \ud0c0\uae43 API 36 \uc81c\ucd9c \ucc28\ub2e8\uc774 \ud604\uc2e4\ud654\ub410\ub2e4 \u2014 11\uc6d4 1\uc77c \uc5f0\uc7a5 \uc2e0\uccad\uacfc \ub300\uc751 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","authors":["way"],"tags":["android","play","target-sdk","release"]},"unlisted":false,"prevItem":{"title":"Remote Compose 1.0.0-alpha21 \u2014 10\uc6d4 AndroidX \ub9b4\ub9ac\uc2a4\uc5d0\uc11c \ubcf8 \uc11c\ubc84 \uad6c\ub3d9 UI\uc758 \ud604\uc7ac \uc704\uce58","permalink":"/blog/posts/androidx-remote-compose-alpha21"},"nextItem":{"title":"SharedPreferences\uc5d0\uc11c DataStore\ub85c \uc62e\uae30\uace0 \uc22b\uc790\ub85c \uc99d\uba85\ud558\uae30 \u2014 \ub300\uaddc\ubaa8 \uc571\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc2e4\uce21 \uc0ac\ub840","permalink":"/blog/posts/datastore-migration-benchmark"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 8\uc6d4 31\uc77c\uc744 \uae30\uc810\uc73c\ub85c, Google Play\uc5d0 \uc81c\ucd9c\ub418\ub294 \uc2e0\uaddc \uc571\uacfc \uc571 \uc5c5\ub370\uc774\ud2b8\ub294 Android 16(API 36) \ud0c0\uae43\uc774 \ud544\uc218 \uc870\uac74\uc774 \ub410\uc2b5\ub2c8\ub2e4. \uacbd\uace0\ub85c \ub05d\ub098\ub294 \uc904 \uc54c\uc558\ub358 \ub9c8\uac10\uc77c\uc774 \uc774\uc81c\ub294 \uc2e4\uc81c\ub85c \uc5c5\ub85c\ub4dc\ub97c \ub9c9\ub294 \ub2e8\uacc4\uc5d0 \ub4e4\uc5b4\uc654\uc2b5\ub2c8\ub2e4. \ud55c \uc904\uc9dc\ub9ac \ud06c\ub798\uc2dc \ud56b\ud53d\uc2a4\ub3c4 `targetSdk`\ub97c 36\uc73c\ub85c \uc62c\ub9ac\uae30 \uc804\uae4c\uc9c0\ub294 \ucf58\uc194\uc5d0 \uc62c\ub77c\uac00\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc544\uc9c1 \ub300\uc751 \uc804\uc774\ub77c\uba74 11\uc6d4 1\uc77c\uae4c\uc9c0 \ud55c \ubc88\uc758 \uc5f0\uc7a5\uc744 \uc2e0\uccad\ud560 \uc218 \uc788\ub294\ub370, \uc774\uac83\ub3c4 \uc790\ub3d9\uc73c\ub85c \uc8fc\uc5b4\uc9c0\ub294 \uac74 \uc544\ub2d9\ub2c8\ub2e4. \uc774\ubc88 \uae00\uc5d0\uc11c\ub294 \uaddc\uce59\uc758 \uc815\ud655\ud55c \ub0b4\uc6a9\uacfc \ubc14\ub85c \uc2e4\ud589\ud560 \uc218 \uc788\ub294 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub97c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- 2026\ub144 8\uc6d4 31\uc77c \uc774\ud6c4, \uc2e0\uaddc \uc571\xb7\uc571 \uc5c5\ub370\uc774\ud2b8\ub294 Android 16(API \ub808\ubca8 36) \uc774\uc0c1\uc744 \ud0c0\uae43\ud574\uc57c Google Play\uc5d0 \uc81c\ucd9c\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. (Wear OS\xb7Android Automotive\ub294 API 35, Android TV\xb7Android XR\uc740 API 34)\\n- \uc774\ubbf8 \uc2a4\ud1a0\uc5b4\uc5d0 \uc788\ub294 \uc571\uc740 API 35 \uc774\uc0c1\uc744 \ud0c0\uae43\ud574\uc57c \ud0c0\uae43\ubcf4\ub2e4 \ub192\uc740 OS\ub97c \uc4f0\ub294 \uc2e0\uaddc \uc0ac\uc6a9\uc790\uc5d0\uac8c \uacc4\uc18d \ub178\ucd9c\ub429\ub2c8\ub2e4. API 34 \uc774\ud558\uc5d0 \uba38\ubb3c\uba74 \uc2e0\uaddc \uc0ac\uc6a9\uc790 \uc124\uce58\uac00 \uc870\uc6a9\ud788 \ub9c9\ud799\ub2c8\ub2e4.\\n- \uc2dc\uac04\uc774 \ubd80\uc871\ud558\uba74 Play Console\uc5d0\uc11c 2026\ub144 11\uc6d4 1\uc77c\uae4c\uc9c0\uc758 \uc5f0\uc7a5\uc744 \ud55c \ubc88 \uc2e0\uccad\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ud55c \ubc88\ubfd0\uc774\uace0, 11\uc6d4 1\uc77c\uc740 \ud655\uc815 \uae30\ud55c\uc785\ub2c8\ub2e4.\\n- `targetSdk`\ub9cc \ubc14\uafb8\ub294 \uac8c \ub05d\uc774 \uc544\ub2c8\ub77c, Android 16\uc758 \ub3d9\uc791 \ubcc0\uacbd(\uc5e3\uc9c0 \ud22c \uc5e3\uc9c0 \uc758\ubb34\ud654 \ub4f1)\uc5d0 \ub300\ud55c \ud68c\uadc0 \ud14c\uc2a4\ud2b8\uac00 \uc9c4\uc9dc \uc791\uc5c5\ub7c9\uc785\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### \uaddc\uce59\uc740 \uc81c\ucd9c \uc2dc\uc810\uc5d0 \ub9c9\ub294\ub2e4\\n\\n\uc774 \uc694\uad6c\uc0ac\ud56d\uc758 \ud3ec\uc778\ud2b8\ub294 \\"\uc2ec\uc0ac\\"\uac00 \uc544\ub2c8\ub77c \\"\uc81c\ucd9c\\" \ub2e8\uacc4\uc5d0\uc11c \uac78\ub9b0\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. Play Console\uc5d0 AAB\ub97c \uc62c\ub9ac\ub294 \uc21c\uac04 \ud0c0\uae43 API \uac80\uc0ac\uac00 \uba3c\uc800 \ub3cc\uc544\uac00\uace0, \uc870\uac74\uc744 \ubabb \ub9de\ucd94\uba74 \uc5c5\ub85c\ub4dc \uc790\uccb4\uac00 \uac70\ubd80\ub429\ub2c8\ub2e4. \uc989, \uc2ec\uc0ac \uc9c0\uc5f0\uc774 \uc544\ub2c8\ub77c \uc544\uc608 \ub9ac\ubdf0 \ub300\uae30\uc5f4\uc5d0 \ub4e4\uc5b4\uac00\uc9c0\ub3c4 \ubabb\ud569\ub2c8\ub2e4. \ud55c\ucc38 \uc804\uc5d0 \ub9cc\ub4e4\uc5b4 \ub454 \ube4c\ub4dc\ub97c \\"\uadf8\ub0e5 \uc62c\ub824\uc57c\uc9c0\\" \ud558\ub358 \ud300\uc740 \uc5ec\uae30\uc11c \ubc14\ub85c \ubc1c\ubaa9\uc774 \uc7a1\ud799\ub2c8\ub2e4.\\n\\n#### \uc138 \uac00\uc9c0 \uc0c1\ud0dc, \uc138 \uac00\uc9c0 \uae30\uc900\\n\\nGoogle\uc758 \ud0c0\uae43 API \uc815\ucc45\uc740 \uc571\uc758 \uc0c1\ud0dc\ub97c \uc774\ub807\uac8c \uad6c\ubd84\ud569\ub2c8\ub2e4.\\n\\n| \uc571 \uc0c1\ud0dc | \uc801\uc6a9 \uae30\uc900 |\\n|---|---|\\n| \uc2e0\uaddc \uc571(\uc544\uc9c1 \uac8c\uc2dc \uc548 \ub428) | \uccab \uc81c\ucd9c\ubd80\ud130 API 36 \uc774\uc0c1 (\ud734\ub300\ud3f0\xb7\ud0dc\ube14\ub9bf\xb7\ud3f4\ub354\ube14 \uae30\uc900) |\\n| \uae30\uc874 \uc571\uc758 \uc5c5\ub370\uc774\ud2b8 \uc81c\ucd9c | \ub300\uccb4 \ubc84\uc804 \uc81c\ucd9c \uc2dc API 36 \uc774\uc0c1 |\\n| \uae30\uc874 \uc571(\uc5c5\ub370\uc774\ud2b8 \uc548 \ud568) | API 35 \uc774\uc0c1\uc774\uc5b4\uc57c \uc2e0\uaddc \uc0ac\uc6a9\uc790\uc5d0\uac8c \ub178\ucd9c \uc720\uc9c0 |\\n\\n\\"\uae30\uc874 \uc571\uc740 API 35\uba74 \ub418\ub2c8\uae4c \uc5c5\ub370\uc774\ud2b8\ub3c4 35\uba74 \ub418\uc9c0 \uc54a\ub098?\\"\ub77c\uace0 \ucc29\uac01\ud558\uae30 \uc26c\uc6b4\ub370, \uadf8\ub807\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc5c5\ub370\uc774\ud2b8\ub97c \ud55c \ubc88\uc774\ub77c\ub3c4 \uc81c\ucd9c\ud558\uba74 \uadf8 \uc21c\uac04\ubd80\ud130 \uc2e0\uaddc \uc571\uacfc \uac19\uc740 API 36 \uae30\uc900\uc774 \uc801\uc6a9\ub429\ub2c8\ub2e4. API 35\ub294 \\"\uc544\ubb34\uac83\ub3c4 \uc548 \ud558\uace0 \ub194\ub46c\ub3c4 \uc2a4\ud1a0\uc5b4\uc5d0\uc11c \uc0ac\ub77c\uc9c0\uc9c0\ub294 \uc54a\uac8c \ud574\uc8fc\ub294\\" \uc644\ucda9\uc120\uc77c \ubfd0, \uc5c5\ub370\uc774\ud2b8 \uba74\uc81c\uad8c\uc774 \uc544\ub2d9\ub2c8\ub2e4.\\n\\n#### \uc5f0\uc7a5 \uc2e0\uccad: 11\uc6d4 1\uc77c\uae4c\uc9c0, \ud55c \ubc88\\n\\nPlay Console\uc5d0\uc11c \ud574\ub2f9 \uc571\uc758 \ud0c0\uae43 API \uacbd\uace0 \ud654\uba74\uc73c\ub85c \ub4e4\uc5b4\uac00\uba74 \uc5f0\uc7a5 \uc2e0\uccad \uc591\uc2dd\uc744 \ucc3e\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc2e0\uccad\uc774 \ubc1b\uc544\ub4e4\uc5ec\uc9c0\uba74 \uae30\ud55c\uc774 2026\ub144 11\uc6d4 1\uc77c\ub85c \ubbf8\ub904\uc9d1\ub2c8\ub2e4. \uc911\uc694\ud55c \uac74 \uc774 \uc5f0\uc7a5\uc774 \\"\uc790\ub3d9\\"\ub3c4 \uc544\ub2c8\uace0 \\"\ubc18\ubcf5\\"\ub3c4 \uc548 \ub41c\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. 11\uc6d4 1\uc77c \uc774\ud6c4\uc5d0\ub294 \ub2e4\uc2dc \uae30\uc900\uc774 \uc6d0\uc0c1\ubcf5\uadc0\ub429\ub2c8\ub2e4. \uc2e0\uccad \uc548 \ud558\uace0 \ubc84\ud2f0\uba74 \ud558\ub8e8\ub77c\ub3c4 \ub2a6\uc740 \ub0a0\ubd80\ud130 \uc81c\ucd9c\uc774 \ub9c9\ud788\ub2c8, \ub300\uc751 \uc77c\uc815\uc774 \ube60\ub4ef\ud558\ub2e4\uba74 \uc77c\ub2e8 \uc2e0\uccad\ubd80\ud130 \ud574\ub450\uace0 \uac1c\ubc1c\uc744 \uc9c4\ud589\ud558\ub294 \uac8c \ud569\ub9ac\uc801\uc785\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **\uc22b\uc790 \ubc14\uafb8\ub294 \uac74 1\ubd84, \ub3d9\uc791 \ubcc0\uacbd \ub300\uc751\uc774 \ubcf8\uac8c\uc784**: 2026\ub144 10\uc6d4 \ucd08\uc5d0 \uc138 \uac1c \uc571\uc744 API 36\uc73c\ub85c \uc62c\ub9b0 \uac1c\ubc1c\uc790\uc758 \ud68c\uace0\uc5d0 \ub530\ub974\uba74, `build.gradle.kts`\uc758 \uc22b\uc790 \ubcc0\uacbd\uc740 1\ubd84\uc774\uba74 \ub418\uc9c0\ub9cc \uc774\ud6c4 \uc791\uc5c5\uc5d0 \uc774\ud2c0\uc774 \uac78\ub838\ub2e4\uace0 \ud569\ub2c8\ub2e4. Android 16\uc5d0\uc11c\ub294 \uc5e3\uc9c0 \ud22c \uc5e3\uc9c0(Edge-to-Edge)\uac00 \uc758\ubb34\ud654\ub418\uace0, \ud0dc\ube14\ub9bf\xb7\ud3f4\ub354\ube14\uc5d0\uc11c\ub294 \ubc29\ud5a5 \uace0\uc815(orientation lock)\uc774 \ubb34\uc2dc\ub418\ub294 \ub4f1 \uc2e4\uc81c \ub3d9\uc791\uc774 \ubc14\ub00c\ub294 \uc9c0\uc810\uc774 \uc788\uc2b5\ub2c8\ub2e4. UI\uac00 \ud654\uba74 \ub05d\uae4c\uc9c0 \uadf8\ub824\uc9c0\ub294\uc9c0, \uc778\uc14b \ucc98\ub9ac\uac00 \uae68\uc9c0\uc9c0 \uc54a\ub294\uc9c0 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- **API 34 \uc774\ud558\uc5d0 \uba38\ubb34\ub974\uba74 \\"\uc870\uc6a9\ud788\\" \uc8fd\ub294\ub2e4**: \uc571\uc774 \uc2a4\ud1a0\uc5b4\uc5d0\uc11c \uac11\uc790\uae30 \uc0ad\uc81c\ub418\ub294 \uac8c \uc544\ub2c8\ub77c, \ud0c0\uae43\ubcf4\ub2e4 \ub192\uc740 OS \ubc84\uc804\uc744 \uc4f0\ub294 \uc2e0\uaddc \uc0ac\uc6a9\uc790\uc5d0\uac8c\ub9cc \ub178\ucd9c\uc774 \uc911\ub2e8\ub429\ub2c8\ub2e4. \uc124\uce58\uc728\uc774 \uc774\uc720 \uc5c6\uc774 \ub5a8\uc5b4\uc9c0\ub294 \uac83\ucc98\ub7fc \ubcf4\uc774\uae30 \ub54c\ubb38\uc5d0, \ubaa8\ub2c8\ud130\ub9c1\ub9cc \ubcf4\uace0 \uc788\uc73c\uba74 \uc6d0\uc778 \ud30c\uc545\uc774 \ub2a6\uc5b4\uc9d1\ub2c8\ub2e4. \uc6b0\ub9ac \uc571\uc758 \ud604\uc7ac `targetSdk`\ub97c Play Console \uc571 \ub300\uc2dc\ubcf4\ub4dc\uc5d0\uc11c \uba3c\uc800 \ud655\uc778\ud574 \ubcf4\uc138\uc694.\\n- **\uc5f0\uc7a5\uc740 \uacc4\ud68d\uc774 \uc544\ub2c8\ub2e4**: \uc5f0\uc7a5\uc744 \uc2e0\uccad\ud558\uba74 6\uc8fc \ub0a8\uc9d3\uc758 \uc2dc\uac04\uc744 \ubc84\ub294 \uac83\ubfd0\uc774\uace0, \uc791\uc5c5\ub7c9\uc740 \uadf8\ub300\ub85c\uc785\ub2c8\ub2e4. \uc5f0\uc7a5 \uc2b9\uc778\uc774 \ub0ac\ub2e4\ub294 \uc774\uc720\ub85c \ud68c\uadc0 \ud14c\uc2a4\ud2b8\ub97c \uc904\uc774\uba74 \ub098\uc911\uc5d0 \ub354 \uc544\ud515\ub2c8\ub2e4.\\n- **\uc5f0\uad00 \uac8c\uc774\ud2b8\ub3c4 \uac19\uc774 \ud655\uc778**: \uac19\uc740 \uc2dc\uae30, Play Billing\uc744 \uc4f0\ub294 \uc571\uc740 Billing Library 8.0.0 \uc774\uc0c1\uc774 \ub3d9\ubc18 \uc694\uad6c\ub418\uace0, \ub124\uc774\ud2f0\ube0c \ucf54\ub4dc\ub97c \ud3ec\ud568\ud558\ub294 \uc571\uc740 2027\ub144 2\uc6d4 1\uc77c\ubd80\ud130 16 KB \ud398\uc774\uc9c0 \uc0ac\uc774\uc988 \uc9c0\uc6d0 \uc5c6\uc774\ub294 \uc5c5\ub85c\ub4dc\uac00 \uac70\ubd80\ub429\ub2c8\ub2e4. `targetSdk` \uc62c\ub9b4 \ub54c \uac19\uc774 \uc810\uac80\ud558\uba74 \uc77c\uc815\uc744 \ud55c \ubc88\uc73c\ub85c \ud569\uce60 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c \uc774\ub807\uac8c \ud655\uc778\ud560 \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uae09\ud55c \uc21c\uc11c\ub300\ub85c \uccb4\ud06c\ub9ac\uc2a4\ud2b8\uc785\ub2c8\ub2e4.\\n\\n```kotlin\\n// app/build.gradle.kts (Kotlin DSL)\\nandroid {\\n    compileSdk = 36\\n    defaultConfig {\\n        minSdk = 24\\n        targetSdk = 36   // \u2190 \uc774 \uc22b\uc790. 8\uc6d4 31\uc77c \uc774\ud6c4 \uc81c\ucd9c \uc870\uac74\\n    }\\n}\\n```\\n\\n1. Play Console \u2192 \ud574\ub2f9 \uc571 \u2192 \uc815\ucc45/\ud0c0\uae43 API \uacbd\uace0 \ud654\uba74\uc5d0\uc11c \ud604\uc7ac \uc0c1\ud0dc \ud655\uc778\\n2. \uc544\uc9c1 36\uc774 \uc544\ub2c8\uba74 **\uc5f0\uc7a5 \uc2e0\uccad \ud3fc\ubd80\ud130 \uc81c\ucd9c** (11\uc6d4 1\uc77c\uae4c\uc9c0, \ud55c \ubc88)\\n3. `compileSdk`/`targetSdk` 36\uc73c\ub85c \uc62c\ub9ac\uace0 \uc5e3\uc9c0 \ud22c \uc5e3\uc9c0\xb7\uc778\uc14b\xb7\ubc29\ud5a5 \ucc98\ub9ac \ud68c\uadc0 \ud14c\uc2a4\ud2b8\\n4. Billing Library \ubc84\uc804(8.0.0+)\uacfc 16 KB \ud398\uc774\uc9c0 \uc0ac\uc774\uc988 \ub300\uc751 \uc5ec\ubd80\ub3c4 \uac19\uc740 \ud328\uc2a4\uc5d0 \ud655\uc778\\n\\n\ud15c\ud50c\ub9bf\uc774\ub098 \ud504\ub808\uc784\uc6cc\ud06c\uac00 \uc544\uc9c1 35\ub97c \uae30\ubcf8\uac12\uc73c\ub85c \uc4f0\uace0 \uc788\ub294 \uacbd\uc6b0\uac00 \ub9ce\uc73c\ub2c8, \uc2e0\uaddc \ud504\ub85c\uc81d\ud2b8\ub77c\uba74 \ud504\ub85c\uc81d\ud2b8 \uc0dd\uc131 \uc9c1\ud6c4 \uc774 \uc22b\uc790\ubd80\ud130 \ud655\uc778\ud558\ub294 \uc2b5\uad00\uc744 \ub4e4\uc774\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\n\ud0c0\uae43 API \ub9c8\uac10\uc77c\uc740 \ub9e4\ub144 \uc624\ub294 \ud589\uc0ac\uc9c0\ub9cc, \uc62c\ud574\ub294 \\"\uc81c\ucd9c \ucc28\ub2e8\\"\uc774\ub77c\ub294 \uc810\uc5d0\uc11c \uccb4\uac10 \uac15\ub3c4\uac00 \ub2e4\ub985\ub2c8\ub2e4. \ud2b9\ud788 API 34 \uc774\ud558\uc5d0 \uba38\ubb34\ub294 \uc571\uc740 \uc2e0\uaddc \uc0ac\uc6a9\uc790 \ub178\ucd9c\uc774 \uc870\uc6a9\ud788 \ub9c9\ud788\uae30 \ub54c\ubb38\uc5d0, \ubcc4\ub2e4\ub978 \uc774\uc0c1 \uc5c6\uc774 \uc124\uce58 \uc9c0\ud45c\uac00 \ub5a8\uc5b4\uc9c0\ub294 \uc0c1\ud669\uc774\uba74 `targetSdk`\ub97c \uba3c\uc800 \uc758\uc2ec\ud574 \ubcf4\uae38 \uad8c\ud569\ub2c8\ub2e4. \uc5f0\uc7a5\uc740 \ub9c8\uc9c0\ub9c9 \uc218\ub2e8\uc774 \uc544\ub2c8\ub77c, \uc77c\uc815 \ud655\ubcf4\ub97c \uc704\ud55c \uccab \ubc88\uc9f8 \ud589\ub3d9\uc785\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [Google Play\uc758 \ud0c0\uae43 API \ub808\ubca8 \uc694\uad6c\uc0ac\ud56d](https://support.google.com/googleplay/android-developer/answer/11926878) (2026-08-31 \uae30\uc900: \uc2e0\uaddc \uc571\xb7\uc5c5\ub370\uc774\ud2b8\ub294 API 36, Wear/Automotive\ub294 API 35, TV/XR\uc740 API 34 / 2026-11-01\uae4c\uc9c0 1\ud68c \uc5f0\uc7a5 \uac00\ub2a5)\\n> \ucd9c\ucc98: [Google Play API 36 deadline: app status and extension choices \u2014 OTF Blog](https://otf-kit.dev/blog/google-play-target-api-deadline-2026) (2026-10-10, \uae30\uc874 \uc571 API 35 \uae30\uc900\xb7\uc2e0\uaddc \uc81c\ucd9c API 36 \uad6c\ubd84 \uc815\ub9ac)"},{"id":"datastore-migration-benchmark","metadata":{"permalink":"/blog/posts/datastore-migration-benchmark","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-11-datastore-migration-benchmark/index.mdx","source":"@site/blog/2026-10-11-datastore-migration-benchmark/index.mdx","title":"SharedPreferences\uc5d0\uc11c DataStore\ub85c \uc62e\uae30\uace0 \uc22b\uc790\ub85c \uc99d\uba85\ud558\uae30 \u2014 \ub300\uaddc\ubaa8 \uc571\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc2e4\uce21 \uc0ac\ub840","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-11T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"datastore","permalink":"/blog/posts/tags/datastore"},{"inline":true,"label":"performance","permalink":"/blog/posts/tags/performance"},{"inline":true,"label":"benchmark","permalink":"/blog/posts/tags/benchmark"}],"readingTime":3.17,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"datastore-migration-benchmark","title":"SharedPreferences\uc5d0\uc11c DataStore\ub85c \uc62e\uae30\uace0 \uc22b\uc790\ub85c \uc99d\uba85\ud558\uae30 \u2014 \ub300\uaddc\ubaa8 \uc571\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc2e4\uce21 \uc0ac\ub840","authors":["way"],"tags":["android","datastore","performance","benchmark"]},"unlisted":false,"prevItem":{"title":"Play \ud0c0\uae43 API 36 \uc81c\ucd9c \ucc28\ub2e8\uc774 \ud604\uc2e4\ud654\ub410\ub2e4 \u2014 11\uc6d4 1\uc77c \uc5f0\uc7a5 \uc2e0\uccad\uacfc \ub300\uc751 \uccb4\ud06c\ub9ac\uc2a4\ud2b8","permalink":"/blog/posts/play-target-api-36-deadline"},"nextItem":{"title":"Kotlin 2.4.21 \ubc84\uadf8\ud53d\uc2a4 \ub9b4\ub9ac\uc2a4 \u2014 2.4.x \ub77c\uc778 \uc720\uc9c0\ud300\uc740 \uc548\uc804\ud558\uac8c \uc62c\ub9b4 \uc2dc\uc810","permalink":"/blog/posts/kotlin-2-4-21"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\nSharedPreferences\ub97c DataStore\ub85c \uc62e\uae30\uace0 \uc2f6\uc740\ub370 \\"\uc131\ub2a5\uc774 \ub098\ube60\uc9c0\uc9c4 \uc54a\uc744\uae4c\\" \ub9dd\uc124\uc600\ub358 \ud300\uc774\ub77c\uba74, \uc774\ubc88 ProAndroidDev \ucee4\ubba4\ub2c8\ud2f0 \uae00\uc774 \uc88b\uc740 \ucc38\uace0 \uc790\ub8cc\uc785\ub2c8\ub2e4. \ub300\uaddc\ubaa8 \uc571\uc758 \uc2a4\ud1a0\ub9ac\uc9c0 \uae30\ubc18\uc744 \ud1b5\uc9f8\ub85c \uac08\uc544\uc5ce\uace0, \uc601\ud5a5\uc744 \uc22b\uc790\ub85c \uc99d\uba85\ud55c \uc0ac\ub840\uac70\ub4e0\uc694.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- \ud55c \ub300\uaddc\ubaa8 \uc571 \ud300\uc774 \ud575\uc2ec \ub85c\uceec \ub370\uc774\ud130\ub97c SharedPreferences\uc5d0\uc11c Jetpack DataStore\ub85c \uc774\uc804\ud588\uc2b5\ub2c8\ub2e4.\\n- \ub2e4\ub978 \ubcc0\uacbd\uc758 \uc601\ud5a5\uc774 \uc11e\uc774\uc9c0 \uc54a\ub3c4\ub85d \ube4c\ub4dc\ub97c 3\uac1c\ub85c \ub098\ub220 \uce21\uc815\ud55c \uacb0\uacfc, **DataStore \uc790\uccb4\uc758 \ub7f0\ud0c0\uc784 \ube44\uc6a9\uc740 \uce21\uc815 \uc624\ucc28 \ubc94\uc704 \uc548\uc774\uc5c8\uc2b5\ub2c8\ub2e4**. \ucf5c\ub4dc \uc2a4\ud0c0\ud2b8, CPU, \uba54\ubaa8\ub9ac \ubaa8\ub450 \ub9c8\ucc2c\uac00\uc9c0\uc785\ub2c8\ub2e4.\\n- \uae30\uc874 \uc0ac\uc6a9\uc790 \ub370\uc774\ud130 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc740 \ubc31\uadf8\ub77c\uc6b4\ub4dc \uc2a4\ub808\ub4dc\uc5d0\uc11c 1\ud68c \uc2e4\ud589\ub418\uba70 \uc218\uc2ed ms\uc5d0 \ub05d\ub0a9\ub2c8\ub2e4. \uc800\uc0ac\uc591 \uae30\uae30 \uc5c5\ub370\uc774\ud2b8 \uc2dc\ub098\ub9ac\uc624\uc5d0\uc11c\ub3c4 \uccab \uc2e4\ud589\uc774 \ub290\ub824\uc9c0\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### \uc65c SharedPreferences\ub97c \ub5a0\ub0ac\ub098\\n\\n\uae00\uc4f4\uc774\uac00 \uaf3d\uc740 SharedPreferences\uc758 \ud55c\uacc4\ub294 \ub2e4\uc12f \uac00\uc9c0\uc785\ub2c8\ub2e4.\\n\\n1. \uccab \uc77d\uae30\uac00 \ub3d9\uae30\uc2dd\uc774\ub77c \uba54\uc778 \uc2a4\ub808\ub4dc\uc5d0\uc11c \ud638\ucd9c\ud558\uba74 \ud654\uba74\uc774 \uac19\uc774 \uae30\ub2e4\ub9bd\ub2c8\ub2e4.\\n2. `apply()`\ub294 \ube44\ub3d9\uae30\ucc98\ub7fc \ubcf4\uc774\uc9c0\ub9cc Activity \uc885\ub8cc \uc2dc\uc810\uc5d0 \ubc00\ub9b0 \uc4f0\uae30\ub97c \ubaa8\ub450 \uae30\ub2e4\ub9bd\ub2c8\ub2e4. \uc800\uc7a5\uc18c\uac00 \ub290\ub9b0 \uae30\uae30\uc5d0\uc11c\ub294 ANR\ub85c \uc774\uc5b4\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n3. \uc4f0\uae30 \uc2e4\ud328\uac00 \uc870\uc6a9\ud788 \ubb3b\ud799\ub2c8\ub2e4. `apply()`\ub294 \uc131\uacf5 \uc5ec\ubd80\ub97c \uc54c\ub824\uc8fc\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n4. \ubcc0\uacbd\uc744 \uad00\ucc30\ud558\uae30 \uc5b4\ub835\uc2b5\ub2c8\ub2e4. \ub9ac\uc2a4\ub108 \ubc29\uc2dd\uc740 \ub204\uc218 \ub098\uae30 \uc27d\uace0 \ucf54\ub8e8\ud2f4/Flow\uc640\ub3c4 \uc5b4\uc6b8\ub9ac\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n5. \ud0c0\uc785\uc774 \uac15\uc81c\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. `Int`\ub85c \uc800\uc7a5\ud55c \uac78 `Long`\uc73c\ub85c \uc77d\uc73c\uba74 \ub7f0\ud0c0\uc784\uc5d0 `ClassCastException`\uc73c\ub85c \ud130\uc9d1\ub2c8\ub2e4.\\n\\nDataStore\ub294 \uc815\ud655\ud788 \uc774 \uc9c0\uc810\ub4e4\uc744 \uaca8\ub0e5\ud55c \uc124\uacc4\uc774\ub2c8, \\"\uc65c \uc62e\uae30\ub0d0\\"\uc5d0 \ub300\ud55c \ub2f5\uc740 \ube44\uad50\uc801 \uba85\ud655\ud569\ub2c8\ub2e4.\\n\\n#### \uce21\uc815 \ubc29\ubc95\uc774 \uc778\uc0c1\uc801\uc778 \ubd80\ubd84\\n\\n\uc81c\uc77c \ubc30\uc6b8 \uc810\uc740 \uce21\uc815 \uc124\uacc4\uc785\ub2c8\ub2e4. \uc774\ubc88 \ub9b4\ub9ac\uc2a4\uc5d0\ub294 DataStore \ub9d0\uace0\ub3c4 \ub2e4\ub978 \ubcc0\uacbd\uc774 \ub9ce\uc558\uae30 \ub54c\ubb38\uc5d0, \ud300\uc740 **\ube4c\ub4dc\ub97c 3\uac1c\ub85c \ub098\ub220\uc11c** \uc7c0\uc2b5\ub2c8\ub2e4.\\n\\n- \uc774\uc804 \ub9b4\ub9ac\uc2a4\\n- \uc774\ubc88 \ub9b4\ub9ac\uc2a4\uc5d0\uc11c DataStore\ub9cc \ube80 \ube4c\ub4dc\\n- \uc2e4\uc81c\ub85c \ubc30\ud3ec\ud55c \uc774\ubc88 \ub9b4\ub9ac\uc2a4\\n\\n\ub450 \ubc88\uc9f8\uc640 \uc138 \ubc88\uc9f8\uc758 \ucc28\uc774\uac00 \uace7 DataStore\uc758 \uc21c\uc218 \ube44\uc6a9\uc785\ub2c8\ub2e4. Xiaomi Redmi Note 9 Pro(Snapdragon 720G, 6GB RAM)\uc5d0\uc11c 24\ubd84\uc9dc\ub9ac \ub2e8\uc77c \uc138\uc158\uc5d0 \ubab0\uc544\ub123\uc5b4 \ube4c\ub4dc\ub2f9 10\ud68c \ucf5c\ub4dc \uc2a4\ud0c0\ud2b8\ub97c \uc5f0\ub2ec\uc544 \uc7c0\uc2b5\ub2c8\ub2e4. \uacb0\uacfc\ub294 \ubaa8\ub4e0 \ucc28\uc774\uac00 \uac19\uc740 \ube4c\ub4dc \ub0b4 \ubcc0\ub3d9 \ud3ed \uc548\uc5d0 \ub4e4\uc5c8\uc2b5\ub2c8\ub2e4. \uc624\ud788\ub824 CPU\ub9cc\uc740 B \ud654\uba74 \uc544\uc774\ub4e4 \uc0c1\ud0dc\uc5d0\uc11c 2.6\ud3ec\uc778\ud2b8 \uc77c\uad00\ub418\uac8c \ub0b4\ub824\uac14\uace0, \uc774\uac74 \ub450 \ubc88\uc758 \ubcc4\ub3c4 \uce21\uc815 \uc138\uc158\uc5d0\uc11c \ubaa8\ub450 \uc7ac\ud604\ub410\uc2b5\ub2c8\ub2e4.\\n\\n#### \uc800\uc0ac\uc591 \uae30\uae30 \uc5c5\ub370\uc774\ud2b8 \uc2dc\ub098\ub9ac\uc624\\n\\n\ub9c8\uc774\uadf8\ub808\uc774\uc158\uc774 \uc2e4\uc81c\ub85c \ub3c4\ub294 \uac74 \uae30\uc874 \uc0ac\uc6a9\uc790\uac00 \uc5c5\ub370\uc774\ud2b8\ud560 \ub54c\ub77c\uc11c, Galaxy A15\uc5d0\uc11c \uad6c\ubc84\uc804 \ub370\uc774\ud130\ub97c \uae54\uc544\ub454 \uc0c1\ud0dc\ub85c 10\ud68c\uc529 \uc7c0\uc2b5\ub2c8\ub2e4(Perfetto). 10\ud68c \ucf5c\ub4dc \uc2a4\ud0c0\ud2b8\uc640 10\ud68c \uc6dc \uc2a4\ud0c0\ud2b8 \ubaa8\ub450 \uc0c8 APK\uac00 \ube68\ub790\uace0, \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc774 \ub3c4\ub294 \uccab \uc2e4\ud589(7.04\ucd08)\ub3c4 \ud3c9\uade0\ubcf4\ub2e4 \ub290\ub9ac\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uc989 **\ub9c8\uc774\uadf8\ub808\uc774\uc158\uc774 \uae30\uc874 \uc0ac\uc6a9\uc790\ub97c \ubd99\uc7a1\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4**.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **\\"DataStore\ub85c \uc62e\uae30\uba74 \ub290\ub824\uc9c4\ub2e4\\"\ub294 \uc120\uc785\uacac\uc744 \uae68\ub294 \uc218\uce58\uc785\ub2c8\ub2e4.** \uce21\uc815 \uc624\ucc28 \ubc94\uc704 \uc548\uc5d0 \ub4e0\ub2e4\ub294 \uac74, \uc2e4\ubb34\uc801\uc73c\ub85c\ub294 \ube44\uc6a9\uc774 \uc5c6\ub2e4\ub294 \ub73b\uc785\ub2c8\ub2e4.\\n- **\ud558\uc9c0\ub9cc \uc774 \ud300\uc758 \uacb0\ub860\uc740 \\"DataStore\uac00 \uc571\uc744 \ube60\ub974\uac8c \ud588\ub2e4\\"\uac00 \uc544\ub2d9\ub2c8\ub2e4.** \uac19\uc740 \ub9b4\ub9ac\uc2a4\uc5d0\uc11c Galaxy A55 \uae30\uc900 \uccab \ud654\uba74\uc774 0.7\ucd08 \ube68\ub77c\uc9c4 \uac74 \ud300 \uc804\uccb4\uc758 \uc791\uc5c5 \ub355\ubd84\uc774\uace0, DataStore\ub294 \uadf8 \ubc1c\ubaa9\uc744 \uc7a1\uc9c0 \uc54a\uc558\uc744 \ubfd0\uc785\ub2c8\ub2e4. \uc22b\uc790\ub97c \uc77d\uc744 \ub54c \uadc0\uc18d \uad00\uacc4\ub97c \ud5f7\uac08\ub9ac\uba74 \uc548 \ub429\ub2c8\ub2e4.\\n- **\ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc18c\uc694 \uc2dc\uac04\uc740 \ud154\ub808\uba54\ud2b8\ub9ac\ub85c \uc7a1\uc558\uc2b5\ub2c8\ub2e4.** \ubc31\uadf8\ub77c\uc6b4\ub4dc\uc5d0\uc11c \uc218\uc2ed ms\uc5d0 \ub05d\ub09c\ub2e4\ub294 \uc8fc\uc7a5\uc774 \\"\ub290\ub08c\\"\uc774 \uc544\ub2c8\ub77c \uce21\uc815\uac12\uc778 \uac8c \uc774 \uae00\uc758 \uc2e0\ub8b0\ub3c4\ub97c \uc62c\ub9bd\ub2c8\ub2e4.\\n- \uae00\uc4f4\uc774 \ubcf8\uc778\ub3c4 \uacbd\uace0\ud569\ub2c8\ub2e4. \ubaa8\ub4e0 \uc22b\uc790\ub294 \ubb3c\ub9ac \uae30\uae30\uc5d0\uc11c \uc9c1\uc811 \uc7b0 \ub0b4\ubd80 \uce21\uc815\uac12\uc774\ub77c, \ub0b4 \uc571\xb7\ub0b4 \uae30\uae30\uc5d0\uc11c\ub294 \uac12\uc774 \ub2e4\ub97c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \uc801\uc6a9\ud560 \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\nDataStore Preferences\ub85c \uc62e\uae38 \ub54c \uae30\uc874 SharedPreferences \ub370\uc774\ud130\ub97c \uc0b4\ub9ac\ub294 \ud45c\uc900 \ud328\ud134\uc740 \uc774\ub807\uc2b5\ub2c8\ub2e4.\\n\\n```kotlin\\n// \uae30\uc874 prefs \ub370\uc774\ud130\ub97c \uc783\uc9c0 \uc54a\uace0 DataStore\ub85c 1\ud68c \ub9c8\uc774\uadf8\ub808\uc774\uc158\\nval Context.dataStore by preferencesDataStore(\\n    name = \\"settings\\",\\n    produceMigrations = { context ->\\n        listOf(SharedPreferencesMigration(context, \\"old_prefs\\"))\\n    }\\n)\\n\\n// \uc77d\uae30: \ucf54\ub8e8\ud2f4/Flow\uc5d0 \uc790\uc5f0\uc2a4\ub7fd\uac8c \uc5f0\uacb0\\nval darkMode = context.dataStore.data\\n    .map { prefs -> prefs[DARK_MODE_KEY] ?: false }\\n```\\n\\n\uae00\uc5d0\uc11c \uc5bb\uc740 \uad50\ud6c8\uc744 \uc6b0\ub9ac \ud300\uc5d0 \uc801\uc6a9\ud55c\ub2e4\uba74 \ub450 \uac00\uc9c0\ub97c \uac00\uc838\uac00\uace0 \uc2f6\uc2b5\ub2c8\ub2e4. \uccab\uc9f8, \uc131\ub2a5\uc744 \uc6b0\ub824\ud558\ub294 \ub300\uaddc\ubaa8 \ubcc0\uacbd\uc740 \\"\ubcc0\uacbd\ub9cc \ube80 \ube44\uad50 \ube4c\ub4dc\\"\ub97c \ud558\ub098 \ub354 \ub9cc\ub4e4\uc5b4 \uce21\uc815\ud558\uae30. \ub458\uc9f8, \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc18c\uc694 \uc2dc\uac04\uc744 \ud154\ub808\uba54\ud2b8\ub9ac \uc774\ubca4\ud2b8\ub85c \ub0a8\uaca8\uc11c \uc6b4\uc601 \uc911\uc5d0\ub3c4 \uc2e4\uc81c \uc22b\uc790\ub97c \ubcfc \uc218 \uc788\uac8c \ud558\uae30. \uc774 \ub450 \uac00\uc9c0\ub9cc \ud574\ub3c4 \\"\ub290\ub824\uc9c4 \uac70 \uc544\ub2c8\uc57c?\\"\ub77c\ub294 \uc9c8\ubb38\uc5d0 \uac10\uc774 \uc544\ub2c8\ub77c \uc22b\uc790\ub85c \ub2f5\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc2a4\ud1a0\ub9ac\uc9c0 \ub9c8\uc774\uadf8\ub808\uc774\uc158\uc740 \uc0ac\uc6a9\uc790\uc5d0\uac8c \ubcf4\uc774\uc9c0 \uc54a\ub294 \uac8c \uc131\uacf5\uc785\ub2c8\ub2e4. \uc720\uc2e4\ub3c4 \uc5c6\uace0, \uc911\uac04\uc5d0 \ub04a\uae34 \uc138\uc158\ub3c4 \uc5c6\uace0, \ub290\ub824\uc9c4 \uc571\ub3c4 \uc5c6\ub294 \uac83 \u2014 \uadf8\uac78 \uc22b\uc790\ub85c \uc99d\uba85\ud55c \uc0ac\ub840\uac00 \ub098\uc654\ub2e4\ub294 \uc810\uc5d0\uc11c, \uc544\uc9c1 SharedPreferences\uc5d0 \uba38\ubb3c\ub7ec \uc788\ub294 \ud300\uc5d0\uac8c \ud55c \ubc88\ucbe4 \uc77d\uc5b4\ubcfc \ub9cc\ud55c \uae00\uc785\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [Moving Local Storage to Jetpack DataStore Without Paying a Cent in Performance \u2014 ProAndroidDev (Taufik Amaryansyah)](https://proandroiddev.com/moving-local-storage-to-jetpack-datastore-without-paying-a-cent-in-performance-e709b28719de)"},{"id":"kotlin-2-4-21","metadata":{"permalink":"/blog/posts/kotlin-2-4-21","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-11-kotlin-2-4-21/index.mdx","source":"@site/blog/2026-10-11-kotlin-2-4-21/index.mdx","title":"Kotlin 2.4.21 \ubc84\uadf8\ud53d\uc2a4 \ub9b4\ub9ac\uc2a4 \u2014 2.4.x \ub77c\uc778 \uc720\uc9c0\ud300\uc740 \uc548\uc804\ud558\uac8c \uc62c\ub9b4 \uc2dc\uc810","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-11T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"kotlin","permalink":"/blog/posts/tags/kotlin"},{"inline":true,"label":"kmp","permalink":"/blog/posts/tags/kmp"},{"inline":true,"label":"release","permalink":"/blog/posts/tags/release"}],"readingTime":2.51,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kotlin-2-4-21","title":"Kotlin 2.4.21 \ubc84\uadf8\ud53d\uc2a4 \ub9b4\ub9ac\uc2a4 \u2014 2.4.x \ub77c\uc778 \uc720\uc9c0\ud300\uc740 \uc548\uc804\ud558\uac8c \uc62c\ub9b4 \uc2dc\uc810","authors":["way"],"tags":["android","kotlin","kmp","release"]},"unlisted":false,"prevItem":{"title":"SharedPreferences\uc5d0\uc11c DataStore\ub85c \uc62e\uae30\uace0 \uc22b\uc790\ub85c \uc99d\uba85\ud558\uae30 \u2014 \ub300\uaddc\ubaa8 \uc571\uc758 \ub9c8\uc774\uadf8\ub808\uc774\uc158 \uc2e4\uce21 \uc0ac\ub840","permalink":"/blog/posts/datastore-migration-benchmark"},"nextItem":{"title":"KMP \ud50c\ub7ec\uadf8\uc778\uc758 Swift IDE \uc9c0\uc6d0 \uc885\ub8cc \u2014 2026.3\ubd80\ud130 Swift \uc791\uc5c5\uc740 Xcode\ub85c \ub098\ub220\uc57c \ud55c\ub2e4","permalink":"/blog/posts/kmp-swift-ide-discontinued"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 8\uc77c, JetBrains\uac00 Kotlin 2.4.21\uc744 \ub9b4\ub9ac\uc2a4\ud588\uc2b5\ub2c8\ub2e4. \uae30\ub2a5 \ucd94\uac00 \uc5c6\ub294 \ubc84\uadf8\ud53d\uc2a4 \ub9b4\ub9ac\uc2a4\ub77c\uc11c 2.4.x \ub77c\uc778\uc744 \uc4f0\uace0 \uc788\ub294 \ud300\uc774\ub77c\uba74 \ud2b9\ubcc4\ud55c \uace0\ubbfc \uc5c6\uc774 \uc62c\ub9b4 \uc218 \uc788\ub294 \ubc84\uc804\uc785\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- K/Wasm\uc5d0\uc11c \uc798\ubabb\ub41c \ud0c0\uc785\uc758 \uc778\uc790\ub85c \ub78c\ub2e4\ub97c \ud638\ucd9c\ud558\uba74 \ud2b8\ub7a9\uc774 \ub098\ub358 \ubb38\uc81c\uac00 \uace0\uccd0\uc84c\uc2b5\ub2c8\ub2e4. \uc774\uc81c \uc815\uc0c1\uc801\uc73c\ub85c `ClassCastException`\uc774 \ub358\uc838\uc9d1\ub2c8\ub2e4.\\n- Kotlin/JS \ud504\ub85c\ub355\uc158 \ube4c\ub4dc\uc5d0\uc11c \uba64\ubc84 \uc774\ub984\uc774 minify\ub418\uc9c0 \uc54a\ub3c4\ub85d \ub418\ub3cc\ub824\uc84c\uc2b5\ub2c8\ub2e4.\\n- JVM \ub9ac\ud50c\ub809\uc158\uc758 `KCallable` \ud45c\ud604 \ubc29\uc2dd\uc774 K1 \ucef4\ud30c\uc77c\ub7ec \uc758\uc874\uc131\uc744 \uc81c\uac70\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \ubc14\ub00c\uc5c8\uc2b5\ub2c8\ub2e4.\\n- Kotlin Script\uc640 JSR-223(\uc2a4\ud06c\ub9bd\ud2b8 2\ud68c \uc2e4\ud589 \uc2dc `NoClassDefFoundError`, \ubc14\uc778\ub529 \uae68\uc9d0 \ub4f1) \uad00\ub828 \uc218\uc815\uc774 \uc5ec\ub7ec \uac74 \ud3ec\ud568\ub410\uc2b5\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### K/Wasm: \uc870\uc6a9\ud55c \ud2b8\ub7a9 \ub300\uc2e0 \uc608\uc678\uac00 \ub358\uc838\uc9c4\ub2e4\\n\\n`(T) -> R` \ud615\ud0dc\uc758 \ub78c\ub2e4\uc5d0 `T`\uac00 \uc544\ub2cc \uc778\uc790\ub97c \ub123\uc5c8\uc744 \ub54c, \uc774\uc804\uc5d0\ub294 Wasm \ud2b8\ub7a9\uc774 \ubc1c\uc0dd\ud574 \\"\ubb58 \uc798\ubabb\ud55c \uac74\uc9c0\\" \uc54c\uae30 \uc5b4\ub824\uc6e0\uc2b5\ub2c8\ub2e4. \uc774\ubc88 \uc218\uc815\uc73c\ub85c `ClassCastException`\uc774 \uc815\uc0c1\uc801\uc73c\ub85c \ub358\uc838\uc9d1\ub2c8\ub2e4. K/Wasm \ud0c0\uae43\uc744 \ub9cc\uc9c0\ub294 KMP \ud504\ub85c\uc81d\ud2b8\ub77c\uba74, \uae30\uc874\uc5d0 \ud2b8\ub7a9\uc73c\ub85c \uc8fd\ub358 \uacbd\ub85c\uac00 \uc774\uc81c catch \uac00\ub2a5\ud55c \uc608\uc678\ub85c \ubc14\ub00c\ub294 \uac83\uc774\ub2c8 \uc608\uc678 \ucc98\ub9ac \ub85c\uc9c1\uc744 \ud55c \ubc88 \ud655\uc778\ud574 \ubcfc \ub9cc\ud569\ub2c8\ub2e4.\\n\\n#### Kotlin/JS: \ud504\ub85c\ub355\uc158 \ube4c\ub4dc\uc5d0\uc11c \uba64\ubc84 \uc774\ub984 \uc720\uc9c0\\n\\nK/JS \ud504\ub85c\ub355\uc158 \ube4c\ub4dc\uc5d0\uc11c \uba64\ubc84 \uc774\ub984\uc774 minify\ub418\ub358 \ubcc0\uacbd\uc774 \ub418\ub3cc\ub824\uc84c\uc2b5\ub2c8\ub2e4. \ub514\ubc84\uae45\uc774\ub098 \ub7f0\ud0c0\uc784 \uc774\ub984 \uae30\ubc18 \ucc98\ub9ac\uc5d0 \uc601\ud5a5\uc744 \ubc1b\uc744 \uc218 \uc788\ub294 \ud504\ub85c\uc81d\ud2b8\ub294 \uc548\uc2ec\ud558\uace0 \uc62c\ub9b4 \uc218 \uc788\ub294 \ubc29\ud5a5\uc785\ub2c8\ub2e4.\\n\\n#### \ub9ac\ud50c\ub809\uc158\uc5d0\uc11c K1 \uc758\uc874\uc131 \uc81c\uac70\\n\\n`KCallable`\uc758 \ub0b4\ubd80 \ud45c\ud604\uc774 K1 \ucef4\ud30c\uc77c\ub7ec\uc5d0 \uc758\uc874\ud558\uc9c0 \uc54a\ub3c4\ub85d \uc815\ub9ac\ub410\uc2b5\ub2c8\ub2e4. \uac89\uc73c\ub85c\ub294 \ub4dc\ub7ec\ub098\uc9c0 \uc54a\uc9c0\ub9cc, K2 \ucef4\ud30c\uc77c\ub7ec\ub85c \uc644\uc804\ud788 \ub118\uc5b4\uac00\ub294 \uacfc\uc815\uc5d0\uc11c \ub0a8\uc740 \uad6c\ud615 \uc758\uc874\uc131\uc744 \ud558\ub098\uc529 \uac77\uc5b4\ub0b4\ub294 \uc791\uc5c5\uc785\ub2c8\ub2e4. \ub9ac\ud50c\ub809\uc158\uc744 \uc4f0\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 \ub0b4\ubd80 \uad6c\ud604\uc744 \ubcf4\ub294 \ud3b8\uc774\ub77c\uba74 \\"\uc65c \uc774\ub7f0 \uc2dd\uc73c\ub85c \ubc14\ub00c\uc5c8\ub294\uc9c0\\"\uc758 \ub9e5\ub77d \uc815\ub3c4\ub85c \uc774\ud574\ud558\uba74 \ub429\ub2c8\ub2e4.\\n\\n#### \uc2a4\ud06c\ub9bd\ud2b8 \uad00\ub828 \uc218\uc815\ub4e4\\n\\nKotlin Script\uc5d0\uc11c \uc804\ub2ec \uc758\uc874\uc131\uc774 \uc788\ub294 \uc2a4\ud06c\ub9bd\ud2b8\ub97c \ub450 \ubc88\uc9f8 \uc2e4\ud589\ud558\uba74 `NoClassDefFoundError`\uac00 \ub098\ub358 \ubb38\uc81c, JSR-223\uc5d0\uc11c \uc81c\ub124\ub9ad Java \ubc14\uc778\ub529\uc774 \uc774\ud6c4\uc758 \ubaa8\ub4e0 `eval()` \ud638\ucd9c\uc744 \uae68\ub728\ub9ac\ub358 \ubb38\uc81c\uac00 \uc218\uc815\ub410\uc2b5\ub2c8\ub2e4. \uc2a4\ud06c\ub9bd\ud2b8 \uc5d4\uc9c4\uc744 \ub0b4\uc7a5\ud55c \uc571\uc774\ub77c\uba74 \uc758\ubbf8 \uc788\ub294 \uc218\uc815\uc785\ub2c8\ub2e4.\\n\\n#### \uadf8 \ubc16\uc758 \uc218\uc815\\n\\n- `@Serializable` \uc81c\ub124\ub9ad \ud074\ub798\uc2a4\uc5d0 \ud074\ub798\uc2a4 \uc0c1\ud55c(class upper bound)\uc774 \uc788\uc744 \ub54c \uc798\ubabb\ub41c Wasm\uc774 \ub098\uc624\ub358 \ubb38\uc81c\\n- K/N Gradle\uc5d0\uc11c SwiftPM import \uc2dc \ub85c\uadf8\uac00 \ub118\uccd0\ub098\ub358 \ubb38\uc81c\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **2.4.x \ub77c\uc778 \uc720\uc9c0 \uc911\uc774\ub77c\uba74 \uc774\ubc88\uc5d4 \uc62c\ub9ac\uba74 \ub429\ub2c8\ub2e4.** \uc0c8 \uae30\ub2a5\uc774 \uc544\ub2c8\ub77c \ubc84\uadf8\ud53d\uc2a4 \ubb36\uc74c\uc774\ub77c \ub3d9\uc791 \ubcc0\uacbd \ub9ac\uc2a4\ud06c\uac00 \ub0ae\uc2b5\ub2c8\ub2e4.\\n- **K/Wasm\uc744 \uc4f0\ub294 KMP \ud504\ub85c\uc81d\ud2b8\ub294 \uc608\uc678 \uacbd\ub85c\ub97c \uc810\uac80\ud558\uc138\uc694.** \ud2b8\ub7a9\uc774 \uc608\uc678\ub85c \ubc14\ub00c\ub294 \uac74 \uc5d0\ub7ec \ucc98\ub9ac \uc804\ub7b5\uc5d0 \uc9c1\uc811 \uc601\ud5a5\uc744 \uc90d\ub2c8\ub2e4.\\n- **Kotlin/JS\ub294 minify \ubcf5\uc6d0\uc774\ub77c \ud070 \uc8fc\uc758\uc810\uc740 \uc5c6\uc2b5\ub2c8\ub2e4.** \uc624\ud788\ub824 \uc774\uc804 \ubc84\uc804\uc5d0\uc11c \uc774\uc0c1 \uc9d5\ud6c4\uac00 \uc788\uc5c8\ub2e4\uba74 \ud574\uc18c \ubc29\ud5a5\uc785\ub2c8\ub2e4.\\n- **\uc2a4\ud06c\ub9bd\ud2b8 \uc5d4\uc9c4 \ub0b4\uc7a5 \uc571(\uc11c\ubc84 \uce21 \ud639\uc740 \ub0b4\ubd80 \ub3c4\uad6c)\uc740 \uc774\ubc88 \ub9b4\ub9ac\uc2a4\uac00 \uc81c\ubc95 \uc54c\ucc39\ub2c8\ub2e4.** \uc2a4\ud06c\ub9bd\ud2b8 \uc2e4\ud589 \uad00\ub828 \uc218\uc815\uc774 4\uac74\uc774\ub098 \ub4e4\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \uc62c\ub9b4 \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\ubc84\uc804 \uce74\ud0c8\ub85c\uadf8 \uae30\uc900\uc73c\ub85c \ubc84\uc804\ub9cc \ubc14\uafb8\ub294 \uac8c \uc804\ubd80\uc785\ub2c8\ub2e4. \ub2e4\ub9cc \uc62c\ub9ac\uace0 \ub098\uba74 \ucef4\ud30c\uc77c\ub7ec\uac00 \ubc14\ub00c\ub294 \ub9cc\ud07c, \uc804\uccb4 \ube4c\ub4dc \ud55c \ubc88\uacfc \uc8fc\uc694 \ud654\uba74 \uc2a4\ubaa8\ud06c \ud14c\uc2a4\ud2b8 \uc815\ub3c4\ub294 \ub3cc\ub9bd\ub2c8\ub2e4.\\n\\n```kotlin\\n// gradle/libs.versions.toml\\n[versions]\\nkotlin = \\"2.4.21\\" // 2.4.20 -> 2.4.21 (\ubc84\uadf8\ud53d\uc2a4, \ub3d9\uc791 \ubcc0\uacbd \uc5c6\uc74c \uc608\uc0c1)\\n```\\n\\nKMP \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c Wasm \ud0c0\uae43\uc744 \uc4f0\ub294 \uacbd\uc6b0, \ub9b4\ub9ac\uc2a4 \ub178\ud2b8\uc758 \ud574\ub2f9 \ud56d\ubaa9\uc774 \ub0b4 \ucf54\ub4dc \uacbd\ub85c\uc5d0 \ub2ff\ub294\uc9c0 \ube60\ub974\uac8c \ud655\uc778\ud558\ub294 \uc2a4\ud06c\ub9bd\ud2b8\ub97c CI\uc5d0 \uac78\uc5b4 \ub450\uba74 \uc774\ud6c4 \ub9b4\ub9ac\uc2a4\uc5d0\uc11c\ub3c4 \ubd80\ub2f4\uc774 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\n\uba54\uc774\uc800 \ub9b4\ub9ac\uc2a4\uac00 \uc544\ub2c8\ub77c\uc11c \ud654\ub824\ud558\uc9c4 \uc54a\uc9c0\ub9cc, \uc774\ub7f0 \ubc84\uadf8\ud53d\uc2a4 \ub9b4\ub9ac\uc2a4\uc57c\ub9d0\ub85c \\"\uadf8\ub0e5 \uc62c\ub9ac\uba74 \uc88b\uc740\\" \ub9b4\ub9ac\uc2a4\uc785\ub2c8\ub2e4. 2.4.x \ub77c\uc778\uc5d0\uc11c \uc6b4\uc601 \uc911\uc778 \ud504\ub85c\uc81d\ud2b8\uac00 \uc788\ub2e4\uba74, \uc774\ubc88 \uc8fc\uc5d0 \ubc84\uc804\ub9cc \uc62c\ub9ac\uace0 \uc2a4\ubaa8\ud06c \ud14c\uc2a4\ud2b8 \ud55c \ubc88 \ub3cc\ub824 \ubcf4\uae38 \uad8c\ud569\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [Release Kotlin 2.4.21 \u2014 JetBrains/kotlin GitHub Releases](https://github.com/JetBrains/kotlin/releases/tag/v2.4.21)"},{"id":"kmp-swift-ide-discontinued","metadata":{"permalink":"/blog/posts/kmp-swift-ide-discontinued","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-10-kmp-swift-ide-discontinued/index.mdx","source":"@site/blog/2026-10-10-kmp-swift-ide-discontinued/index.mdx","title":"KMP \ud50c\ub7ec\uadf8\uc778\uc758 Swift IDE \uc9c0\uc6d0 \uc885\ub8cc \u2014 2026.3\ubd80\ud130 Swift \uc791\uc5c5\uc740 Xcode\ub85c \ub098\ub220\uc57c \ud55c\ub2e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-10T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"kotlin","permalink":"/blog/posts/tags/kotlin"},{"inline":true,"label":"kmp","permalink":"/blog/posts/tags/kmp"},{"inline":true,"label":"kotlin-multiplatform","permalink":"/blog/posts/tags/kotlin-multiplatform"},{"inline":true,"label":"tooling","permalink":"/blog/posts/tags/tooling"}],"readingTime":3.08,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kmp-swift-ide-discontinued","title":"KMP \ud50c\ub7ec\uadf8\uc778\uc758 Swift IDE \uc9c0\uc6d0 \uc885\ub8cc \u2014 2026.3\ubd80\ud130 Swift \uc791\uc5c5\uc740 Xcode\ub85c \ub098\ub220\uc57c \ud55c\ub2e4","authors":["way"],"tags":["android","kotlin","kmp","kotlin-multiplatform","tooling"]},"unlisted":false,"prevItem":{"title":"Kotlin 2.4.21 \ubc84\uadf8\ud53d\uc2a4 \ub9b4\ub9ac\uc2a4 \u2014 2.4.x \ub77c\uc778 \uc720\uc9c0\ud300\uc740 \uc548\uc804\ud558\uac8c \uc62c\ub9b4 \uc2dc\uc810","permalink":"/blog/posts/kotlin-2-4-21"},"nextItem":{"title":"ML Drift \uc624\ud508\uc18c\uc2a4 \uacf5\uac1c \u2014 LiteRT GPU \uac00\uc18d\uc758 \uc0c8 \uc5d4\uc9c4, TFLite GPU delegate\uc758 \ub4a4\ub97c \uc787\ub2e4","permalink":"/blog/posts/ml-drift-litert-gpu"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 5\uc77c, JetBrains\uac00 Kotlin Multiplatform(KMP) \ud50c\ub7ec\uadf8\uc778\uc5d0\uc11c \uc81c\uacf5\ud558\ub358 Swift \uc5b8\uc5b4 IDE \uae30\ub2a5\uc744 \uc55e\uc73c\ub85c \uc911\ub2e8\ud55c\ub2e4\uace0 \uc54c\ub838\uc2b5\ub2c8\ub2e4. \uc801\uc6a9 \uc2dc\uc810\uc740 IntelliJ IDEA 2026.3\uacfc Android Studio Rabbit 2 | 2026.2.2\ubd80\ud130\uc785\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- \uc5c6\uc5b4\uc9c0\ub294 \uac83\uc740 Swift \ud30c\uc77c\uc744 \uac19\uc740 IDE \uc548\uc5d0\uc11c \ud3b8\uc9d1\ud558\uace0, \ubb38\ubc95 \uac15\uc870\ub97c \ubc1b\uace0, Swift\uc640 Kotlin \uc0ac\uc774\ub97c \uc624\uac00\uba70 \uc774\ub3d9\ud558\ub358 \uae30\ub2a5\uc785\ub2c8\ub2e4.\\n- iOS \uc571\uc744 \uc2e4\ud589\ud558\ub294 \uc77c\uacfc iOS\uc5d0\uc11c Kotlin \ucf54\ub4dc\ub97c \ub514\ubc84\uae45\ud558\ub294 \uc77c\uc740 \uacc4\uc18d \uc9c0\uc6d0\ub429\ub2c8\ub2e4.\\n- Kotlin/Native \ucabd \uae30\ub2a5\ub3c4 \uadf8\ub300\ub85c\uc785\ub2c8\ub2e4. Swift\ub85c \ub0b4\ubcf4\ub0b4\ub294 Swift Export\ub098, Swift \ud328\ud0a4\uc9c0\ub97c Kotlin \ud504\ub85c\uc81d\ud2b8\ub85c \uac00\uc838\uc624\ub294 \ud750\ub984\uc740 \uc774\ubc88 \uacb0\uc815\uacfc \ubcc4\uac1c\uc785\ub2c8\ub2e4.\\n- \uc608\uc804 \ubc84\uc804\uc758 IDE\uc640 \ud50c\ub7ec\uadf8\uc778\uc5d0\uc11c\ub294 \uae30\uc874 Swift \uae30\ub2a5\uc744 \uacc4\uc18d \uc4f8 \uc218 \uc788\uc9c0\ub9cc, \uac70\uae30\uc5d0 \uc0c8 \uc5c5\ub370\uc774\ud2b8\uac00 \ubd99\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n\uc27d\uac8c \ub9d0\ud558\uba74, \ub3c4\uad6c\uac00 \ud558\ub098\ub85c \ud569\uccd0\uc9c0\ub358 \ubc29\ud5a5\uc5d0\uc11c \ub2e4\uc2dc \uac01\uc790 \uc798\ud558\ub294 \ucabd\uc73c\ub85c \uc5ed\ud560\uc744 \ub098\ub204\ub294 \uc120\ud0dd\uc785\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n\uadf8\ub3d9\uc548 KMP \ud50c\ub7ec\uadf8\uc778 \uc548\uc5d0\uc11c\ub294 Kotlin \ucf54\ub4dc\uc640 Swift \ucf54\ub4dc\ub97c \ud55c \ucc3d\uc5d0\uc11c \ubcf4\ub294 \uacbd\ud5d8\uc774 \uac00\ub2a5\ud588\uc2b5\ub2c8\ub2e4. \uc774\uc81c \uadf8 \uacbd\uacc4\uac00 \ub2e4\uc2dc IDE \ubc16\uc73c\ub85c \ub098\uac11\ub2c8\ub2e4. SwiftUI \ud654\uba74\uc774\ub098 iOS \uc804\uc6a9 \ucf54\ub4dc\ub294 Xcode\uc5d0\uc11c, \uacf5\uc720 \ub85c\uc9c1\uacfc Compose Multiplatform \ucf54\ub4dc\ub294 IntelliJ\ub098 Android Studio\uc5d0\uc11c \ubcf4\ub294 \ud750\ub984\uc774 \uae30\ubcf8\uc774 \ub429\ub2c8\ub2e4.\\n\\nJetBrains\uac00 \ubc1d\ud78c \ubc30\uacbd\uc744 \uc81c \ub9d0\ub85c \uc904\uc774\uba74 \uc774\ub807\uc2b5\ub2c8\ub2e4. \uc6d0\ub798 \uc774 Swift \uc9c0\uc6d0\uc740 \uacfc\uac70 AppCode \uc2dc\uc808\uc758 \uae30\uc220\uc744 \ubc14\ud0d5\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc84c\uace0, \uc774\ud6c4 \uc5ec\ub7ec \uc81c\ud488\uc744 \uac70\uce58\uba70 KMP \ud50c\ub7ec\uadf8\uc778\uae4c\uc9c0 \uc774\uc5b4\uc84c\uc2b5\ub2c8\ub2e4. \uadf8\ub7f0\ub370 \uc2e4\uc81c \uc0ac\uc6a9\uc740 \uafb8\uc900\ud788 \uc904\uc5c8\uace0, KMP\ub97c \uc4f0\ub294 iOS \uac1c\ubc1c\uc790 \uc0c1\ub2f9\uc218\ub294 Swift \uc791\uc5c5\ub9cc\ud07c\uc740 Xcode\ub97c \uc120\ud638\ud588\ub2e4\uace0 \ud569\ub2c8\ub2e4. \ubc18\ub300\ub85c \ud50c\ub7ec\uadf8\uc778 \uc548\uc5d0\uc11c \uc77c\ud558\ub294 \ud300\uc740 Kotlin\uacfc Compose Multiplatform \ube44\uc911\uc774 \uc810\uc810 \ucee4\uc84c\uc2b5\ub2c8\ub2e4. Swift\uc640 Xcode, IntelliJ \ud50c\ub7ab\ud3fc\uc774 \uacc4\uc18d \ubc14\ub00c\ub294 \uc0c1\ud669\uc5d0\uc11c \uc774 \uc5f0\uacb0\uc744 \uc720\uc9c0\ud558\ub294 \ube44\uc6a9\uc774 \uc2e4\uc81c \uc4f0\uc784\uc5d0 \ube44\ud574 \ucef8\ub2e4\ub294 \ud310\ub2e8\uc785\ub2c8\ub2e4.\\n\\n\ub300\uccb4 \uae30\ub2a5\uc744 \uc0c8\ub85c \ub9cc\ub4e4 \uacc4\ud68d\uc740 \ud604\uc7ac\ub85c\uc11c\ub294 \uc5c6\ub2e4\uace0\ub3c4 \ud588\uc2b5\ub2c8\ub2e4. \uc55e\uc73c\ub85c\ub294 Kotlin \ub3c4\uad6c \uc790\uccb4\uc640 iOS \uac1c\ubc1c\uc790\ub97c \uc704\ud55c KMP \uacbd\ud5d8\uc744 \ub2e4\ub4ec\ub294 \ub370 \ud798\uc744 \uc3df\uaca0\ub2e4\ub294 \ubc29\ud5a5\uc785\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\nAndroid\ub9cc \ub9cc\ub4dc\ub294 \ud300\uc774\ub77c\uba74 \uccb4\uac10 \ubcc0\ud654\ub294 \uac70\uc758 \uc5c6\uc2b5\ub2c8\ub2e4. \uc601\ud5a5\uc740 KMP\ub85c iOS\uae4c\uc9c0 \uac19\uc774 \ubcf4\ub294 \ud300\uc5d0\uc11c \uc0dd\uae41\ub2c8\ub2e4.\\n\\n- **Swift \ud30c\uc77c\uc744 Android Studio\uc5d0\uc11c \uace0\uce58\ub358 \uc2b5\uad00\uc774 \uc788\ub2e4\uba74 \uc791\uc5c5 \ub3d9\uc120\uc744 \ub098\ub220\uc57c \ud569\ub2c8\ub2e4.** \ud2b9\ud788 `iosApp` \ucabd SwiftUI \uc9c4\uc785\uc810, \uad8c\ud55c\uc774\ub098 \ub525\ub9c1\ud06c\ucc98\ub7fc iOS\uc5d0 \ubd99\uc740 \uc587\uc740 \uce35\uc744 \ub204\uac00 \uc5b4\ub290 IDE\uc5d0\uc11c \uace0\uce60\uc9c0 \ud300 \uc548\uc5d0\uc11c \uc815\ud574\ub450\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.\\n- **\uad6c\ubc84\uc804\uc5d0 \uba38\ubb34\ub294 \uc120\ud0dd\uc740 \uc784\uc2dc \ubc29\ud3b8\uc785\ub2c8\ub2e4.** Swift \uc774\ub3d9 \uae30\ub2a5\uc774 \uaf2d \ud544\uc694\ud574\uc11c IntelliJ IDEA 2026.3 \uc774\uc804\uc5d0 \uba38\ubb34\ub97c \uc218\ub294 \uc788\uc9c0\ub9cc, \uadf8 \uc0ac\uc774 Kotlin \ud50c\ub7ec\uadf8\uc778\uacfc Android Studio\uc758 \ub2e4\ub978 \uac1c\uc120\uc744 \ubabb \ubc1b\uac8c \ub429\ub2c8\ub2e4. \ubcf4\uc548\uacfc \ube4c\ub4dc \ub3c4\uad6c \ud638\ud658\uae4c\uc9c0 \uac19\uc774 \ubcf4\uba74 \uc624\ub798 \ubc84\ud2f0\ub294 \uc804\ub7b5\uc740 \uc544\ub2d9\ub2c8\ub2e4.\\n- **\uacf5\uc720 \uacbd\uacc4\ub97c \ub354 \uc587\uac8c \uac00\uc838\uac08 \uc774\uc720\uac00 \uc0dd\uacbc\uc2b5\ub2c8\ub2e4.** Swift \ucabd\uc5d0 \ub85c\uc9c1\uc774 \ub9ce\uc774 \ub0a8\uc544 \uc788\uc73c\uba74 IDE\ub97c \uc624\uac08 \ub54c\ub9c8\ub2e4 \ub9e5\ub77d\uc774 \ub04a\uae41\ub2c8\ub2e4. \ubc18\ub300\ub85c Swift\ub97c \ud654\uba74 \uc9c4\uc785\uacfc \ud50c\ub7ab\ud3fc \uc5f0\uacb0 \uc815\ub3c4\ub85c \uc587\uac8c \ub450\uace0, \uc0c1\ud0dc\uc640 \uaddc\uce59\uc744 Kotlin\uc5d0 \ub450\uba74 \uc774\ubc88 \ubcc0\ud654\uc758 \ub9c8\ucc30\uc774 \uc791\uc544\uc9d1\ub2c8\ub2e4.\\n\\n\uc800\ub294 \uc774 \uc18c\uc2dd\uc744 KMP \uc790\uccb4\uac00 \uc57d\ud574\uc84c\ub2e4\ub294 \uc2e0\ud638\ub85c \ubcf4\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4. \uc624\ud788\ub824 JetBrains\uac00 \uc798 \uc4f0\uc774\uc9c0 \uc54a\ub294 \ud1b5\ud569\uc744 \uac77\uc5b4\ub0b4\uace0, \uc2e4\uc81c\ub85c \ub9ce\uc774 \uc4f0\uc774\ub294 Kotlin \ucabd \uacbd\ud5d8\uc5d0 \uc9d1\uc911\ud558\uaca0\ub2e4\ub294 \ucabd\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \ub098\ub220\ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uc0c8\ub85c KMP\ub97c \uc2dc\uc791\ud55c\ub2e4\uba74 \ucc98\uc74c\ubd80\ud130 Swift \uce35\uc744 \uc587\uac8c \uc7a1\ub294 \uad6c\uc131\uc774 \uc548\uc804\ud574 \ubcf4\uc785\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uba74 iOS \uc9c4\uc785\uc810\uc740 Compose \ud654\uba74\uc744 \uac10\uc2f8\ub294 \uc5ed\ud560\ub9cc \ud558\uace0, \ub098\uba38\uc9c0\ub294 \uacf5\uc720 \ubaa8\ub4c8\uc774 \ub9e1\ub294 \uc2dd\uc785\ub2c8\ub2e4.\\n\\n```swift\\n// iosApp: Swift\ub294 \uc9c4\uc785\uc810\ub9cc \ub2f4\ub2f9\ud558\uace0, \ud654\uba74\uacfc \uc0c1\ud0dc\ub294 \uacf5\uc720 \ubaa8\ub4c8\uc5d0 \ub454\ub2e4\\nimport SwiftUI\\nimport Shared\\n\\nstruct ContentView: View {\\n    var body: some View {\\n        ComposeView()\\n            .ignoresSafeArea()\\n    }\\n}\\n\\nstruct ComposeView: UIViewControllerRepresentable {\\n    func makeUIViewController(context: Context) -> UIViewController {\\n        MainViewControllerKt.MainViewController()\\n    }\\n    func updateUIViewController(_ uiViewController: UIViewController, context: Context) {}\\n}\\n```\\n\\n```kotlin\\n// shared: iOS\uc640 Android\uac00 \uac19\uc774 \uc4f0\ub294 \ud654\uba74 \uc9c4\uc785\uc810\\nfun MainViewController() = ComposeUIViewController {\\n    App()\\n}\\n```\\n\\n\uc774\ub807\uac8c \ub450\uba74 Swift\ub97c \uc218\uc815\ud560 \uc77c\uc774 \uc0dd\uaca8\ub3c4 Xcode\uc5d0\uc11c \ubcf4\ub294 \ubc94\uc704\uac00 \uc791\uace0, \ub300\ubd80\ubd84\uc758 \ubcc0\uacbd\uc740 Kotlin \ucabd\uc5d0\uc11c \ub05d\ub0a9\ub2c8\ub2e4. \uc774\ubbf8 Swift\uc5d0 \ub85c\uc9c1\uc774 \ub9ce\uc774 \ub4e4\uc5b4\uac00 \uc788\ub294 \ud504\ub85c\uc81d\ud2b8\ub77c\uba74, \ud55c \ubc88\uc5d0 \uc62e\uae30\uae30\ubcf4\ub2e4 \uc0c8\ub85c \ub9cc\ub4dc\ub294 \ud654\uba74\ubd80\ud130 \uc774 \uacbd\uacc4\ub97c \uc801\uc6a9\ud574 \ubcf4\ub294 \uac83\ub3c4 \ubc29\ubc95\uc785\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\nKMP\ub97c \uc4f0\ub294 \ud300\uc774\ub77c\uba74 IDE\ub97c \uc62c\ub9ac\uae30 \uc804\uc5d0 \ud55c \ubc88\ub9cc \uc810\uac80\ud574 \ubcf4\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4. Swift \ud30c\uc77c\uc744 \uc9c0\uae08 \uc5b4\ub290 \ub3c4\uad6c\uc5d0\uc11c \uace0\uce58\uace0 \uc788\ub294\uc9c0, \uadf8 \ud750\ub984\uc774 \uc0c8 \ubc84\uc804\uc5d0\uc11c\ub3c4 \uc774\uc5b4\uc9c0\ub294\uc9c0 \ud655\uc778\ud558\ub294 \uac83\ub9cc\uc73c\ub85c \uc5c5\uadf8\ub808\uc774\ub4dc \ub4a4\uc758 \ud63c\ub780\uc744 \uc904\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [Discontinuing Swift Language IDE Support in the Kotlin Multiplatform Plugin \u2014 The Kotlin Blog](https://blog.jetbrains.com/kotlin/2026/10/discontinuing-swift-language-ide-support-in-the-kotlin-multiplatform-plugin/)"},{"id":"ml-drift-litert-gpu","metadata":{"permalink":"/blog/posts/ml-drift-litert-gpu","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-10-ml-drift-litert-gpu/index.mdx","source":"@site/blog/2026-10-10-ml-drift-litert-gpu/index.mdx","title":"ML Drift \uc624\ud508\uc18c\uc2a4 \uacf5\uac1c \u2014 LiteRT GPU \uac00\uc18d\uc758 \uc0c8 \uc5d4\uc9c4, TFLite GPU delegate\uc758 \ub4a4\ub97c \uc787\ub2e4","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-10T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"ai","permalink":"/blog/posts/tags/ai"},{"inline":true,"label":"litert","permalink":"/blog/posts/tags/litert"},{"inline":true,"label":"on-device","permalink":"/blog/posts/tags/on-device"},{"inline":true,"label":"ml","permalink":"/blog/posts/tags/ml"}],"readingTime":4.1,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"ml-drift-litert-gpu","title":"ML Drift \uc624\ud508\uc18c\uc2a4 \uacf5\uac1c \u2014 LiteRT GPU \uac00\uc18d\uc758 \uc0c8 \uc5d4\uc9c4, TFLite GPU delegate\uc758 \ub4a4\ub97c \uc787\ub2e4","authors":["way"],"tags":["android","ai","litert","on-device","ml"]},"unlisted":false,"prevItem":{"title":"KMP \ud50c\ub7ec\uadf8\uc778\uc758 Swift IDE \uc9c0\uc6d0 \uc885\ub8cc \u2014 2026.3\ubd80\ud130 Swift \uc791\uc5c5\uc740 Xcode\ub85c \ub098\ub220\uc57c \ud55c\ub2e4","permalink":"/blog/posts/kmp-swift-ide-discontinued"},"nextItem":{"title":"Android CLI\uc5d0 \uc2e4\uae30\uae30 \uc2a4\ud2b8\ub9ac\ubc0d\uc774 \ubd99\uc5c8\ub2e4 \u2014 \uc5d0\uc774\uc804\ud2b8\uac00 \uc6d0\uaca9 \ub2e8\ub9d0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud558\ub294 \ud750\ub984","permalink":"/blog/posts/android-cli-device-streaming"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 8\uc77c, Google AI Edge \ud300\uc774 \uc628\ub514\ubc14\uc774\uc2a4 GPU \ucd94\ub860\uc744 \uc704\ud55c \uc0c8 \uc5d4\uc9c4 ML Drift\ub97c Apache 2.0 \ub77c\uc774\uc120\uc2a4\ub85c \uacf5\uac1c\ud588\uc2b5\ub2c8\ub2e4. LiteRT \uc548\uc5d0\uc11c GPU \uac00\uc18d\uc744 \ub9e1\ub294 \uc911\uc2ec \uc5d4\uc9c4\uc774\uae30\ub3c4 \ud558\uace0, \ub530\ub85c \ub5bc\uc5b4\ub0b4\uc5b4 \ucee4\uc2a4\ud140 \uadf8\ub798\ud53d\uc774\ub098 \ucd94\ub860 \ub7f0\ud0c0\uc784\uc744 \ub9cc\ub4e4 \ub54c \uc4f0\ub294 \ub3c5\ub9bd \ub77c\uc774\ube0c\ub7ec\ub9ac\ub85c\ub3c4 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- ML Drift\ub294 \uae30\uae30\ub9c8\ub2e4 \ub2e4\ub978 GPU \ud658\uacbd\uc744 \ud55c \uce35\uc73c\ub85c \uac10\uc2f8\ub294 \ud06c\ub85c\uc2a4 \ud50c\ub7ab\ud3fc GPU \ucef4\ud4e8\ud2b8 \uc5d4\uc9c4\uc785\ub2c8\ub2e4. \ub4a4\ucabd\uc5d0\uc11c\ub294 OpenGL ES, OpenCL, Metal, WebGPU \uac19\uc740 \uc11c\ub85c \ub2e4\ub978 \uadf8\ub798\ud53d \uacbd\ub85c\ub97c \ub2e4\ub8f9\ub2c8\ub2e4.\\n- \uae30\uc874 TensorFlow Lite GPU delegate\uac00 \ub9e1\ub358 \uc790\ub9ac\ub97c \uc774\uc5b4\ubc1b\ub294 \ubc29\ud5a5\uc774\uba70, \uc55e\uc73c\ub85c \uadf8 \uc608\uc804 \uacbd\ub85c\ub294 \uc0c8 \uae30\ub2a5\uc744 \ub354 \ubc1b\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc774\ub3d9 \uacbd\ub85c\ub294 LiteRT\uc758 ML Drift GPU \uac00\uc18d \uacbd\ub85c\uc785\ub2c8\ub2e4.\\n- \uace0\uc804\uc801\uc778 \ube44\uc804 \ubaa8\ub378\ubfd0 \uc544\ub2c8\ub77c, \uae30\uae30\uc5d0\uc11c \ub3c4\ub294 \uc0dd\uc131\ud615 \ubaa8\ub378\uae4c\uc9c0 \ud568\uaed8 \ub178\ub9b0 \uad6c\uc870 \uac1c\ud3b8\uc774 \ub4e4\uc5b4\uac14\uc2b5\ub2c8\ub2e4.\\n\\n\uc11c\ubc84\uc5d0\uc11c\ub294 \ube44\uc2b7\ud55c \uac00\uc18d\uae30\uac00 \uc904\uc9c0\uc5b4 \uc788\uc9c0\ub9cc, \ud734\ub300\ud3f0\uc740 \uce69\uacfc \ub4dc\ub77c\uc774\ubc84\uc640 \uadf8\ub798\ud53d \uacbd\ub85c\uac00 \uc81c\uac01\uac01\uc785\ub2c8\ub2e4. \uc774 \ub2e4\uc591\uc131\uc744 \uc571 \uac1c\ubc1c\uc790\uac00 \uc9c1\uc811 \uba54\uc6b0\uc9c0 \uc54a\uac8c \ud558\ub294 \uac83\uc774 \uc774 \uc5d4\uc9c4\uc774 \ud480\ub824\ub294 \ubb38\uc81c\uc785\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### \ud150\uc11c\ub97c \ubc14\ub77c\ubcf4\ub294 \ubc29\uc2dd\uc744 \ubc14\uafe8\ub2e4\\n\\n\uc608\uc804 \ubc29\uc2dd\uc5d0\uc11c\ub294 \ud150\uc11c\uac00 GPU\uc758 \ud14d\uc2a4\ucc98\ub098 \ubc84\ud37c \uac19\uc740 \uc2e4\uc81c \uc790\uc6d0\uc5d0 \uc5b4\ub5bb\uac8c \ubd99\ub294\uc9c0\ub97c \ubc31\uc5d4\ub4dc\ub9c8\ub2e4 \ub530\ub85c \uc801\uc5b4 \ub450\ub294 \uc77c\uc774 \ub9ce\uc558\uc2b5\ub2c8\ub2e4. ML Drift\ub294 \uc5ec\uae30\uc11c \ud55c \ub2e8\uacc4 \ucd94\uc0c1\ud654\ub97c \ub123\uc5c8\uc2b5\ub2c8\ub2e4. \ub17c\ub9ac\uc801\uc778 \ud150\uc11c\uc640 \uc2e4\uc81c GPU \ubc30\uce58\ub97c \ubd84\ub9ac\ud574 \ub450\uace0, \ucd08\uae30 \uc124\uc815 \ub2e8\uacc4\uc5d0\uc11c \uc170\uc774\ub354\uac00 \uadf8 \uc5f0\uacb0\uc744 \ud480\uc5b4\ub0b4\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4. \ub355\ubd84\uc5d0 \ubc31\uc5d4\ub4dc\ub9c8\ub2e4 \uc170\uc774\ub354\ub97c \ub530\ub85c \uc720\uc9c0\ud558\ub294 \ubd80\ub2f4\uc744 \uc904\uc774\uba74\uc11c\ub3c4 \uc2e4\ud589 \uc911 \ubd80\ub2f4\uc740 \uc791\uac8c \uac00\uc838\uac00\ub824 \ud588\ub2e4\ub294 \uc124\uba85\uc785\ub2c8\ub2e4.\\n\\n#### 5\ucc28\uc6d0 \ud150\uc11c\uc640 \uc2dc\uacf5\uac04 \ubaa8\ub378\\n\\n\uc608\uc804 GPU \uacbd\ub85c\ub294 4\ucc28\uc6d0 \ud150\uc11c\ub97c \uc804\uc81c\ub85c \uc9dc\uc5ec \uc788\uc5b4, \uadf8\ubcf4\ub2e4 \ubcf5\uc7a1\ud55c \ubaa8\uc591\uc774 \ud544\uc694\ud558\uba74 \uc6b0\ud68c\ub85c\ub97c \ub9cc\ub4e4\uc5b4\uc57c \ud588\uc2b5\ub2c8\ub2e4. \uc0c8 \uc5d4\uc9c4\uc5d0\uc11c\ub294 5\ucc28\uc6d0 \ud150\uc11c\ub97c \uae30\ubcf8\uc73c\ub85c \ub2e4\ub8f0 \uc218 \uc788\uac8c \ub418\uba74\uc11c, 3\ucc28\uc6d0 \ud569\uc131\uacf1\uc774\ub098 \uc601\uc0c1\ucc98\ub7fc \uc2dc\uac04 \ucd95\uc774 \ubd99\uc740 \ubaa8\ub378\uc744 \uae30\uae30 GPU\uc5d0\uc11c \ubc14\ub85c \ub3cc\ub9ac\ub294 \uae38\uc774 \ub113\uc5b4\uc84c\uc2b5\ub2c8\ub2e4.\\n\\n#### LLM \ub2e8\uacc4\uc5d0 \ub530\ub77c \ucee4\ub110\uc744 \ubc14\uafbc\ub2e4\\n\\n\uae30\uae30\uc5d0\uc11c \ub3c4\ub294 \uc5b8\uc5b4 \ubaa8\ub378\uc740 \ud55c \ubc88\uc5d0 \uae38\uac8c \uc77d\uc5b4 \ub4e4\uc774\ub294 \uad6c\uac04\uacfc, \ud1a0\ud070\uc744 \ud558\ub098\uc529 \uc774\uc5b4 \ubd99\uc774\ub294 \uad6c\uac04\uc758 \uc131\uaca9\uc774 \ub2e4\ub985\ub2c8\ub2e4. \uc55e\ucabd\uc740 \uc5f0\uc0b0\ub7c9\uc5d0, \ub4a4\ucabd\uc740 \uba54\ubaa8\ub9ac \uc774\ub3d9\uc5d0 \ub354 \ubb36\uc785\ub2c8\ub2e4. ML Drift\ub294 \uc9c0\uae08\uc774 \uc5b4\ub290 \ub2e8\uacc4\uc778\uc9c0\uc5d0 \ub530\ub77c \ucee4\ub110\uacfc \ubc30\uce58\ub97c \ubc14\uafb8\uace0, KV \uce90\uc2dc \ucabd\uc5d0\ub3c4 \uc804\uc6a9 \ubc30\uce58\ub97c \uc801\uc6a9\ud574 \ubd88\ud544\uc694\ud55c \uc655\ubcf5\uc744 \uc904\uc774\ub294 \ubc29\ud5a5\uc744 \ud0dd\ud588\uc2b5\ub2c8\ub2e4.\\n\\n#### \ucee4\uc2a4\ud140 \uc5f0\uc0b0\uacfc \ub370\uc2a4\ud06c\ud1b1 \ud655\uc7a5\\n\\n\ubaa8\ub378\uc5d0 \ud2b9\uc774\ud55c \ube14\ub85d\uc774 \uc788\uc73c\uba74 \uac1c\ubc1c\uc790\uac00 \ub0ae\uc740 \uc218\uc900\uc758 \uc170\uc774\ub529 \uc5b8\uc5b4\ub85c \uc9c1\uc811 \uc5f0\uc0b0\uc744 \ub4f1\ub85d\ud560 \uc218 \uc788\ub294 \uae38\ub3c4 \uc0c8\ub85c \uc815\ub9ac\ub410\uc2b5\ub2c8\ub2e4. \ud765\ubbf8\ub85c\uc6b4 \ubd80\ubd84\uc740, \ucf54\ub529 \uc5d0\uc774\uc804\ud2b8\uac00 \uc774 \ucee4\uc2a4\ud140 \uc170\uc774\ub354\ub97c \ub9cc\ub4e4\uace0 \uac80\uc99d\ud558\ub294 \uacfc\uc815\uc744 \ub3d5\ub294 \uc548\ub0b4 \ud30c\uc77c\uae4c\uc9c0 \ud568\uaed8 \uc81c\uacf5\ub41c\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4. \ub610 WebGPU \uacbd\ub85c\ub97c \ubc14\ud0d5\uc73c\ub85c \ube0c\ub77c\uc6b0\uc800 \ubc16 Windows\uc640 Linux\uc5d0\uc11c\ub3c4 \uac19\uc740 \ucf54\ub4dc\ub97c \ub3cc\ub9ac\ub294 \ubbf8\ub9ac\ubcf4\uae30\uac00 \uc18c\uac1c\ub410\uace0, macOS\uc5d0\uc11c\ub294 Metal \uacbd\ub85c\uac00 \uc774\ub97c \ubc1b\uce69\ub2c8\ub2e4.\\n\\n\uc2e4\uc81c \uc11c\ube44\uc2a4\uc5d0\uc11c\uc758 \uc4f0\uc784\ub3c4 \ud568\uaed8 \uc18c\uac1c\ub410\uc2b5\ub2c8\ub2e4. \uc601\uc0c1 \ud6a8\uacfc, \uc0ac\uc9c4 \ubcf4\uc815, \ube0c\ub77c\uc6b0\uc800 \uc548 \uc628\ub514\ubc14\uc774\uc2a4 \ubaa8\ub378, \uc0ac\uc9c4 \ud3b8\uc9d1 \uc571\uc758 \ud53c\uc0ac\uccb4 \uc120\ud0dd \uac19\uc740 \uc791\uc5c5\uc5d0\uc11c \uae30\uc874 GPU \uacbd\ub85c\ubcf4\ub2e4 \uc9c0\uc5f0\uc774 \uc904\uc5c8\ub2e4\ub294 \uc0ac\ub840\uac00 \uc2e4\ub838\uc2b5\ub2c8\ub2e4. \uc22b\uc790\ub294 \ubaa8\ub378\uacfc \uae30\uae30\ub9c8\ub2e4 \ub2e4\ub974\ub2c8, \uacb0\uad6d \ub0b4 \ubaa8\ub378\ub85c \uc7ac\ubcf4\ub294 \uc218\ubc16\uc5d0 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n- **TFLite GPU delegate\ub97c \uc9c1\uc811 \uc4f0\uace0 \uc788\ub2e4\uba74 \uc774\ub3d9 \uacc4\ud68d\uc744 \uc138\uc6b8 \ub54c\uc785\ub2c8\ub2e4.** \uc0c8 \uae30\ub2a5\uc774 \uadf8\ucabd\uc73c\ub85c \ub354 \uc624\uc9c0 \uc54a\ub294\ub2e4\uace0 \ubabb \ubc15\uc740 \ub9cc\ud07c, \uc9c0\uae08 \ub2f9\uc7a5 \ub04a\uae30\uc9c0\ub294 \uc54a\ub354\ub77c\ub3c4 \ub2e4\uc74c \ubaa8\ub378 \uad50\uccb4\ub098 \uc131\ub2a5 \uac1c\uc120 \uc2dc\uc810\uc5d0 LiteRT \uacbd\ub85c\ub85c \ubca4\uce58\ub9c8\ud06c\ub97c \ud55c \ubc88\uc740 \ub3cc\ub824\ubd10\uc57c \ud569\ub2c8\ub2e4.\\n- **\ubca4\uce58\ub9c8\ud06c\ub294 \ubaa8\ub378 \uc804\uccb4 \ud3c9\uade0\ub9cc \ubcf4\uba74 \uc548 \ub429\ub2c8\ub2e4.** \uc5b8\uc5b4 \ubaa8\ub378\uc774\ub77c\uba74 \uc77d\uc5b4 \ub4e4\uc774\ub294 \uad6c\uac04\uacfc \ud1a0\ud070\uc744 \ub9cc\ub4dc\ub294 \uad6c\uac04\uc758 \uc18d\ub3c4\uac00 \ub530\ub85c \uc6c0\uc9c1\uc785\ub2c8\ub2e4. \ub450 \uad6c\uac04\uc744 \ub098\ub220 \uc7ac\uc9c0 \uc54a\uc73c\uba74 \ubcd1\ubaa9\uc774 \uc5b4\ub514\uc778\uc9c0 \ub193\uce58\uae30 \uc27d\uc2b5\ub2c8\ub2e4.\\n- **GPU \ubca4\ub354\ubcc4 \ud655\uc778\uc740 \uc5ec\uc804\ud788 \ud544\uc694\ud569\ub2c8\ub2e4.** \ucd94\uc0c1\ud654\uac00 \uc88b\uc544\uc84c\ub2e4\uace0 \ud574\ub3c4 \uc2e4\uc81c \uc18d\ub3c4\ub294 \uce69\uacfc \ub4dc\ub77c\uc774\ubc84\uc5d0\uc11c \uac08\ub9bd\ub2c8\ub2e4. \ud50c\ub798\uadf8\uc2ed \ud55c \ub300\uc5d0\uc11c\ub9cc \uc7ac\uace0 \ub05d\ub0b4\uba74 \uc911\uc800\uac00 \uae30\uae30\uc5d0\uc11c \uccb4\uac10\uc774 \ub2e4\ub974\uac8c \ub098\uc62c \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- **\ucee4\uc2a4\ud140 \uc5f0\uc0b0\uc740 \uac15\ub825\ud558\uc9c0\ub9cc \uc720\uc9c0 \ube44\uc6a9\uc774 \ubd99\uc2b5\ub2c8\ub2e4.** \uc9c1\uc811 \uc9e0 \uc170\uc774\ub354\ub294 \ubaa8\ub378\uc744 \ubc14\uafc0 \ub54c\ub9c8\ub2e4 \ub2e4\uc2dc \ubd10\uc57c \ud569\ub2c8\ub2e4. \uaf2d \ud544\uc694\ud55c \ube14\ub85d\uc5d0\ub9cc \uc4f0\uace0, \ub098\uba38\uc9c0\ub294 \uae30\ubcf8 \uc5f0\uc0b0\uc73c\ub85c \ub450\ub294 \ud3b8\uc774 \uc6b4\uc601\uc5d0 \ub0ab\uc2b5\ub2c8\ub2e4.\\n\\n\uae08\uc735 \uc571 \uad00\uc810\uc5d0\uc11c\ub294, \uc0ac\uc9c4\uc744 \uc77d\uc5b4 \ubb38\uc11c\ub97c \uc778\uc2dd\ud558\uac70\ub098 \uae30\uae30 \uc548\uc5d0\uc11c \uc791\uc740 \ubaa8\ub378\ub85c \ubd84\ub958\ud558\ub294 \uc791\uc5c5\uc744 \uc11c\ubc84\ub85c \ubcf4\ub0b4\uc9c0 \uc54a\uace0 \ub05d\ub0bc \uc218 \uc788\uc744 \ub54c \uc758\ubbf8\uac00 \ud07d\ub2c8\ub2e4. \ub370\uc774\ud130\ub97c \uae30\uae30 \ubc16\uc73c\ub85c \ub0b4\ubcf4\ub0b4\uc9c0 \uc54a\ub294 \uad6c\uc870\ub294 \uac1c\uc778\uc815\ubcf4\uc640 \ub124\ud2b8\uc6cc\ud06c \ube44\uc6a9 \uc591\ucabd\uc5d0\uc11c \uc774\ub4dd\uc774 \uc788\uae30 \ub54c\ubb38\uc785\ub2c8\ub2e4. \ub2e4\ub9cc \uadf8 \uc804\uc81c\ub294 \uacb0\uad6d \uc18d\ub3c4\uc778\ub370, \uc774\ubc88 \uac1c\ud3b8\uc740 \uadf8 \uc18d\ub3c4\ub97c \ubca4\ub354 \uc911\ub9bd\uc801\uc73c\ub85c \ub04c\uc5b4\uc62c\ub9ac\ub824\ub294 \uc2dc\ub3c4\ub77c\uace0 \uc77d\ud799\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c\ub294 \uc774\ub807\uac8c \uc7ac\ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uc800\ub77c\uba74 \uae30\uc874\uc5d0 GPU delegate\ub85c \ub3cc\ub9ac\ub358 \ubaa8\ub378\uc744 LiteRT \uacbd\ub85c\ub85c \ubc14\uafd4 \uac19\uc740 \uae30\uae30\uc5d0\uc11c \ub098\ub780\ud788 \uc7ac\ub294 \uac83\ubd80\ud130 \uc2dc\uc791\ud558\uaca0\uc2b5\ub2c8\ub2e4. \uc544\ub798\ub294 \uac1c\ub150\uc744 \uc7a1\uae30 \uc704\ud55c \uc608\uc2dc \ud750\ub984\uc785\ub2c8\ub2e4.\\n\\n```kotlin\\n// \uac19\uc740 \ubaa8\ub378\uc744 CPU\uc640 GPU \uacbd\ub85c\ub85c \uac01\uac01 \uc900\ube44\ud574 \uc9c0\uc5f0\uc744 \ub098\ub220 \uc7ac\ub294 \ubca4\uce58\ub9c8\ud06c \ubf08\ub300\\ndata class BenchResult(\\n    val backend: String,\\n    val warmupMs: Double,\\n    val steadyMs: Double,\\n)\\n\\nfun benchmarkModel(backend: String): BenchResult {\\n    // 1) LiteRT \ubaa8\ub378\uc744 backend \uc635\uc158\uc73c\ub85c \uc5f0\ub2e4 (GPU\uba74 ML Drift \uac00\uc18d \uacbd\ub85c)\\n    // 2) warm-up\uc744 \ucda9\ubd84\ud788 \ub3cc\ub9b0 \ub4a4, \uc785\ub825 \ubaa8\uc591\ubcc4\ub85c \uc9c0\uc5f0\uc744 \uce21\uc815\ud55c\ub2e4\\n    // 3) \uc5b8\uc5b4 \ubaa8\ub378\uc774\uba74 prefill\uacfc decode\ub97c \ubd84\ub9ac\ud574\uc11c \uae30\ub85d\ud55c\ub2e4\\n    return BenchResult(backend, warmupMs = 0.0, steadyMs = 0.0)\\n}\\n\\nval results = listOf(\\"CPU\\", \\"GPU\\").map { benchmarkModel(it) }\\nresults.forEach { println(\\"${it.backend}: steady=${it.steadyMs}ms\\") }\\n```\\n\\n\uc5ec\uae30\uc5d0 \uae30\uae30 \uc774\ub984\uacfc \uce69 \uc815\ubcf4, \ubaa8\ub378 \ubc84\uc804\uc744 \ud568\uaed8 \ub0a8\uaca8 \ub450\uba74 \ub098\uc911\uc5d0 \\"\uc5b4\ub5a4 \ud3f0\uc5d0\uc11c \ub290\ub824\uc84c\ub294\uc9c0\\"\ub97c \ucd94\uc801\ud558\uae30\uac00 \ud6e8\uc52c \uc26c\uc6cc\uc9d1\ub2c8\ub2e4. \ucee4\uc2a4\ud140 \uc5f0\uc0b0\uc740 \uc774 \uae30\ubcf8 \uce21\uc815\uc774 \ub05d\ub09c \ub4a4, \ud504\ub85c\ud30c\uc77c\uc5d0\uc11c \uc2e4\uc81c\ub85c \ub728\uac70\uc6b4 \ube14\ub85d\uc774 \ubcf4\uc77c \ub54c\ub9cc \uc190\ub300\ub294 \uc21c\uc11c\uac00 \uc88b\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n\ub3c5\ub9bd \ub77c\uc774\ube0c\ub7ec\ub9ac \ucabd\uc774 \uad81\uae08\ud558\ub2e4\uba74 \uacf5\uac1c \uc800\uc7a5\uc18c\uc5d0\uc11c Android\uc6a9 OpenCL \uc2dc\uc791 \uac00\uc774\ub4dc\ubd80\ud130 \ubcfc \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc628\ub514\ubc14\uc774\uc2a4 \ucd94\ub860\uc740 \uc774\uc81c \uc2e4\ud5d8 \uae30\ub2a5\uc774 \uc544\ub2c8\ub77c, \uc601\uc0c1\uacfc \uc0ac\uc9c4\uacfc \uc0dd\uc131\ud615 \uae30\ub2a5\uc774 \uc2e4\uc81c\ub85c \ub3c4\ub294 \ubc14\ub2e5\uc774 \ub418\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uadf8 \ubc14\ub2e5\uc758 GPU \uce35\uc774 \uc624\ud508\uc18c\uc2a4\ub85c \uc5f4\ub9ac\uace0 \uc608\uc804 \uacbd\ub85c\uc758 \uc885\ub8cc \ubc29\ud5a5\uae4c\uc9c0 \uc815\ud574\uc9c4 \ub9cc\ud07c, \uad00\ub828 \uae30\ub2a5\uc744 \uac00\uc9c4 \ud300\uc774\ub77c\uba74 \ud55c \ubc88\uc740 \ud604\uc7ac \uc2a4\ud0dd\uc744 \uc810\uac80\ud574 \ubcfc \uc2dc\uc810\uc785\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [ML Drift: Next-Gen GPU AI/ML Inference at the Edge \u2014 Google Developers Blog](https://developers.googleblog.com/en/ml-drift-next-gen-gpu-aiml-inference-at-the-edge/) \xb7 [ML Drift GitHub \uc800\uc7a5\uc18c](https://github.com/google-ai-edge/ml-drift)"},{"id":"android-cli-device-streaming","metadata":{"permalink":"/blog/posts/android-cli-device-streaming","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-09-android-cli-device-streaming/index.mdx","source":"@site/blog/2026-10-09-android-cli-device-streaming/index.mdx","title":"Android CLI\uc5d0 \uc2e4\uae30\uae30 \uc2a4\ud2b8\ub9ac\ubc0d\uc774 \ubd99\uc5c8\ub2e4 \u2014 \uc5d0\uc774\uc804\ud2b8\uac00 \uc6d0\uaca9 \ub2e8\ub9d0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud558\ub294 \ud750\ub984","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-09T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"android-cli","permalink":"/blog/posts/tags/android-cli"},{"inline":true,"label":"ai-agent","permalink":"/blog/posts/tags/ai-agent"},{"inline":true,"label":"testing","permalink":"/blog/posts/tags/testing"}],"readingTime":3.82,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"android-cli-device-streaming","title":"Android CLI\uc5d0 \uc2e4\uae30\uae30 \uc2a4\ud2b8\ub9ac\ubc0d\uc774 \ubd99\uc5c8\ub2e4 \u2014 \uc5d0\uc774\uc804\ud2b8\uac00 \uc6d0\uaca9 \ub2e8\ub9d0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud558\ub294 \ud750\ub984","authors":["way"],"tags":["android","android-cli","ai-agent","testing"]},"unlisted":false,"prevItem":{"title":"ML Drift \uc624\ud508\uc18c\uc2a4 \uacf5\uac1c \u2014 LiteRT GPU \uac00\uc18d\uc758 \uc0c8 \uc5d4\uc9c4, TFLite GPU delegate\uc758 \ub4a4\ub97c \uc787\ub2e4","permalink":"/blog/posts/ml-drift-litert-gpu"},"nextItem":{"title":"IntelliJ\uc758 Kotlin \uc778\ud154\ub9ac\uc804\uc2a4\uac00 VS Code\ub85c \uc654\ub2e4 \u2014 Java and Kotlin \ud655\uc7a5 RC \uacf5\uac1c","permalink":"/blog/posts/intellij-lsp-rc"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 2\uc77c, Android Developers Blog\ub97c \ud1b5\ud574 Android CLI \uc5c5\ub370\uc774\ud2b8\uac00 \uacf5\uac1c\ub410\uc2b5\ub2c8\ub2e4. \ud575\uc2ec\uc740 \ub450 \uac00\uc9c0\uc785\ub2c8\ub2e4. \uc6d0\uaca9 \uc2e4\uae30\uae30\uc5d0 \ubd99\ub294 Device Streaming\uc744 CLI\uc5d0\uc11c \uc4f8 \uc218 \uc788\uac8c \ub410\uace0, \uc5d0\uc774\uc804\ud2b8\uc6a9 Android skills\uac00 20\uac1c\ub97c \ub118\uc5b4\uc130\uc2b5\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- Android CLI\ub294 \ud2b9\uc815 AI \ubaa8\ub378\uc5d0 \ubb36\uc774\uc9c0 \uc54a\uace0, \ub2e4\uc591\ud55c \ucf54\ub529 \uc5d0\uc774\uc804\ud2b8\uc640 \ud568\uaed8 \ud504\ub85c\uc81d\ud2b8 \uc0dd\uc131, \ube4c\ub4dc, \ud14c\uc2a4\ud2b8, \uc5d0\ubbac\ub808\uc774\ud130 \uc2e4\ud589\uc744 \ub3d5\ub294 \ucee4\ub9e8\ub4dc\ub77c\uc778 \ub3c4\uad6c\uc785\ub2c8\ub2e4.\\n- \uc774\uc81c CLI\ub97c \ud1b5\ud574 Android Device Streaming\uc5d0 \uc811\uc18d\ud558\uba74, \uc190\uc5d0 \uc5c6\ub294 \uc2e4\uae30\uae30\ub77c\ub3c4 \uc6d0\uaca9\uc73c\ub85c \uc571\uc744 \uc62c\ub9ac\uace0 \ub85c\uadf8\uc640 \ud2b8\ub808\uc774\uc2a4\ub97c \uc218\uc9d1\ud558\uace0 \uc2a4\ud06c\ub9b0\uc0f7\uae4c\uc9c0 \ucc0d\uc744 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n- Android skills\ub294 `SKILL.md` \ud615\ud0dc\uc758 \uad6c\uc870\ud654\ub41c \uc9c0\uce68 \ubaa8\uc74c\uc785\ub2c8\ub2e4. \ubaa8\ub378\uc758 \ud559\uc2b5 \uc2dc\uc810\uc5d0 \uae30\ub300\uc9c0 \uc54a\uace0, \uacf5\uc2dd \uac00\uc774\ub4dc \uae30\uc900\uc73c\ub85c \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \ub9e5\ub77d\uc744 \uc8fc\uc785\ud558\ub294 \ubc29\uc2dd\uc785\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n#### 1) Device Streaming\uc744 \uc5d0\uc774\uc804\ud2b8\uac00 \uc9c1\uc811 \uc4f4\ub2e4\\n\\n\uc2e4\uae30\uae30\uc5d0\uc11c\ub9cc \uc7ac\ud604\ub418\ub294 \ud558\ub4dc\uc6e8\uc5b4/OS \uc774\uc288\ub294 \uc5d0\ubbac\ub808\uc774\ud130\ub85c \ub193\uce58\uae30 \uc27d\uc9c0\ub9cc, \ud544\uc694\ud55c \ub2e8\ub9d0\uc774 \ud56d\uc0c1 \ucc45\uc0c1 \uc704\uc5d0 \uc788\ub294 \uac83\ub3c4 \uc544\ub2d9\ub2c8\ub2e4. \uc774\ubc88 \uc5c5\ub370\uc774\ud2b8\ub85c \uc5d0\uc774\uc804\ud2b8\uac00 \ubcf4\uc548\uc774 \uc801\uc6a9\ub41c ADB over SSL \uc5f0\uacb0\uc744 \ud1b5\ud574 \uc6d0\uaca9 \ub2e8\ub9d0\uc744 \ub9c8\uce58 USB\ub85c \uc5f0\uacb0\ud55c \uac83\ucc98\ub7fc \ub2e4\ub8f0 \uc218 \uc788\uac8c \ub410\uc2b5\ub2c8\ub2e4.\\n\\n\uac00\ub2a5\ud55c \uc791\uc5c5\uc740 \ub300\ub7b5 \uc774\ub807\uc2b5\ub2c8\ub2e4.\\n\\n- \uc6d0\uaca9 \ub2e8\ub9d0 \uae68\uc6b0\uae30, \ube4c\ub4dc \ubc30\ud3ec\\n- \ub85c\uadf8/\ud2b8\ub808\uc774\uc2a4 \uc218\uc9d1\\n- \ud5e4\ub4dc\ub9ac\uc2a4 \uc2a4\ud06c\ub9b0\uc0f7 \ucea1\ucc98\\n- \ud130\ubbf8\ub110 \uc548\uc5d0\uc11c \uae30\uae30 \ubaa9\ub85d\uc744 \ubcf4\uace0 \uc5b4\ub5a4 \ub2e8\ub9d0\uc744 \uc4f8\uc9c0 \uc120\ud0dd\\n\\n\uc989, \u201c\ucf54\ub4dc\ub97c \uace0\ucce4\uc73c\ub2c8 \uc2e4\uc81c \ub2e8\ub9d0\uc5d0\uc11c \ub20c\ub7ec\ubcf4\uace0 \uacb0\uacfc\ub97c \uac00\uc838\uc640\u201d \uac19\uc740 \ud750\ub984\uc744 \uc0ac\ub78c\uc774 \uc911\uac04\uc5d0 \ub07c\uc9c0 \uc54a\uace0\ub3c4 \uc2dc\ub3c4\ud560 \uc218 \uc788\ub294 \uae30\ubc18\uc774 \uc0dd\uae34 \uc148\uc785\ub2c8\ub2e4.\\n\\n#### 2) Android skills\uac00 \uc2e4\ubb34\ud615\uc73c\ub85c \ub298\uc5b4\ub0ac\ub2e4\\n\\n\uacf5\uc2dd skills \uc800\uc7a5\uc18c\uc5d0\ub294 \uc774\uc81c 20\uac1c\uac00 \ub118\ub294 \uc2a4\ud0ac\uc774 \uc788\uace0, \uc131\uaca9\ub3c4 \uaf64 \uc2e4\ubb34\uc801\uc785\ub2c8\ub2e4. \uc6d0\ubb38\uc5d0\uc11c \uc18c\uac1c\ud55c \uc608\uc2dc\ub97c \uc81c \ub9d0\ub85c \uc904\uc774\uba74 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n- \uc81c\ucd9c \uc804 Play \uc815\ucc45 \uc900\uc218 \uc810\uac80(\ub9e4\ub2c8\ud398\uc2a4\ud2b8, \uad8c\ud55c, \ud0c0\uae43 SDK, \uac1c\uc778\uc815\ubcf4 \uace0\uc9c0)\\n- Credential Manager \uae30\ubc18 \ubcf5\uc6d0 \ub85c\uadf8\uc778(Restore Credentials) \uad6c\ud604\\n- \uc554\uc2dc\uc801 \uc778\ud150\ud2b8 \ud0c8\ucde8 \uac19\uc740 \uc778\ud150\ud2b8 \ubcf4\uc548 \uc810\uac80\\n- \ud504\ub85c\ud30c\uc77c\ub7ec\ub85c \ud504\ub808\uc784 \ub4dc\ub86d \uc6d0\uc778\uc744 \ucc3e\uace0 PerfettoSQL\ub85c \ud2b8\ub808\uc774\uc2a4 \uc9c8\uc758\\n- \uad6c\ud615 Camera1/Camera2 \ucf54\ub4dc\ub97c CameraX\ub85c \uc774\uc804\\n- Leanback \uae30\ubc18 TV \ud654\uba74\uc744 Compose for TV\ub85c \uc804\ud658\\n- Media3 \uc7ac\uc0dd \uc0c1\ud0dc\uc640 Cast \uc218\uc2e0\uae30 \ub3d9\uae30\ud654\\n- \ud14c\uc2a4\ud2b8 \uc804\ub7b5(\ub2e8\uc704 \ud14c\uc2a4\ud2b8, Compose UI \ud14c\uc2a4\ud2b8, \uc2a4\ud06c\ub9b0\uc0f7 \ud14c\uc2a4\ud2b8) \uc138\ud305\\n- R8 \uc124\uc815 \uac10\uc0ac\\n\\n\uc774\ubc88 \uae00\uc5d0\uc11c\ub294 Wear OS\uc6a9 Compose Material 3 \uc2a4\ud0ac\uc774 \uc2a4\ud3ec\ud2b8\ub77c\uc774\ud2b8\ub85c \uc18c\uac1c\ub410\uc2b5\ub2c8\ub2e4. \ub465\uadfc \ud654\uba74, \ud68c\uc804 \uc785\ub825, \uc800\uc804\ub825, `TransformingLazyColumn`, `AppScaffold`/`ScreenScaffold` \uac19\uc740 Wear \ud2b9\uc720\uc758 \ud328\ud134\uc744 \uc5d0\uc774\uc804\ud2b8\uac00 \ub193\uce58\uc9c0 \uc54a\uac8c \uc7a1\uc544\uc8fc\ub294 \uc2a4\ud0ac\uc778\ub370, FotMob \ud300\uc774 \uae30\uc874 Wear \uc571\uc758 \ub9ac\uc2a4\ud2b8 \uc5ec\ub7ec \uac1c\ub97c \uc774 \ud328\ud134\uc73c\ub85c \uc62e\uae30\uba74\uc11c \ub808\uac70\uc2dc \ub798\ud37c\uc640 \ud68c\uc804/\ud3ec\ucee4\uc2a4 \ubcf4\uc77c\ub7ec\ud50c\ub808\uc774\ud2b8\ub97c \uac77\uc5b4\ub0c8\ub2e4\ub294 \uc0ac\ub840\ub3c4 \ud568\uaed8 \uc2e4\ub838\uc2b5\ub2c8\ub2e4.\\n\\n#### 3) \uc2a4\ud0ac \uad00\ub9ac\uac00 CLI\uc5d0 \ubd99\uc5c8\ub2e4\\n\\n\uc2a4\ud0ac\uc740 \ud504\ub85c\uc81d\ud2b8\ub9c8\ub2e4, \ub610 \uc5d0\uc774\uc804\ud2b8\ub9c8\ub2e4 \ub514\ub809\ud130\ub9ac\uac00 \ub2ec\ub77c\uc11c \uad00\ub9ac\uac00 \ubc88\uac70\ub85c\uc6b8 \uc218 \uc788\ub294\ub370, \ud750\ub984\uc740 \ube44\uad50\uc801 \ub2e8\uc21c\ud558\uac8c \uc815\ub9ac\ub3fc \uc788\uc2b5\ub2c8\ub2e4.\\n\\n```bash\\n# Android CLI \uc124\uce58 \ud6c4 android-cli \uc2a4\ud0ac \uc138\ud305\\nandroid init\\n\\n# \uacf5\uc2dd \uc2a4\ud0ac \ubaa9\ub85d \ud655\uc778\\nandroid skills list\\n\\n# \ud544\uc694\ud55c \uc2a4\ud0ac\ub9cc \ud504\ub85c\uc81d\ud2b8\uc5d0 \ucd94\uac00 (\uc608: Wear Compose M3)\\nandroid skills add wear-compose-m3 --project=.\\n\\n# \ub098\uc911\uc5d0 \uc77c\uad04 \uc5c5\ub370\uc774\ud2b8\\nandroid skills update --all\\n```\\n\\n\uc911\uc694\ud55c \uac74 \uc774 \uc2a4\ud0ac\ub4e4\uc774 \ud2b9\uc815 \ud658\uacbd \uc804\uc6a9\uc774 \uc544\ub2c8\ub77c\ub294 \uc810\uc785\ub2c8\ub2e4. Android Studio, \ub2e4\ub978 \ucf54\ub4dc \uc5d0\ub514\ud130, \uc11c\ub4dc\ud30c\ud2f0 \uc5d0\uc774\uc804\ud2b8 \ud658\uacbd\uc5d0\uc11c\ub3c4 \uac19\uc740 \uc2a4\ud0ac\uc744 \uc7ac\uc0ac\uc6a9\ud558\ub294 \ubc29\ud5a5\uc73c\ub85c \uc124\uacc4\ub410\ub2e4\uace0 \ud569\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\n\uae08\uc735 \uc571\ucc98\ub7fc \ub2e8\ub9d0 \ud30c\ud3b8\ud654\uc640 \ubcf4\uc548 \uc815\ucc45\uc774 \uc911\uc694\ud55c \ud658\uacbd\uc5d0\uc11c\ub294, \uc5d0\uc774\uc804\ud2b8\uac00 \uc2e4\uae30\uae30 \uacb0\uacfc\ub97c \uc9c1\uc811 \ud655\uc778\ud558\ub294 \ud750\ub984\uc774 \ub9e4\ub825\uc801\uc785\ub2c8\ub2e4. \ub2e4\ub9cc \ubc14\ub85c \uc6b4\uc601 \ud30c\uc774\ud504\ub77c\uc778\uc5d0 \ub123\uae30 \uc804\uc5d0 \ud655\uc778\ud560 \uac83\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n- **\uad8c\ud55c\uacfc \ubcf4\uc548 \uc5f0\uacb0**: \uc6d0\uaca9 \ub2e8\ub9d0 \uc811\uc18d\uc740 ADB over SSL \uae30\ubc18\uc774\ub77c\uc9c0\ub9cc, \uc0ac\ub0b4 \ub124\ud2b8\uc6cc\ud06c \uc815\ucc45\uacfc \ub2e8\ub9d0 \uc811\uadfc \ud1b5\uc81c \ubc94\uc704 \uc548\uc5d0\uc11c \uc368\uc57c \ud569\ub2c8\ub2e4. \uc5b4\ub5a4 \ud504\ub85c\uc81d\ud2b8\ub97c \ub9c1\ud06c\ud558\uace0, \uc5b4\ub5a4 \ub85c\uadf8\uac00 \uc678\ubd80\ub85c \ub098\uac00\ub294\uc9c0 \uba3c\uc800 \uc815\ub9ac\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- **\uc2a4\ud0ac\uc740 \uc815\ub2f5\uc9c0\uac00 \uc544\ub2c8\ub77c \ub9e5\ub77d\uc774\ub2e4**: \uc2a4\ud0ac\uc774 \uc788\uc5b4\ub3c4 \ucd5c\uc885 \ud310\ub2e8\uc740 \ucf54\ub4dc \ub9ac\ubdf0\uc640 \ud14c\uc2a4\ud2b8\uac00 \ud574\uc57c \ud569\ub2c8\ub2e4. \ud2b9\ud788 Play \uc815\ucc45, \uad8c\ud55c, \uc778\ud150\ud2b8 \ubcf4\uc548\ucc98\ub7fc \uc2ec\uc0ac/\ubcf4\uc548\uacfc \ub2ff\uc740 \uc601\uc5ed\uc740 \uc2a4\ud0ac \uacb0\uacfc\ub97c \uadf8\ub300\ub85c \ubbff\uc9c0 \ub9d0\uace0 \uccb4\ud06c\ub9ac\uc2a4\ud2b8\ub85c \ud55c \ubc88 \ub354 \ud655\uc778\ud558\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.\\n- **\ube44\uc6a9\uc774 \ub4dc\ub294 \ubc18\ubcf5 \uc2e4\ud589 \uc8fc\uc758**: \u201c\ub2e8\ub9d0\uc5d0\uc11c \ud655\uc778\ud574\ubd10\u201d\ub97c \uc5d0\uc774\uc804\ud2b8 \ub8e8\ud504\uc5d0 \ub123\uc73c\uba74, \uc0ac\ub78c\uc774 \ud560 \ub54c\ubcf4\ub2e4 \ud6e8\uc52c \uc790\uc8fc \uc2e4\ud589\ud558\uac8c \ub429\ub2c8\ub2e4. \ud14c\uc2a4\ud2b8 \ub2e8\ub9d0 \uc2dc\uac04, \ub124\ud2b8\uc6cc\ud06c, CI \ubd84(minute)\uc744 \uba39\ub294 \uad6c\uc870\uc778\uc9c0 \uba3c\uc800 \uc791\uc740 \uc791\uc5c5\uc73c\ub85c \uce21\uc815\ud574 \ubcf4\uae38 \uad8c\ud569\ub2c8\ub2e4.\\n\\n\uc7a5\uc810\ub3c4 \ubd84\uba85\ud569\ub2c8\ub2e4. \uc9c0\uae08\uae4c\uc9c0\ub294 \uc5d0\uc774\uc804\ud2b8\uac00 \ucf54\ub4dc\ub9cc \ubcf4\uace0 \ucd94\uce21\ud588\ub2e4\uba74, \uc774\uc81c\ub294 \uc2e4\ud589 \uacb0\uacfc(\ub85c\uadf8, \uc2a4\ud06c\ub9b0\uc0f7, \ud2b8\ub808\uc774\uc2a4)\ub97c \uadfc\uac70\ub85c \ub2e4\uc74c \ud328\uce58\ub97c \uc81c\uc548\ud558\ub294 \ub8e8\ud504\ub97c \ub9cc\ub4e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4. UI \ud68c\uadc0\ub098 \ub2e8\ub9d0\ubcc4 \ub80c\ub354\ub9c1 \ucc28\uc774\ub97c \uc7a1\ub294 \ub370 \ud2b9\ud788 \ub3c4\uc6c0\uc774 \ub420 \ub9cc\ud569\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c \uc774\ub807\uac8c \uc368\ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uc800\ub294 \uac70\ucc3d\ud558\uac8c \uc2dc\uc791\ud558\uae30\ubcf4\ub2e4, \uc2a4\ud0ac \ud55c \uac1c + \ub2e8\ub9d0 \ud55c \ub300\ub85c \uc791\uc740 \uc2e4\ud5d8\ubd80\ud130 \ud574\ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4.\\n\\n```bash\\n# 1) \uc9c0\uae08 \ud504\ub85c\uc81d\ud2b8\uc5d0 \ud14c\uc2a4\ud2b8 \uc804\ub7b5 \uc2a4\ud0ac\uc744 \ubd99\uc5ec \ud604\uc7ac \ud14c\uc2a4\ud2b8 \uad6c\uc131\uc744 \uc810\uac80\\nandroid skills add testing-strategy --project=.\\n\\n# 2) \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \uc694\uccad\ud558\ub294 \ud504\ub86c\ud504\ud2b8 \uc608\uc2dc\\n# \\"\uc774 \ubaa8\ub4c8\uc758 Compose UI \ud14c\uc2a4\ud2b8\uac00 \ube44\uc5b4 \uc788\ub294 \ud654\uba74\uc744 \ucc3e\uc544\uc11c,\\n#  Device Streaming \ub2e8\ub9d0\uc5d0\uc11c \uc2a4\ud06c\ub9b0\uc0f7\uae4c\uc9c0 \ud655\uc778\ud55c \ub4a4 \uacb0\uacfc\ub97c \ubcf4\uace0\ud574\uc918\\"\\n```\\n\\n\uc2a4\ud06c\ub9b0\uc0f7 \ud14c\uc2a4\ud2b8\uac00 \uc57d\ud55c \ud654\uba74\ubd80\ud130 \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \ub9e1\uaca8\ubcf4\uba74, \uc0ac\ub78c\uc774 \ub193\uce5c \ub808\uc774\uc544\uc6c3 \uae68\uc9d0\uc744 \uc5bc\ub9c8\ub098 \uc7a1\uc544\ub0b4\ub294\uc9c0, \ubc18\ub300\ub85c \uc624\ud0d0\uc774 \uc5bc\ub9c8\ub098 \ub098\uc624\ub294\uc9c0 \uae08\ubc29 \uac10\uc774 \uc635\ub2c8\ub2e4. \uadf8 \ub2e4\uc74c\uc5d0 R8 \uac10\uc0ac\ub098 CameraX \uc774\uc804\ucc98\ub7fc \ubc94\uc704\uac00 \ub113\uc740 \uc2a4\ud0ac\ub85c \ud655\uc7a5\ud574\ub3c4 \ub2a6\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc774\ubc88 \uc5c5\ub370\uc774\ud2b8\uc758 \ubc29\ud5a5\uc740 \u201c\uc5d0\uc774\uc804\ud2b8\uac00 \ucf54\ub4dc\ub97c \ub354 \uc798 \uc4f0\ub294 \uac83\u201d\uc5d0\uc11c \u201c\uc5d0\uc774\uc804\ud2b8\uac00 \uc2e4\ud589 \uacb0\uacfc\uae4c\uc9c0 \ud655\uc778\ud558\uba70 \uc77c\ud558\ub294 \uac83\u201d\uc73c\ub85c \ud55c \ubc1c \ub098\uac04 \ub290\ub08c\uc785\ub2c8\ub2e4. Android \uac1c\ubc1c\uc790\ub77c\uba74 CLI\uc640 skills\ub97c \ud55c \ubc88\ucbe4 \uc9c1\uc811 \ub9cc\uc838\ubcf4\uba74\uc11c, \ub0b4 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \uc790\ub3d9\uc73c\ub85c \ud655\uc778\ud560 \uc218 \uc788\ub294 \uc77c\uc774 \ubb34\uc5c7\uc778\uc9c0 \ubaa9\ub85d\uc744 \ub9cc\ub4e4\uc5b4\ubcf4\ub294 \uac83\ub9cc\uc73c\ub85c\ub3c4 \uac00\uce58\uac00 \uc788\uc744 \uac83 \uac19\uc2b5\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [Device Streaming and Android skills - available in Android CLI \u2014 Android Developers Blog](https://android-developers.googleblog.com/2026/10/android-cli-device-streaming-and-skills.html)"},{"id":"intellij-lsp-rc","metadata":{"permalink":"/blog/posts/intellij-lsp-rc","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-09-intellij-lsp-rc/index.mdx","source":"@site/blog/2026-10-09-intellij-lsp-rc/index.mdx","title":"IntelliJ\uc758 Kotlin \uc778\ud154\ub9ac\uc804\uc2a4\uac00 VS Code\ub85c \uc654\ub2e4 \u2014 Java and Kotlin \ud655\uc7a5 RC \uacf5\uac1c","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-09T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"kotlin","permalink":"/blog/posts/tags/kotlin"},{"inline":true,"label":"tooling","permalink":"/blog/posts/tags/tooling"},{"inline":true,"label":"intellij","permalink":"/blog/posts/tags/intellij"},{"inline":true,"label":"lsp","permalink":"/blog/posts/tags/lsp"}],"readingTime":2.96,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"intellij-lsp-rc","title":"IntelliJ\uc758 Kotlin \uc778\ud154\ub9ac\uc804\uc2a4\uac00 VS Code\ub85c \uc654\ub2e4 \u2014 Java and Kotlin \ud655\uc7a5 RC \uacf5\uac1c","authors":["way"],"tags":["android","kotlin","tooling","intellij","lsp"]},"unlisted":false,"prevItem":{"title":"Android CLI\uc5d0 \uc2e4\uae30\uae30 \uc2a4\ud2b8\ub9ac\ubc0d\uc774 \ubd99\uc5c8\ub2e4 \u2014 \uc5d0\uc774\uc804\ud2b8\uac00 \uc6d0\uaca9 \ub2e8\ub9d0\uc5d0\uc11c \uc9c1\uc811 \ud655\uc778\ud558\ub294 \ud750\ub984","permalink":"/blog/posts/android-cli-device-streaming"},"nextItem":{"title":"Compose 1.13.0-beta01 \uc815\ub9ac \u2014 Dp.Unspecified\uac00 \ub9ac\ucef4\ud3ec\uc9c0\uc158\uc744 \ub9c9\ub358 \ubc84\uadf8 \uc218\uc815","permalink":"/blog/posts/compose-113-beta01"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 6\uc77c, JetBrains\uac00 `Java and Kotlin by IntelliJ IDEA` \ud655\uc7a5\uc758 Release Candidate\ub97c \uacf5\uac1c\ud588\uc2b5\ub2c8\ub2e4. \ud504\ub9ac\ubdf0\ub97c \uc2dc\uc791\ud55c \uc9c0 \uc57d \ub450 \ub2ec \ub9cc\uc774\uace0, \uc815\uc2dd 1.0\uc774 \uc784\ubc15\ud588\ub2e4\ub294 \uc2e0\ud638\uc785\ub2c8\ub2e4.\\n\\n### \ud575\uc2ec \uc694\uc57d\\n\\n- IntelliJ IDEA\uac00 \uac00\uc9c4 Java/Kotlin \ucf54\ub4dc \uc774\ud574 \ub2a5\ub825\uc744 LSP(Language Server Protocol) \uc11c\ubc84 \ud615\ud0dc\ub85c \ubf51\uc544\ub0b4, VS Code\uc640 Cursor \uac19\uc740 \uc678\ubd80 \uc5d0\ub514\ud130\uc5d0\uc11c \uc4f8 \uc218 \uc788\uac8c \ud55c \ud655\uc7a5\uc785\ub2c8\ub2e4.\\n- \uc774\ubc88 RC\ub294 \ub9c8\uc9c0\ub9c9 EAP \ube4c\ub4dc\uc785\ub2c8\ub2e4. \uc774\ud6c4 \uc815\uc2dd \ubc84\uc804\uc774 \ub098\uc624\uba74 \uc2e0\uaddc \uc0ac\uc6a9\uc790\ub294 30\uc77c \uccb4\ud5d8 \ud6c4 IntelliJ IDEA Ultimate \uad6c\ub3c5\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n- \ub9c8\ucf13\ud50c\ub808\uc774\uc2a4 \ub204\uc801 \ub2e4\uc6b4\ub85c\ub4dc\ub294 2\ub9cc \uac74\uc744 \ub118\uacbc\uace0, JetBrains \ub0b4\ubd80\uc5d0\uc11c\ub3c4 IntelliJ \uae30\ubc18 IDE\ub97c \ub9cc\ub4dc\ub294 \ub300\ud615 \uc800\uc7a5\uc18c\uc5d0 \uc9c1\uc811 \uc801\uc6a9\ud574 \uac80\uc99d\ud588\ub2e4\uace0 \ud569\ub2c8\ub2e4.\\n\\n### \ubb34\uc5c7\uc774 \ub2ec\ub77c\uc84c\ub294\uc9c0\\n\\n\ud504\ub9ac\ubdf0 \ub2e8\uacc4\uc5d0\uc11c\ub294 \uc644\uc131\ub3c4\uc640 \uc548\uc815\uc131\uc744 \ub2e4\ub4ec\ub294 \uc5c5\ub370\uc774\ud2b8\uac00 \uc774\uc5b4\uc84c\uace0, RC\uc5d0\uc11c\ub294 \u201c\uc5d0\ub514\ud130 \ubc16 \uc6cc\ud06c\ud50c\ub85c\uae4c\uc9c0 IntelliJ\uc758 \uc774\ud574\ub3c4\ub97c \uac00\uc838\uac04\ub2e4\u201d\ub294 \ubc29\ud5a5\uc774 \ub354 \ub610\ub837\ud574\uc84c\uc2b5\ub2c8\ub2e4.\\n\\n\uc81c \uae30\uc900\uc73c\ub85c \uc2e4\ubb34\uc5d0 \ub2ff\ub294 \ubd80\ubd84\ub9cc \ucd94\ub9ac\uba74 \uc774\ub807\uc2b5\ub2c8\ub2e4.\\n\\n- **\ud575\uc2ec \ucf54\ub529 \uc9c0\uc6d0**: \uc2a4\ub9c8\ud2b8 \uc790\ub3d9\uc644\uc131, \ucf54\ub4dc \ub0b4\ube44\uac8c\uc774\uc158, \uc778\uc2a4\ud399\uc158, \ud035\ud53d\uc2a4, \uc815\uc801 \ubd84\uc11d \uac19\uc740 \uae30\ubcf8\uae30\uac00 LSP\ub97c \ud1b5\ud574 \uc81c\uacf5\ub429\ub2c8\ub2e4.\\n- **\ud55c \ub2e8\uacc4 \uc704 \uae30\ub2a5**: \ud504\ub85c\uc81d\ud2b8 \uc804\uc5ed \ub9ac\ud329\ud130\ub9c1, DAP \uae30\ubc18 \ub514\ubc84\uae45, Maven/Gradle/Bazel \ud504\ub85c\uc81d\ud2b8 \ubaa8\ub378 \uc774\ud574, \ub0b4\uc7a5 \ud14c\uc2a4\ud2b8 \ub7ec\ub108, Spring \ub3c4\uad6c \uc5f0\ub3d9\uae4c\uc9c0 \ud3ec\ud568\ub429\ub2c8\ub2e4.\\n- **\uc5d0\uc774\uc804\ud2b8 \uc5f0\ub3d9**: Cursor\uc5d0 \uc124\uce58\ud558\uba74 Cursor Agent\uac00 \uac19\uc740 \uc5b8\uc5b4 \uc11c\ubc84\ub97c \ud65c\uc6a9\ud574 \uc758\ubbf8 \uae30\ubc18 \uac80\uc0c9, \uc774\ub3d9, \ubd84\uc11d\uc744 \uc218\ud589\ud569\ub2c8\ub2e4. \ud14d\uc2a4\ud2b8 \uac80\uc0c9\ub9cc\uc73c\ub85c \ucf54\ub4dc\ub97c \ub4a4\uc9c0\ub294 \uac83\ubcf4\ub2e4 \ube60\ub974\uace0 \uacb0\uc815\uc801\uc778 \uacb0\uacfc\ub97c \uae30\ub300\ud560 \uc218 \uc788\ub294 \uad6c\uc870\uc785\ub2c8\ub2e4.\\n\\n\uc6d0\ubb38\uc5d0\uc11c \uac15\uc870\ud558\ub294 \uac83\ub3c4 \uacb0\uad6d \u201c\ub2e4\ub978 \uc5d0\ub514\ud130\uc5d0 IntelliJ \uae30\ub2a5\uc744 \ubcf5\uc81c\u201d\ud558\ub294 \uac8c \uc544\ub2c8\ub77c, \uac1c\ubc1c\uc790\uc640 \ub3c4\uad6c\uac00 \uc5b4\ub514\uc11c \uc77c\ud558\ub4e0 JVM \ucf54\ub4dc \uc774\ud574\ub3c4\ub97c \uc7ac\uc0ac\uc6a9\ud558\uac8c \ub9cc\ub4dc\ub294 \ucabd\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4.\\n\\n### \uc2e4\ubb34 \uc601\ud5a5 / \uc8fc\uc758\uc810\\n\\nAndroid \uac1c\ubc1c\uc790 \uc785\uc7a5\uc5d0\uc11c \uc774 \ud655\uc7a5\uc774 \ub2f9\uc7a5 Android Studio\ub97c \ub300\uccb4\ud558\uc9c4 \uc54a\uc2b5\ub2c8\ub2e4. \uc5d0\ubbac\ub808\uc774\ud130, \ud504\ub85c\ud30c\uc77c\ub7ec, Compose \ud504\ub9ac\ubdf0, AGP \ud2b9\ud654 \ub3c4\uad6c\ucc98\ub7fc Android Studio \uc548\uc5d0 \uae4a\uac8c \ubd99\uc740 \uae30\ub2a5\uc740 \uc5ec\uc804\ud788 Studio \ucabd\uc774 \ubcf8\uc9c4\uc785\ub2c8\ub2e4.\\n\\n\ub300\uc2e0 \uc774\ub7f0 \uc0c1\ud669\uc5d0\uc11c \uaf64 \uc720\uc6a9\ud569\ub2c8\ub2e4.\\n\\n- \ud3c9\uc18c Cursor\ub098 VS Code\ub85c AI \uc5d0\uc774\uc804\ud2b8\uc640 \ud568\uaed8 \ucf54\ub4dc\ub97c \ub9cc\uc9c0\ub294\ub370, Kotlin/Java \uc774\ud574\ub3c4\uac00 \uc544\uc26c\uc6e0\ub358 \uacbd\uc6b0\\n- \uba40\ud2f0\ubaa8\ub4c8 Gradle \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c \u201c\uc815\uc758\ub85c \uc774\ub3d9\u201d\uc774\ub098 \u201c\uc0ac\uc6a9\ucc98 \ucc3e\uae30\u201d\uac00 \ubd80\uc815\ud655\ud574 \uc5d0\uc774\uc804\ud2b8\uac00 \uc5c9\ub6b1\ud55c \ud30c\uc77c\uc744 \uace0\uce58\ub294 \uc77c\uc774 \uc7a6\uc558\ub358 \uacbd\uc6b0\\n- \ubc31\uc5d4\ub4dc(Spring) + Android\ub97c \uc624\uac00\uba70 \ud55c \uc5d0\ub514\ud130\uc5d0\uc11c \uc791\uc5c5\ud558\uace0 \uc2f6\uc740 \uacbd\uc6b0\\n\\n\ub2e4\ub9cc \ub77c\uc774\uc120\uc2a4\ub294 \ubbf8\ub9ac \ubd10\ub450\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4. RC\ub294 EAP \uc870\uac74\uc73c\ub85c 30\uc77c\uac04 \ub77c\uc774\uc120\uc2a4 \uc5c6\uc774 \uc4f8 \uc218 \uc788\uace0, \uc815\uc2dd \uc774\ud6c4\uc5d0\ub294 \uccb4\ud5d8 \uae30\uac04\uc774 \ub05d\ub098\uba74 Ultimate \uad6c\ub3c5\uc774 \ud544\uc694\ud558\ub2e4\uace0 \uc548\ub0b4\ub3fc \uc788\uc2b5\ub2c8\ub2e4. \ud300\uc5d0\uc11c \uc774\ubbf8 Ultimate\uc744 \uc4f0\uace0 \uc788\ub2e4\uba74 \ucd94\uac00 \ube44\uc6a9\uc774 \uc5c6\uc9c0\ub9cc, \ubb34\ub8cc \uc5d0\ub514\ud130 + \ubb34\ub8cc \ud655\uc7a5 \uc870\ud569\uc73c\ub85c \uc0dd\uac01\ud588\ub2e4\uba74 \uc815\uc2dd \uc774\ud6c4 \uc815\ucc45\uc744 \ud655\uc778\ud574\uc57c \ud569\ub2c8\ub2e4.\\n\\n\ub610 \ud558\ub098, RC\ub294 \uc5b4\ub514\uae4c\uc9c0\ub098 \uc815\uc2dd \uc9c1\uc804 \ub2e8\uacc4\uc785\ub2c8\ub2e4. \uc0ac\ub0b4 \ud575\uc2ec \uc800\uc7a5\uc18c\uc5d0 \ubc14\ub85c \ubd99\uc774\uae30\ubcf4\ub2e4, \uc0ac\uc774\ub4dc \ud504\ub85c\uc81d\ud2b8\ub098 \uc791\uc740 \ubaa8\ub4c8\uc5d0\uc11c \ub9ac\ud329\ud130\ub9c1 \uc815\ud655\ub3c4\uc640 \uc778\ub371\uc2f1 \uc18d\ub3c4\ub97c \uba3c\uc800 \uccb4\uac10\ud574 \ubcf4\ub294 \ucabd\uc774 \uc548\uc804\ud569\ub2c8\ub2e4.\\n\\n### \ub0b4 \ucf54\ub4dc\uc5d0\uc11c \uc774\ub807\uac8c \uc368\ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4\\n\\n\uc800\ub294 Cursor\uc5d0\uc11c \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \ubaa8\ub4c8 \uac04 \uc774\ub3d9\uc774 \ub9ce\uc740 \uc791\uc5c5\uc744 \uc2dc\ud0ac \ub54c\ub97c \ub178\ub824\ubcf4\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc608\ub97c \ub4e4\uc5b4 \ud53c\ucc98 \ubaa8\ub4c8\uc758 \uacf5\uac1c API\ub97c \ubc14\uafb8\ub294 \uc791\uc5c5\uc740, \uc5d0\uc774\uc804\ud2b8\uac00 \ud638\ucd9c\ubd80\ub97c \uc815\ud655\ud788 \ucc3e\uc544\ub0b4\uc9c0 \ubabb\ud558\uba74 \ucef4\ud30c\uc77c\uc774 \uae68\uc9c4 \uc0c1\ud0dc\ub85c \ub0a8\uae30 \uc27d\uc2b5\ub2c8\ub2e4.\\n\\n```text\\n1) VS Code / Cursor\uc5d0 Java and Kotlin by IntelliJ IDEA (RC) \uc124\uce58\\n2) \ud55c\ud22c \uc571\uc758 \uc791\uc740 Gradle \ubaa8\ub4c8\ubd80\ud130 \uc5f4\uc5b4 \uc778\ub371\uc2f1\uc774 \ub05d\ub0a0 \ub54c\uae4c\uc9c0 \ub300\uae30\\n3) \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \uc694\uccad: \\"\uc774 \uc778\ud130\ud398\uc774\uc2a4\uc758 \uad6c\ud604\uccb4\uc640 \ud638\ucd9c\ubd80\ub97c \ubaa8\ub450 \ucc3e\uc544\uc11c \uc2dc\uadf8\ub2c8\ucc98 \ubcc0\uacbd \uc601\ud5a5 \ubc94\uc704\ub97c \uba3c\uc800 \ubcf4\uace0\ud574\uc918\\"\\n4) \uacb0\uacfc\ub97c Android Studio\uc758 Find Usages\uc640 \ub300\uc870\ud574 \uc815\ud655\ub3c4 \ud655\uc778\\n```\\n\\n\uc774 \ub300\uc870\ub97c \uba87 \ubc88 \ud574\ubcf4\uba74, \uc5d0\uc774\uc804\ud2b8\uc5d0\uac8c \ub9ac\ud329\ud130\ub9c1\uc744 \uc5b4\ub514\uae4c\uc9c0 \ub9e1\uae38 \uc218 \uc788\ub294\uc9c0 \uac10\uc774 \uc7a1\ud799\ub2c8\ub2e4. \uc5b8\uc5b4 \uc11c\ubc84\uac00 \ud504\ub85c\uc81d\ud2b8 \ubaa8\ub378\uc744 \uc81c\ub300\ub85c \uc950\uace0 \uc788\uc73c\uba74, \uc5d0\uc774\uc804\ud2b8\uc758 \uccab \ud328\uce58\uac00 \ud6e8\uc52c \ub35c \ud5e4\ub9f5\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\nKotlin Toolchain\uc774 CLI \ucabd\uc5d0\uc11c \ud504\ub85c\uc81d\ud2b8 \uc2dc\uc791 \uacbd\ud5d8\uc744 \ub2e4\ub4ec\uace0 \uc788\ub2e4\uba74, \uc774 \ud655\uc7a5\uc740 \uc5d0\ub514\ud130 \ucabd\uc5d0\uc11c \u201cIntelliJ\uc758 \ub1cc\u201d\ub97c \ubc16\uc73c\ub85c \uaebc\ub0b4\ub294 \uc2dc\ub3c4\uc785\ub2c8\ub2e4. Android Studio\uac00 \ubcf8\uc9c4\uc778 \uac74 \ubcc0\ud558\uc9c0 \uc54a\uc9c0\ub9cc, AI \uc5d0\uc774\uc804\ud2b8\uc640 \ud568\uaed8 \uc77c\ud558\ub294 \ube44\uc911\uc774 \ub298\uc5b4\ub0a0\uc218\ub85d \uc815\ud655\ud55c \uc5b8\uc5b4 \uc11c\ubc84\uc758 \uac00\uce58\ub294 \ub354 \ucee4\uc9c8 \uac70\ub77c\uace0 \ubd05\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [Java and Kotlin by IntelliJ IDEA: The LSP-Based Extension Reaches Release Candidate \u2014 The JetBrains Blog](https://blog.jetbrains.com/idea/2026/10/java-and-kotlin-by-intellij-idea-the-lsp-based-extension-reaches-release-candidate/)"},{"id":"compose-113-beta01","metadata":{"permalink":"/blog/posts/compose-113-beta01","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-08-compose-113-beta01/index.mdx","source":"@site/blog/2026-10-08-compose-113-beta01/index.mdx","title":"Compose 1.13.0-beta01 \uc815\ub9ac \u2014 Dp.Unspecified\uac00 \ub9ac\ucef4\ud3ec\uc9c0\uc158\uc744 \ub9c9\ub358 \ubc84\uadf8 \uc218\uc815","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-08T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"compose","permalink":"/blog/posts/tags/compose"},{"inline":true,"label":"androidx","permalink":"/blog/posts/tags/androidx"},{"inline":true,"label":"jetpack-compose","permalink":"/blog/posts/tags/jetpack-compose"}],"readingTime":1.67,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"compose-113-beta01","title":"Compose 1.13.0-beta01 \uc815\ub9ac \u2014 Dp.Unspecified\uac00 \ub9ac\ucef4\ud3ec\uc9c0\uc158\uc744 \ub9c9\ub358 \ubc84\uadf8 \uc218\uc815","authors":["way"],"tags":["android","compose","androidx","jetpack-compose"]},"unlisted":false,"prevItem":{"title":"IntelliJ\uc758 Kotlin \uc778\ud154\ub9ac\uc804\uc2a4\uac00 VS Code\ub85c \uc654\ub2e4 \u2014 Java and Kotlin \ud655\uc7a5 RC \uacf5\uac1c","permalink":"/blog/posts/intellij-lsp-rc"},"nextItem":{"title":"Kotlin Toolchain 0.13 \u2014 \uc0c8 KMP \ud504\ub85c\uc81d\ud2b8\ub294 kotlin new\ub85c \uc2dc\uc791\ud558\uae30","permalink":"/blog/posts/kotlin-toolchain-013"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n2026\ub144 10\uc6d4 7\uc77c, Compose 1.13.0-beta01\uc774 \ub9b4\ub9ac\uc2a4\ub410\uc2b5\ub2c8\ub2e4. stable \ucc44\ub110\uc758 \ucd5c\uc2e0\uc740 1.12.1\uc785\ub2c8\ub2e4.<br/>\\nruntime \uae30\uc900\uc73c\ub85c \uc2e4\ubb34\uc5d0 \ub2ff\ub294 \ubcc0\uacbd\ub9cc \ucd94\ub824\uc11c \uc815\ub9ac\ud569\ub2c8\ub2e4.\\n\\n### Kotlin 2.2 \ud0c0\uae43\uc73c\ub85c \uc0c1\ud5a5\\n\\n1.13\ubd80\ud130 Compose \ub77c\uc774\ube0c\ub7ec\ub9ac\ub294 Kotlin 2.2\ub97c \ud0c0\uae43\uc73c\ub85c \ube4c\ub4dc\ub418\uace0, kotlinc 2.2\uac00 \ud544\uc694\ud569\ub2c8\ub2e4.<br/>\\n\ubc84\uc804 \uce74\ud0c8\ub85c\uadf8\uc5d0\uc11c Compose BOM\ub9cc \uc62c\ub9ac\ub294 \uc2b5\uad00\uc774 \uc788\ub2e4\uba74, Kotlin \ud50c\ub7ec\uadf8\uc778 \ubc84\uc804\uc774 \ub4a4\ucc98\uc9c4 \ubaa8\ub4c8\uc5d0\uc11c \uba3c\uc800 \uac78\ub9b4 \uc218 \uc788\uc73c\ub2c8 \ud568\uaed8 \ud655\uc778\ud558\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.\\n\\n### Dp.Unspecified\ub97c \ubc1b\ub294 \ucef4\ud3ec\uc800\ube14\uc774 \uc2a4\ud0b5\ub418\uc9c0 \uc54a\ub358 \ubc84\uadf8\\n\\n\uac1c\uc778\uc801\uc73c\ub85c \uc774\ubc88 \ubca0\ud0c0\uc5d0\uc11c \uac00\uc7a5 \ubc18\uac00\uc6b4 \uc218\uc815\uc785\ub2c8\ub2e4.<br/>\\n`Float.NaN`\uc774\ub098 `Double.NaN`\uc744 \uc778\uc790\ub85c \ubc1b\ub294 `@Composable`\uc740 \uc778\uc790\uac00 \uadf8\ub300\ub85c\uc5ec\ub3c4 \uc2a4\ud0b5\ub418\uc9c0 \uc54a\uace0 \ub9e4\ubc88 \ub9ac\ucef4\ud3ec\uc9c0\uc158\ub418\ub294 \ubc84\uadf8\uac00 \uc788\uc5c8\uc2b5\ub2c8\ub2e4. `Dp.Unspecified`\uac00 \ub0b4\ubd80\uc801\uc73c\ub85c `Float.NaN` \uae30\ubc18\uc774\ub77c, \uc120\ud0dd\uc801 \uac04\uaca9\uc774\ub098 \ud06c\uae30\ub97c `Dp.Unspecified` \uae30\ubcf8\uac12\uc73c\ub85c \ubc1b\ub294 \uacf5\uc6a9 \ucef4\ud3ec\ub10c\ud2b8\uac00 \uc870\uc6a9\ud788 \ub9ac\ucef4\ud3ec\uc9c0\uc158 \ube44\uc6a9\uc744 \uce58\ub974\uace0 \uc788\uc5c8\ub358 \uc148\uc785\ub2c8\ub2e4.\\n\\n```kotlin\\n// \uc774\ub7f0 \uacf5\uc6a9 \ucef4\ud3ec\ub10c\ud2b8\uac00 \uc778\uc790 \ubcc0\ud654\uac00 \uc5c6\uc5b4\ub3c4 \uc2a4\ud0b5\ub418\uc9c0 \uc54a\uc744 \uc218 \uc788\uc5c8\ub2e4\\n@Composable\\nfun PriceRow(\\n    label: String,\\n    topPadding: Dp = Dp.Unspecified\\n) { /* ... */ }\\n```\\n\\n\uc0ac\ub0b4 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c\ucc98\ub7fc \uacf5\uc6a9 \ucef4\ud3ec\ub10c\ud2b8\uc5d0 `Dp.Unspecified` \uae30\ubcf8\uac12\uc774 \ud754\ud55c \ucf54\ub4dc\ubca0\uc774\uc2a4\ub77c\uba74, 1.13 stable\uc774 \ub098\uc62c \ub54c \uccb4\uac10 \uc131\ub2a5\uc774 \uc88b\uc544\uc9c8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### computedStateOf \uacc4\uc0b0 \ube14\ub85d\uc740 \uc77d\uae30 \uc804\uc6a9\uc73c\ub85c \uac15\uc81c\\n\\n`computedStateOf`\uc758 \uacc4\uc0b0 \ube14\ub85d \uc548\uc5d0\uc11c \uc0c1\ud0dc\uc5d0 \uc4f0\uba74 \uc774\uc81c `IllegalStateException`\uc774 \ubc1c\uc0dd\ud569\ub2c8\ub2e4.<br/>\\n\uae30\uc874\uc5d0 \uacc4\uc0b0 \ube14\ub85d \uc548\uc5d0\uc11c \uc4f0\uae30\uae4c\uc9c0 \ud558\ub358 \ucf54\ub4dc\uac00 \uc788\uc5c8\ub2e4\uba74 \ub7f0\ud0c0\uc784\uc5d0\uc11c \ubc14\ub85c \ub4dc\ub7ec\ub098\ub2c8, \ubca0\ud0c0\ub97c \uc62c\ub9ac\ub294 \ubaa8\ub4c8\ubd80\ud130 \ud655\uc778\uc774 \ud544\uc694\ud569\ub2c8\ub2e4.\\n\\n### \uadf8 \uc678 \ubc84\uadf8 \ud53d\uc2a4\\n\\n- `CompositionObserver`\uac00 \ucef4\ud3ec\uc9c0\uc158 \ud328\uc2a4\ub9c8\ub2e4 \ud55c \ubc88\ub9cc \ud574\uc11d\ub418\uace0, \uad50\uccb4\ub294 \ub2e4\uc74c \ud328\uc2a4\ubd80\ud130 \uc801\uc6a9\ub429\ub2c8\ub2e4. movable content \uc0bd\uc785 \uc2dc\uc5d0\ub3c4 begin/end \ucf5c\ubc31\uc774 \ubcf4\uace0\ub429\ub2c8\ub2e4.\\n- `movableContent` \uc774\ub3d9 \uc2dc \ub798\ud37c \uadf8\ub8f9 \uc2ac\ub86f\uc774 \ub0a8\uc544 \uc788\ub358 LinkComposer \uba54\ubaa8\ub9ac \ub204\uc218\ub97c \uace0\ucce4\uc2b5\ub2c8\ub2e4.\\n- `lifecycle-runtime` \uc758\uc874\uc131\uc774 2.10.0\uc73c\ub85c \uc62c\ub77c\uac14\uc2b5\ub2c8\ub2e4. \ubc88\ub4e4\ub41c lifecycle lint \uac80\uc0ac\ub294 AGP 9.5.0-alpha04 \uc774\uc0c1\uacfc \ub9de\ubb3c\ub824 \uc788\uc73c\ub2c8, AGP \ubca0\ud0c0 \ucc44\ub110\uc744 \uc4f0\ub294 \ud504\ub85c\uc81d\ud2b8\ub294 \uac19\uc774 \ubcf4\ub294 \uac8c \uc88b\uc2b5\ub2c8\ub2e4.\\n- `ComposeTracer`\ub97c \uba54\uc778 \uc2a4\ub808\ub4dc \ubc16\uc5d0\uc11c\ub3c4 \uc4f8 \uc218 \uc788\uac8c \ub410\uc2b5\ub2c8\ub2e4.\\n\\n### \uc62c\ub9b4\uae4c \ub9d0\uae4c\\n\\n1.12.1 stable\uc740 1.12.0\uc5d0\uc11c \ubcc0\uacbd\uc774 \uc5c6\ub294 \ubc84\uc804\uc774\ub77c, \uc6b4\uc601 \uc571\uc740 stable \uc720\uc9c0\uac00 \ubb34\ub09c\ud569\ub2c8\ub2e4.<br/>\\n\ubca0\ud0c0\ub294 \uc131\ub2a5 \uac80\uc99d\uc774 \ud544\uc694\ud55c \ud654\uba74(\uacf5\uc6a9 \ucef4\ud3ec\ub10c\ud2b8\ub97c \ub9ce\uc774 \uc4f0\ub294 MTS \ud2b9\uc131\uc0c1 \ub9ac\ucef4\ud3ec\uc9c0\uc158 \uc774\uc288\uac00 \uccb4\uac10\ub418\ub294 \uacf3) \uc704\uc8fc\ub85c \uba3c\uc800 \uc62c\ub824 \ubcf4\uace0, \uc571 \uc804\uccb4 \ud655\ub300\ub294 stable \uc774\ud6c4\uac00 \uc548\uc804\ud574 \ubcf4\uc785\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [Compose Runtime release notes \u2014 Android Developers](https://developer.android.com/jetpack/androidx/releases/compose-runtime)"},{"id":"kotlin-toolchain-013","metadata":{"permalink":"/blog/posts/kotlin-toolchain-013","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-10-08-kotlin-toolchain-013/index.mdx","source":"@site/blog/2026-10-08-kotlin-toolchain-013/index.mdx","title":"Kotlin Toolchain 0.13 \u2014 \uc0c8 KMP \ud504\ub85c\uc81d\ud2b8\ub294 kotlin new\ub85c \uc2dc\uc791\ud558\uae30","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2026-10-08T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"kotlin","permalink":"/blog/posts/tags/kotlin"},{"inline":true,"label":"kmp","permalink":"/blog/posts/tags/kmp"},{"inline":true,"label":"kotlin-toolchain","permalink":"/blog/posts/tags/kotlin-toolchain"}],"readingTime":2.52,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"kotlin-toolchain-013","title":"Kotlin Toolchain 0.13 \u2014 \uc0c8 KMP \ud504\ub85c\uc81d\ud2b8\ub294 kotlin new\ub85c \uc2dc\uc791\ud558\uae30","authors":["way"],"tags":["android","kotlin","kmp","kotlin-toolchain"]},"unlisted":false,"prevItem":{"title":"Compose 1.13.0-beta01 \uc815\ub9ac \u2014 Dp.Unspecified\uac00 \ub9ac\ucef4\ud3ec\uc9c0\uc158\uc744 \ub9c9\ub358 \ubc84\uadf8 \uc218\uc815","permalink":"/blog/posts/compose-113-beta01"},"nextItem":{"title":"\uad6d\ub0b4 MTS\uc5d0 Gradle Convention Plugin \ub3c4\uc785\ud558\uae30","permalink":"/blog/posts/mts-gradle-convention-plugin"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\nJetBrains\uac00 Kotlin Toolchain 0.13\uc744 \uacf5\uac1c\ud558\uba74\uc11c, \uc2e0\uaddc Kotlin Multiplatform(KMP) \ud504\ub85c\uc81d\ud2b8\uc758 \ucd9c\ubc1c\uc810\uc73c\ub85c \uc774 \ud234\uccb4\uc778\uc744 \uacf5\uc2dd \ucd94\ucc9c\ud558\uae30 \uc2dc\uc791\ud588\uc2b5\ub2c8\ub2e4.<br/>\\nGradle \uc124\uc815 \ud30c\uc77c\uc744 \uc190\uc73c\ub85c \uc9dc\ub294 \ub300\uc2e0 `kotlin` CLI \ud558\ub098\ub85c \ud658\uacbd\uc744 \ub9de\ucd94\ub294 \ubc29\uc2dd\uc774 \uc5b4\ub5a4 \ubaa8\uc2b5\uc778\uc9c0 \uc815\ub9ac\ud574 \ubcf4\uaca0\uc2b5\ub2c8\ub2e4.\\n\\n### Kotlin Toolchain\uc774 \ubb54\uac00\uc694\\n\\nKotlin Toolchain\uc740 JVM\xb7Android\xb7iOS\xb7\uba40\ud2f0\ud50c\ub7ab\ud3fc\xb7\uc11c\ubc84 \uc571\uc744 \ud558\ub098\uc758 CLI \uc9c4\uc785\uc810\uc73c\ub85c \ub9cc\ub4e4\uace0, \ube4c\ub4dc\ud558\uace0, \ud14c\uc2a4\ud2b8\ud558\uace0, \ubc30\ud3ec\ud558\ub294 \ub3c4\uad6c\uc785\ub2c8\ub2e4.<br/>\\nJDK\ub098 Android SDK \uac19\uc740 \ud544\uc218 \ub3c4\uad6c\ub4e4\uc744 \uc120\uc5b8\uc801 \uc124\uc815\uc5d0 \ub9de\ucdb0 \uc790\ub3d9\uc73c\ub85c \ub0b4\ub824\ubc1b\uc544 \uc8fc\uae30 \ub54c\ubb38\uc5d0, \\"\uc0c8 \ub178\ud2b8\ubd81\uc5d0\uc11c KMP \ud504\ub85c\uc81d\ud2b8 \ucc98\uc74c \uc5f4\uc5c8\ub354\ub2c8 SDK\uac00 \uc5c6\uc5b4\uc11c \ub3d9\uae30\ud654 \uc2e4\ud328\\" \uac19\uc740 \uc628\ubcf4\ub529 \ub9c8\ucc30\uc774 \ud06c\uac8c \uc904\uc5b4\ub4ed\ub2c8\ub2e4.<br/>\\n\uc774\ubc88 0.13\ubd80\ud130\ub294 \uc2e0\uaddc KMP \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc774 \ud234\uccb4\uc778\uc744 \uc4f0\ub294 \uac83\uc774 JetBrains\uc758 \uad8c\uc7a5 \uacbd\ub85c\uac00 \ub410\uc2b5\ub2c8\ub2e4.\\n\\n### kotlin new: \ub300\ud654\ud615 \ud504\ub85c\uc81d\ud2b8 \uc0dd\uc131\\n\\n0.13\uc758 \ud575\uc2ec\uc740 `kotlin new` \uba85\ub839\uc785\ub2c8\ub2e4. \uc6f9\uc758 KMP Wizard\ucc98\ub7fc \uc571 \uc720\ud615\uc744 \uace0\ub974\uace0 \ud0c0\uae43 \ud50c\ub7ab\ud3fc\uc744 \uc120\ud0dd\ud558\uba74 \ud504\ub85c\uc81d\ud2b8\uac00 \uc0dd\uc131\ub429\ub2c8\ub2e4.<br/>\\n\uae30\uc874 `kotlin init`\ub3c4 \uac19\uc740 \ud750\ub984\uc73c\ub85c \ub9de\ucdc4\ub294\ub370, \ucc28\uc774\ub294 `kotlin init`\uc774 \ud604\uc7ac \ub514\ub809\ud130\ub9ac\uc5d0 \ubc14\ub85c \ud30c\uc77c\uc744 \ub9cc\ub4e0\ub2e4\ub294 \uc810\uc785\ub2c8\ub2e4.\\n\\n```bash\\n# \uc0c8 \ud504\ub85c\uc81d\ud2b8 \uc0dd\uc131 (\ub300\ud654\ud615)\\nkotlin new\\n\\n# \uc774\ubbf8 \uc124\uce58\ub3fc \uc788\ub2e4\uba74 \uc5c5\ub370\uc774\ud2b8\\nkotlin update\\n```\\n\\n### Android \uac1c\ubc1c\uc790 \uad00\uc810\uc5d0\uc11c \ubc18\uac00\uc6b4 \ubd80\ubd84\\n\\n- **Android SDK \uc790\ub3d9 \ud504\ub85c\ube44\uc800\ub2dd\uc774 IDE\uae4c\uc9c0 \ud655\uc7a5**: \uc774\uc804\uc5d0\ub294 `kotlin build`/`kotlin run` \ub54c\ub9cc SDK\uac00 \uc790\ub3d9 \uc124\uce58\ub3fc\uc11c, \ube4c\ub4dc \uc804\uc5d0 IDE\ub85c \uba3c\uc800 \uc5f4\uba74 SDK \ub204\ub77d \uc624\ub958\uac00 \ub0ac\uc2b5\ub2c8\ub2e4. \uc774\uc81c \ud504\ub85c\uc81d\ud2b8 import \uc2dc\uc810\uc5d0\ub3c4 \ub204\ub77d\ub41c SDK \ucef4\ud3ec\ub10c\ud2b8\ub97c \uc790\ub3d9\uc73c\ub85c \ubc1b\uc544 \uc90d\ub2c8\ub2e4.\\n- **namespace/applicationId \uac80\uc99d \uac15\ud654**: `com.example.app` \uac19\uc740 \uc0d8\ud50c ID\ub85c \uc2e4\uc218\ub85c \ubc30\ud3ec \ube4c\ub4dc\ub97c \ub9cc\ub4dc\ub294 \uc2e4\uc218\ub97c \ub9c9\uc544 \uc90d\ub2c8\ub2e4.\\n- **\ub2e4\uc6b4\ub85c\ub4dc \uc9c4\ud589 \ud45c\uc2dc**: JDK, Android SDK, iOS \ub7f0\ud0c0\uc784, \ucef4\ud30c\uc77c\ub7ec \ub2e4\uc6b4\ub85c\ub4dc\uac00 CLI\uc5d0 \uc9c4\ud589 \ubc14\ub85c \ud45c\uc2dc\ub429\ub2c8\ub2e4.\\n\\n### Swift Package Manager \uc758\uc874\uc131 \uc9c0\uc6d0\\n\\nApple \ud0c0\uae43\uc5d0\uc11c SPM \ud328\ud0a4\uc9c0\ub97c \uc120\uc5b8\uc801\uc73c\ub85c \uac00\uc838\uc62c \uc218 \uc788\uac8c \ub410\uc2b5\ub2c8\ub2e4. \uc124\uc815 \ud30c\uc77c\uc5d0 \uc800\uc7a5\uc18c\uc640 \ubc84\uc804\uc744 \uc801\uc73c\uba74 \ub429\ub2c8\ub2e4.\\n\\n```kotlin\\ndependencies:\\n  - swiftPackage:\\n      repository: \\"https://github.com/firebase/firebase-ios-sdk.git\\"\\n      version: \\"12.17.0\\"\\n      products: [\\"FirebaseCore\\", \\"FirebaseFirestore\\", \\"FirebaseAnalytics\\"]\\n```\\n\\n\uac00\uc838\uc628 Objective-C API\ub294 `swiftPMImport` \uc811\ub450\uc0ac\ub85c \ub124\uc784\uc2a4\ud398\uc774\uc2a4\uac00 \ubd99\uc5b4, Kotlin \ucf54\ub4dc\uc5d0\uc11c \uba85\uc2dc\uc801\uc73c\ub85c \uad6c\ubd84\ub429\ub2c8\ub2e4. \ub85c\uceec SPM \ud328\ud0a4\uc9c0\ub294 `localSwiftPackage` \ud0a4\ub85c \uc5f0\uacb0\ud560 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ube4c\ub4dc \uc18d\ub3c4: Kotlin/Native \ucef4\ud30c\uc77c\ub7ec \uce90\uc2dc\\n\\nKotlin/Native \uc7ac\ube4c\ub4dc\uac00 \ube68\ub77c\uc9d1\ub2c8\ub2e4. \ucef4\ud30c\uc77c\ub41c \ub124\uc774\ud2f0\ube0c \uc758\uc874\uc131\uc744 \ube4c\ub4dc \uac04, \uc2ec\uc9c0\uc5b4 \ud504\ub85c\uc81d\ud2b8 \uac04\uc5d0 \uce90\uc2dc\ub85c \uc7ac\uc0ac\uc6a9\ud558\uace0, \ud504\ub85c\uc81d\ud2b8 \ucf54\ub4dc\ub294 \ud30c\uc77c \ub2e8\uc704 \uce90\uc2dc\ub85c \ub9c1\ud06c \uc2dc \ubc14\ub010 \ubd80\ubd84\ub9cc \ub2e4\uc2dc \ucef4\ud30c\uc77c\ud569\ub2c8\ub2e4.<br/>\\n\uae30\uc874 `settings.kotlin.compileIncrementally` \uc124\uc815\uc744 \uadf8\ub300\ub85c \uc4f0\uace0, `.klib` \ucef4\ud30c\uc77c \uc790\uccb4\ub294 \uc804\uccb4\ub85c \uc218\ud589\ub429\ub2c8\ub2e4.\\n\\n### \uadf8 \uc678\\n\\n- **IDE \ub3d9\uae30\ud654 \uc0c1\ud0dc\ub97c \uc5d0\ub514\ud130\uc5d0\uc11c \ud655\uc778**\ud560 \uc218 \uc788\uac8c \ub410\uc2b5\ub2c8\ub2e4.\\n- \uba40\ud2f0\ud50c\ub7ab\ud3fc \ub77c\uc774\ube0c\ub7ec\ub9ac \ubc30\ud3ec \uc2dc Compose Resources\uc640 SwiftPM \uc758\uc874\uc131 \uba54\ud0c0\ub370\uc774\ud130\uac00 \uc544\ud2f0\ud329\ud2b8\uc640 \ud568\uaed8 \uac8c\uc2dc\ub418\uace0, \uc11c\ub4dc\ud30c\ud2f0 \uba40\ud2f0\ud50c\ub7ab\ud3fc \ub77c\uc774\ube0c\ub7ec\ub9ac\uc758 Compose Resources\ub3c4 \ud574\uc11d\ub429\ub2c8\ub2e4.\\n- AI \uc5d0\uc774\uc804\ud2b8 \uc5f0\ub3d9\ub3c4 \uac15\ud654\ub410\uc2b5\ub2c8\ub2e4. Compose Hot Reload MCP \uc11c\ubc84\uc640 Kotlin\uc6a9 \uc5d0\uc774\uc804\ud2b8 \uc2a4\ud0ac(`npx skills add kotlin/kotlin-agent-skills`)\uc774 \uc81c\uacf5\ub429\ub2c8\ub2e4.\\n- IDE \uae30\ub2a5\uc740 IntelliJ IDEA 2026.2.3 \ub610\ub294 Android Studio Rabbit 1(2026.2.1) \uc774\uc0c1\uc5d0\uc11c \ucd5c\uc2e0 Kotlin Toolchain \ud50c\ub7ec\uadf8\uc778\uacfc \ud568\uaed8 \uc4f8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\n\uae30\uc874 Gradle \uae30\ubc18 \ud504\ub85c\uc81d\ud2b8\ub97c \ub2f9\uc7a5 \ub9c8\uc774\uadf8\ub808\uc774\uc158\ud558\ub77c\ub294 \uc598\uae30\ub294 \uc544\ub2d9\ub2c8\ub2e4. JetBrains\ub3c4 \ub85c\ub4dc\ub9f5\uc5d0\uc11c Gradle \ud504\ub85c\uc81d\ud2b8\uc758 \uacf5\ubc31\uc744 \uba3c\uc800 \uba54\uc6b0\ub294 \ub370 \uc9d1\uc911\ud558\uaca0\ub2e4\uace0 \ubc1d\ud614\uc2b5\ub2c8\ub2e4.<br/>\\n\ub2e4\ub9cc \uc0c8\ub85c KMP\ub97c \uc2dc\uc791\ud55c\ub2e4\uba74 `kotlin new` \ud55c \ubc88\uc73c\ub85c Android\xb7iOS \ud658\uacbd\uc744 \ud55c \ubc88\uc5d0 \ub9de\ucd94\ub294 \uacbd\ud5d8\uc740 \uaf64 \ub9e4\ub825\uc801\uc785\ub2c8\ub2e4. \ub2e4\uc74c\uc5d0 \uc0ac\uc774\ub4dc \ud504\ub85c\uc81d\ud2b8\ub85c KMP\ub97c \ub9cc\uc9c8 \uc77c\uc774 \uc788\uc73c\uba74 \uc774 \uacbd\ub85c\ub85c \uc2dc\uc791\ud574 \ubcfc \uc0dd\uac01\uc785\ub2c8\ub2e4.\\n\\n> \ucd9c\ucc98: [Start Your Next KMP App With Kotlin Toolchain 0.13 \u2014 The Kotlin Blog](https://blog.jetbrains.com/kotlin/2026/10/start-your-next-kmp-app-with-kotlin-toolchain-0-13/)"},{"id":"mts-gradle-convention-plugin","metadata":{"permalink":"/blog/posts/mts-gradle-convention-plugin","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-12-05-gradle-convention-plugin/index.mdx","source":"@site/blog/2025-12-05-gradle-convention-plugin/index.mdx","title":"\uad6d\ub0b4 MTS\uc5d0 Gradle Convention Plugin \ub3c4\uc785\ud558\uae30","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2025-12-05T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"gradle-convention-plugin","permalink":"/blog/posts/tags/gradle-convention-plugin"},{"inline":true,"label":"mts","permalink":"/blog/posts/tags/mts"},{"inline":true,"label":"\ud55c\uad6d\ud22c\uc790\uc99d\uad8c","permalink":"/blog/posts/tags/\ud55c\uad6d\ud22c\uc790\uc99d\uad8c"},{"inline":true,"label":"\ud55c\ud22c","permalink":"/blog/posts/tags/\ud55c\ud22c"}],"readingTime":1.59,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"mts-gradle-convention-plugin","title":"\uad6d\ub0b4 MTS\uc5d0 Gradle Convention Plugin \ub3c4\uc785\ud558\uae30","authors":["way"],"tags":["android","gradle-convention-plugin","mts","\ud55c\uad6d\ud22c\uc790\uc99d\uad8c","\ud55c\ud22c"]},"unlisted":false,"prevItem":{"title":"Kotlin Toolchain 0.13 \u2014 \uc0c8 KMP \ud504\ub85c\uc81d\ud2b8\ub294 kotlin new\ub85c \uc2dc\uc791\ud558\uae30","permalink":"/blog/posts/kotlin-toolchain-013"},"nextItem":{"title":"\uad6d\ub0b4 MTS\uc5d0 Multi Module \ub3c4\uc785\ud558\uae30","permalink":"/blog/posts/mts-multi-module"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 MTS \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc801\uc6a9\ud558\uac8c \ub41c Gradle Convention Plugin\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ubc30\uacbd\\nMulti Module\uc744 \uc801\uc6a9\ud558\uba74\uc11c, \uac01 \ubaa8\ub4c8\uc758 `build.gradle.kts` \ud30c\uc77c\uc5d0 \uc911\ubcf5\ub418\ub294 \uc124\uc815\ub4e4\uc774 \ub9ce\uc544\uc84c\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 Gradle Convention Plugin\uc744 \ub3c4\uc785\ud558\uc5ec \uacf5\ud1b5 \uc124\uc815\uc744 \uc911\uc559\uc5d0\uc11c \uad00\ub9ac\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uae30\uc874 build.gradle.kts \ud30c\uc77c\ub4e4\uc740 \ub2e4\uc74c\uacfc \uac19\uc740 \uad6c\uc870\ub97c \uac00\uc9c0\uace0 \uc788\uc5c8\uc2b5\ub2c8\ub2e4.\\n\\n```gradle\\n//A module\\nplugins {\\n    alias(libs.plugins.android.application)\\n    alias(libs.plugins.kotlin.android)\\n}\\n\\nandroid {\\n    namespace = \\"com.example.module-a\\"\\n    compileSdk = libs.versions.compile.sdk.get().toInt()\\n    dependencies {\\n        implementation(libs.bundles.kotlin)\\n    }\\n}\\n\\n//B module\\n\\nplugins {\\n    alias(libs.plugins.android.application)\\n    alias(libs.plugins.kotlin.android)\\n}\\n\\nandroid {\\n    namespace = \\"com.example.module-b\\"\\n    compileSdk = libs.versions.compile.sdk.get().toInt()\\n    dependencies {\\n        implementation(libs.bundles.kotlin)\\n    }\\n}\\n\\n```\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media4.giphy.com/media/v1.Y2lkPTc5MGI3NjExYnhsZ2I0Yjd5ZWM4bGNmbGR3cmNlejcwMzgyN2MzbzE2NHlmN2h5bSZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/GERw43KIyCqh5nDNlM/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### Gradle Convention Plugin \ub3c4\uc785\\n\uc704\uc640 \uac19\uc774 \uc911\ubcf5\ub418\ub294 \uc124\uc815\ub4e4\uc744 Gradle Convention Plugin\uc73c\ub85c \ubd84\ub9ac\ud558\uc5ec \uad00\ub9ac\ud558\uba74, \uac01 \ubaa8\ub4c8\uc758 `build.gradle.kts` \ud30c\uc77c\uc774 \ud6e8\uc52c \uac04\uacb0\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\ub2e4\uc74c\uc740 Convention Plugin\uc744 \uc801\uc6a9\ud55c \ud6c4\uc758 \uc608\uc2dc\uc785\ub2c8\ub2e4.\\n\\n#### build-logic/convention/build.gradle.kts\\n```kotlin\\n\\nplugins {\\n    `kotlin-dsl`\\n    `kotlin-dsl-precompiled-script-plugins`\\n}\\n\\ngroup = \\"com.sample.buildlogic\\"\\n\\ndependencies {\\n    compileOnly(libs.android.gradle.plugin)\\n    compileOnly(libs.kotlin.gradle.plugin)\\n    compileOnly(libs.gradle.plugin.ktlint.compose)\\n    compileOnly(libs.gradle.plugin.detekt)\\n    compileOnly(libs.gradle.plugin.ksp)\\n}\\n\\ngradlePlugin {\\n    plugins {\\n        register(\\"sample.android.library\\") {\\n            id = \\"sample.android.library\\"\\n            implementationClass = \\"AndroidLibrarySampleConventionPlugin\\"\\n        }\\n    }\\n}\\n```\\n\\n#### build-logic/src/main/kotlin/AndroidLibrarySampleConventionPlugin.kt\\n```kotlin\\nclass AndroidLibrarySampleConventionPlugin : Plugin<Project> {\\n    override fun apply(target: Project) {\\n        with(target) {\\n            with(pluginManager) {\\n                apply(\\"com.android.library\\")\\n                apply(\\"kotlin-android\\")\\n                apply(\\"koreainvestment.kotlinx.serialization\\")\\n            }\\n            extensions.getByType<VersionCatalogsExtension>().named(\\"libs\\").apply {\\n                extensions.configure<LibraryExtension> {\\n                    configureKotlinAndroid(this)\\n                    defaultConfig.targetSdk =\\n                        findVersion(\\"target-sdk\\").get().requiredVersion.toInt()\\n                    configureFlavors(this)\\n                    defaultConfig.vectorDrawables.useSupportLibrary = true\\n                }\\n            }\\n        }\\n    }\\n}\\n```\\n#### build-logic/convention/build.gradle.kts\\n```gradle\\n//A module\\nplugins {\\n    id(\\"sample.android.library\\")\\n}\\n\\nandroid {\\n    namespace = \\"com.example.module-a\\"\\n}\\n\\n//B module\\n\\nplugins {\\n    id(\\"sample.android.library\\")\\n}\\n\\nandroid {\\n    namespace = \\"com.example.module-b\\"\\n}\\n```\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc704\uc640 \uac19\uc774 Convention Plugin\uc744 \ub3c4\uc785\ud558\uba74, \uacf5\ud1b5 \uc124\uc815\uc774 \uc911\uc559\uc5d0\uc11c \uad00\ub9ac\ub418\uc5b4 \uc720\uc9c0\ubcf4\uc218\uac00 \uc6a9\uc774\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\ub610\ud55c, \uc0c8\ub85c\uc6b4 \ubaa8\ub4c8\uc744 \ucd94\uac00\ud560 \ub54c\ub3c4 Convention Plugin\ub9cc \uc801\uc6a9\ud558\uba74 \ub418\ubbc0\ub85c \uac1c\ubc1c \uc18d\ub3c4\ub3c4 \ud5a5\uc0c1\ub429\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExZHJ3OXNybjRlMm1jcGoxbTAxbjJ5NmtlNHZwZ2w0aXJlenNuZ252ZSZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/5YecPtoB4DZzPPr8ak/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"mts-multi-module","metadata":{"permalink":"/blog/posts/mts-multi-module","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-12-04-multi-module/index.mdx","source":"@site/blog/2025-12-04-multi-module/index.mdx","title":"\uad6d\ub0b4 MTS\uc5d0 Multi Module \ub3c4\uc785\ud558\uae30","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2025-12-04T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"multi-module","permalink":"/blog/posts/tags/multi-module"},{"inline":true,"label":"mts","permalink":"/blog/posts/tags/mts"},{"inline":true,"label":"\ud55c\uad6d\ud22c\uc790\uc99d\uad8c","permalink":"/blog/posts/tags/\ud55c\uad6d\ud22c\uc790\uc99d\uad8c"},{"inline":true,"label":"\ud55c\ud22c","permalink":"/blog/posts/tags/\ud55c\ud22c"}],"readingTime":1.91,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"mts-multi-module","title":"\uad6d\ub0b4 MTS\uc5d0 Multi Module \ub3c4\uc785\ud558\uae30","authors":["way"],"tags":["android","multi-module","mts","\ud55c\uad6d\ud22c\uc790\uc99d\uad8c","\ud55c\ud22c"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 MTS\uc5d0 Gradle Convention Plugin \ub3c4\uc785\ud558\uae30","permalink":"/blog/posts/mts-gradle-convention-plugin"},"nextItem":{"title":"\uad6d\ub0b4 MTS\uc5d0 Version Catalog \ub3c4\uc785\ud558\uae30","permalink":"/blog/posts/mts-version-catalog"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\uad6d\ub0b4 MTS \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc801\uc6a9\ud558\uac8c \ub41c Multi Module\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud604\uc7ac \ud504\ub85c\uc81d\ud2b8 \uad6c\uc870\\n\\n\ud504\ub85c\uc81d\ud2b8\uc5d0 \uc5ec\ub7ec \ubaa8\ub4c8\uc774 \uc874\uc7ac\ud558\uc9c0\ub9cc, 3rd party \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc774 \ub2e4\uc218\uc774\uace0, \uac01 Feature\ub4e4\uc744 \uc7ac\uc0ac\uc6a9\ud558\uae30\uc5d0 \uc801\ud569\ud558\uc9c0 \uc54a\uc740 \uc0c1\ud0dc\uc600\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 Multi Module \uad6c\uc870\ub85c \uc804\ud658\ud558\ub294 \uc791\uc5c5\uc744 \uc9c4\ud589\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ub7b5\uc801\uc778 \ud504\ub85c\uc81d\ud2b8 \uad6c\uc870\ub294 \ub300\ub7b5 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n```text\\n.\\n\u251c\u2500\u2500 app\\n\u251c\u2500\u2500 3rd_party_library_1\\n\u251c\u2500\u2500 3rd_party_library_2\\n\u251c\u2500\u2500 3rd_party_library_3\\n\u251c\u2500\u2500 3rd_party_library_4\\n\u2514\u2500\u2500 formdeCore\\n```\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media3.giphy.com/media/v1.Y2lkPTc5MGI3NjExNzZ6YjJlN2J2Y3R6cHU4enV3N2RuODJweGZqemU2Zm53OWdyZmY5MyZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/Nx85vtTY70T3W/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n### MultiModule \uc801\uc6a9\\n\\nMulti Module \uad6c\uc870\ub85c \uc804\ud658\ud558\uba74\uc11c, \ubaa8\ub4c8\uc758 \uc0c1\ub2e8 \uba85\uce6d\uc744 core, library, features, plugins, resources \ub4f1\uc73c\ub85c \uad6c\ubd84\ud558\uc5ec \uad00\ub9ac\ud558\uae30\ub85c \ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uccb4\uc801\uc778 \ub514\ub809\ud1a0\ub9ac \uad6c\uc870\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n```text\\n.\\n\u251c\u2500\u2500 app/\\n\u251c\u2500\u2500 core/\\n\u2502   \u251c\u2500\u2500 analytics/\\n\u2502   \u251c\u2500\u2500 asset-file/\\n\u2502   \u251c\u2500\u2500 autorization/\\n\u2502   \u251c\u2500\u2500 common/\\n\u2502   \u251c\u2500\u2500 database/\\n\u2502   \u251c\u2500\u2500 datastore/\\n\u2502   \u251c\u2500\u2500 encrypt/\\n\u2502   \u251c\u2500\u2500 network/\\n\u2502   \u251c\u2500\u2500 on-foreground-service/\\n\u2502   \u251c\u2500\u2500 push/\\n\u2502   \u251c\u2500\u2500 remote-file/\\n\u2502   \u251c\u2500\u2500 state-viewmodel/\\n\u2502   \u251c\u2500\u2500 testing/\\n\u2502   \u251c\u2500\u2500 ui/\\n\u2502   \u2514\u2500\u2500 ui-xml/\\n\u251c\u2500\u2500 features/\\n\u2502   \u251c\u2500\u2500 common/\\n\u2502   \u2502   \u251c\u2500\u2500 ui/\\n\u2502   \u2502   \u2514\u2500\u2500 logic/\\n\u2502   \u251c\u2500\u2500 community/\\n\u2502   \u2502   \u251c\u2500\u2500 ui/\\n\u2502   \u2502   \u2514\u2500\u2500 logic/\\n\u2502   \u251c\u2500\u2500 developer/\\n\u2502   \u2502   \u251c\u2500\u2500 ui/\\n\u2502   \u2502   \u2514\u2500\u2500 logic/\\n\u2502   \u251c\u2500\u2500 event/\\n\u2502   \u2502   \u251c\u2500\u2500 ui/\\n\u2502   \u2502   \u2514\u2500\u2500 logic/\\n\u2502   \u251c\u2500\u2500 menu/\\n\u2502   \u2502   \u251c\u2500\u2500 ui/\\n\u2502   \u2502   \u2514\u2500\u2500 logic/\\n\u2502   \u251c\u2500\u2500 my-assets/\\n\u2502   \u2502   \u251c\u2500\u2500 ui/\\n\u2502   \u2502   \u2514\u2500\u2500 logic/\\n\u2502   \u2514\u2500\u2500 product-type/\\n\u2502       \u251c\u2500\u2500 ui/\\n\u2502       \u2514\u2500\u2500 logic/\\n\u251c\u2500\u2500 library/\\n\u2502   \u251c\u2500\u2500 formdeCore/\\n\u2502   \u251c\u2500\u2500 3rd_party_library_1/\\n\u2502   \u251c\u2500\u2500 3rd_party_library_2/\\n\u2502   \u251c\u2500\u2500 3rd_party_library_3/\\n\u2502   \u2514\u2500\u2500 3rd_party_library_4/\\n\u251c\u2500\u2500 plugins/\\n\u2502   \u251c\u2500\u2500 annotation/\\n\u2502   \u251c\u2500\u2500 lint/\\n\u2502   \u2514\u2500\u2500 symobl-processor/\\n\u2514\u2500\u2500 resources/\\n```\\n\\n#### app\\n- \ucd5c\uc885\uc801\uc73c\ub85c \ube4c\ub4dc\ub418\ub294 \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158 \ubaa8\ub4c8\uc785\ub2c8\ub2e4.\\n\\n#### core\\n- \ud504\ub85c\uc81d\ud2b8 \uc804\ubc18\uc5d0\uc11c \uacf5\ud1b5\uc73c\ub85c \uc0ac\uc6a9\ub418\ub294 \uae30\ub2a5\ub4e4\uc744 \ud3ec\ud568\ud558\ub294 \ubaa8\ub4c8\uc785\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4, \ub124\ud2b8\uc6cc\ud06c \ud1b5\uc2e0, \ub370\uc774\ud130\ubca0\uc774\uc2a4 \uad00\ub9ac, \uc778\uc99d \ucc98\ub9ac \ub4f1\uc758 \uae30\ub2a5\ub4e4\uc774 \uc5ec\uae30\uc5d0 \uc18d\ud569\ub2c8\ub2e4.\\n\\n#### features\\n- \uc2e4\uc81c \uc5b4\ud50c\ub9ac\ucf00\uc774\uc158\uc758 \uae30\ub2a5 \ub2e8\uc704\ub4e4\uc744 \ubaa8\ub4c8\ud654\ud55c \uac83\uc785\ub2c8\ub2e4.<br/>\\n\uac01 \uae30\ub2a5\uc740 \ub3c5\ub9bd\uc801\uc73c\ub85c \uac1c\ubc1c \ubc0f \ud14c\uc2a4\ud2b8\uac00 \uac00\ub2a5\ud558\ub3c4\ub85d \uad6c\uc131\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4, \ucee4\ubba4\ub2c8\ud2f0, \uc774\ubca4\ud2b8, \uba54\ub274 \uad00\ub9ac \ub4f1\uc758 \uae30\ub2a5\ub4e4\uc774 \uc5ec\uae30\uc5d0 \uc18d\ud569\ub2c8\ub2e4.\\n\\n- logic\\n    - \uac01 \uae30\ub2a5 \ubaa8\ub4c8 \ub0b4\uc5d0\uc11c \ube44\uc988\ub2c8\uc2a4 \ub85c\uc9c1\uc744 \ub2f4\ub2f9\ud558\ub294 \ubd80\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\ud574\ub2f9 \ubaa8\ub4c8\uc5d0\uc11c\ub294 \uae30\ub2a5\uc5d0 \ud544\uc694\ud55c \ubaa8\ub378\uacfc \ube44\uc988\ub2c8\uc2a4 \ub85c\uc9c1\uc744 \uad6c\ud604\ud569\ub2c8\ub2e4. \uc774\ub97c \ud1b5\ud574 UI\uc640\uc758 \ubd84\ub9ac\ub97c \uc720\uc9c0\ud558\uace0, \ub2e4\ub978 feature \ubaa8\ub4c8\uc5d0\uc11c\ub3c4 \uc7ac\uc0ac\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \ud569\ub2c8\ub2e4.\\n- ui\\n    - \uac01 \uae30\ub2a5 \ubaa8\ub4c8 \ub0b4\uc5d0\uc11c \uc0ac\uc6a9\uc790 \uc778\ud130\ud398\uc774\uc2a4\ub97c \ub2f4\ub2f9\ud558\ub294 \ubd80\ubd84\uc785\ub2c8\ub2e4.<br/>\\n\\n#### library\\n- 3rd party \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \uacf5\ud1b5\uc73c\ub85c \uc0ac\uc6a9\ub418\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc744 \uad00\ub9ac\ud558\ub294 \ubaa8\ub4c8\uc785\ub2c8\ub2e4.<br/>\\n\\n#### plugins\\n- \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc801\uc6a9\ub418\ub294 Gradle \ud50c\ub7ec\uadf8\uc778\ub4e4\uc744 \uad00\ub9ac\ud558\ub294 \ubaa8\ub4c8\uc785\ub2c8\ub2e4.<br/>\\n\uc608\ub97c \ub4e4\uc5b4, \ucee4\uc2a4\ud140 Lint \uac80\uc0ac\uae30\ub098 \uc5b4\ub178\ud14c\uc774\uc158 \ud504\ub85c\uc138\uc11c \ub4f1\uc774 \uc5ec\uae30\uc5d0 \uc18d\ud569\ub2c8\ub2e4.\\n\\n#### resources\\n- \uc774\ubbf8\uc9c0, \ubb38\uc790\uc5f4, \ub808\uc774\uc544\uc6c3 \ud30c\uc77c \ub4f1\uacfc \uac19\uc740 \ub9ac\uc18c\uc2a4 \ud30c\uc77c\ub4e4\uc744 \uad00\ub9ac\ud558\ub294 \ubaa8\ub4c8\uc785\ub2c8\ub2e4.\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc774\uc640 \uac19\uc740 Multi Module \uad6c\uc870\ub97c \ub3c4\uc785\ud568\uc73c\ub85c\uc368, \ucf54\ub4dc\uc758 \uc7ac\uc0ac\uc6a9\uc131\uc774 \ud5a5\uc0c1\ub418\uace0, \uac01 \ubaa8\ub4c8 \uac04\uc758 \uc758\uc874\uc131\uc744 \uba85\ud655\ud788 \uad00\ub9ac\ud560 \uc218 \uc788\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub610\ud55c, \uac01 \ubaa8\ub4c8\uc744 \ub3c5\ub9bd\uc801\uc73c\ub85c \uac1c\ubc1c\ud558\uace0 \ud14c\uc2a4\ud2b8\ud560 \uc218 \uc788\uc5b4 \uac1c\ubc1c \ud6a8\uc728\ub3c4 \ud06c\uac8c \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4.\\n\\n\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media0.giphy.com/media/v1.Y2lkPTc5MGI3NjExN3AzOTlpaXJzMjdsbWVtMDhzano3M3dyaG42MmpmbWVucGowbzQwOCZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/uoQHi35INTkg4ePrbz/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"},{"id":"mts-version-catalog","metadata":{"permalink":"/blog/posts/mts-version-catalog","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2025-12-03-version-catalog/index.mdx","source":"@site/blog/2025-12-03-version-catalog/index.mdx","title":"\uad6d\ub0b4 MTS\uc5d0 Version Catalog \ub3c4\uc785\ud558\uae30","description":"\uc548\ub155\ud558\uc138\uc694, \ud55c\uad6d\ud22c\uc790\uc99d\uad8c\uc5d0\uc11c \ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.","date":"2025-12-03T00:00:00.000Z","tags":[{"inline":true,"label":"android","permalink":"/blog/posts/tags/android"},{"inline":true,"label":"toml","permalink":"/blog/posts/tags/toml"},{"inline":true,"label":"version-catalog","permalink":"/blog/posts/tags/version-catalog"},{"inline":true,"label":"gradle","permalink":"/blog/posts/tags/gradle"},{"inline":true,"label":"mts","permalink":"/blog/posts/tags/mts"},{"inline":true,"label":"\ud55c\uad6d\ud22c\uc790\uc99d\uad8c","permalink":"/blog/posts/tags/\ud55c\uad6d\ud22c\uc790\uc99d\uad8c"},{"inline":true,"label":"\ud55c\ud22c","permalink":"/blog/posts/tags/\ud55c\ud22c"}],"readingTime":1.93,"hasTruncateMarker":false,"authors":[{"name":"Way","title":"Android Developer","url":"http://code-bross.github.io/","page":{"permalink":"/blog/posts/authors/way"},"socials":{"linkedin":"https://www.linkedin.com/in/z3r0ad/","github":"https://github.com/code-bross"},"imageURL":"https://github.com/code-bross/portfolio/blob/develop/assets/sakun_2.png?raw=true","key":"way"}],"frontMatter":{"slug":"mts-version-catalog","title":"\uad6d\ub0b4 MTS\uc5d0 Version Catalog \ub3c4\uc785\ud558\uae30","authors":["way"],"tags":["android","toml","version-catalog","gradle","mts","\ud55c\uad6d\ud22c\uc790\uc99d\uad8c","\ud55c\ud22c"]},"unlisted":false,"prevItem":{"title":"\uad6d\ub0b4 MTS\uc5d0 Multi Module \ub3c4\uc785\ud558\uae30","permalink":"/blog/posts/mts-multi-module"}},"content":"\uc548\ub155\ud558\uc138\uc694, [\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://securities.koreainvestment.com/main/Main.jsp)\uc5d0\uc11c [\ud55c\ud22c-\ud55c\uad6d\ud22c\uc790\uc99d\uad8c](https://play.google.com/store/apps/details?id=com.truefriend.neosmartarenewal&hl=ko) \uac1c\ubc1c\uc744 \ub2f4\ub2f9\ud558\uace0 \uc788\ub294 way\uc785\ub2c8\ub2e4.<br/>\\n\\n\uad6d\ub0b4 MTS \ud504\ub85c\uc81d\ud2b8\uc5d0 \uc801\uc6a9\ud558\uac8c \ub41c Version Catalog\uc5d0 \ub300\ud574 \uc124\uba85\ud574\ub4dc\ub9ac\uaca0\uc2b5\ub2c8\ub2e4.<br/>\\n\uc548\ub4dc\ub85c\uc774\ub4dc\ub294 gradle\uc744 \ube4c\ub4dc \uc2dc\uc2a4\ud15c\uc73c\ub85c \uc0ac\uc6a9\ud558\uba70, groovy \ub610\ub294 kotlin DSL\uc744 \ud1b5\ud574 \uc758\uc874\uc131 \uad00\ub9ac\ub97c \uc218\ud589\ud569\ub2c8\ub2e4.<br/>\\n\uae30\uc874 \ud504\ub85c\uc81d\ud2b8\uc5d0\uc11c\ub294 \uc5ec\ub7ec \ubaa8\ub4c8\uc5d0\uc11c \uac01\uae30 \ub2e4\ub978 \ub77c\uc774\ube0c\ub7ec\ub9ac \ubc84\uc804\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\uc5b4, \uc6b0\uc120 \uc774\ub4e4\uc744 \uc77c\uad00\ub418\uac8c \uad00\ub9ac\ud558\ub294 \ubc29\ubc95\uc73c\ub85c [Version Catalog](https://developer.android.com/build/migrate-to-catalogs?hl=ko) \uc801\uc6a9\uc744 \uac80\ud1a0\ud558\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\\n### \ud604\uc7ac \ud504\ub85c\uc81d\ud2b8 \uad6c\uc870\\n\\napp\uc5d0 \uc9c0\ub098\uce58\uac8c \uc758\uc874\uc801\uc774\uace0 3rd party \ub77c\uc774\ube0c\ub7ec\ub9ac\uac00 \uc0b0\uc7ac\ud574 \uc788\uc5b4 \uc720\uc9c0\ubcf4\uc218\uac00 \uc5b4\ub824\uc6b4 \uc0c1\ud669\uc774\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\uc774\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 Multi Module \uad6c\uc870\ub85c \uc804\ud658\ud558\ub294 \uc791\uc5c5\uc744 \uc9c4\ud589\ud588\uace0, \uadf8 \uacfc\uc815\uc5d0\uc11c Version Catalog\ub97c \ub3c4\uc785\ud558\uac8c \ub418\uc5c8\uc2b5\ub2c8\ub2e4.<br/>\\n\ub300\ub7b5\uc801\uc778 \ud504\ub85c\uc81d\ud2b8 \uad6c\uc870\ub294 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media4.giphy.com/media/v1.Y2lkPTc5MGI3NjExZ25lcGU0OGlxYjJqZzhnaDl3NHd4OWt4aGk3MzRvanc0MTIxdDgzcyZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/iHe7mA9M9SsyQ/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>\\n\\n```text\\n.\\n\u251c\u2500\u2500 app\\n\u251c\u2500\u2500 3rd_party_library_1\\n\u251c\u2500\u2500 3rd_party_library_2\\n\u251c\u2500\u2500 3rd_party_library_3\\n\u251c\u2500\u2500 3rd_party_library_4\\n\u2514\u2500\u2500 formdeCore\\n```\\n\\n### Version Catalog \ub3c4\uc785\ud558\uae30\\n\\nGradle\uc758 [Version Catalog](https://developer.android.com/build/migrate-to-catalogs?hl=ko)\ub97c \ub3c4\uc785\ud574 \ubaa8\ub4c8 \uac04 \ub77c\uc774\ube0c\ub7ec\ub9ac \ubc84\uc804\uc744 \uc911\uc559\uc5d0\uc11c \uad00\ub9ac\ud558\ub3c4\ub85d \ubcc0\uacbd\ud588\uc2b5\ub2c8\ub2e4.<br/>\\n\uad6c\uccb4\uc801\uc73c\ub85c\ub294 `gradle/libs.versions.toml` \ud30c\uc77c\uc744 \ub9cc\ub4e4\uace0, \uac01 \ubaa8\ub4c8\uc758 `build.gradle.kts`\uc5d0\uc11c \ud574\ub2f9 \uce74\ud0c8\ub85c\uadf8\ub97c \ucc38\uc870\ud558\ub3c4\ub85d \ud588\uc2b5\ub2c8\ub2e4.\\n\\n#### versions\\n- \uac01 \ubaa8\ub4c8\uc758 \ub77c\uc774\ube0c\ub7ec\ub9ac \ubc84\uc804\uc744 \uc815\uc758\ud569\ub2c8\ub2e4.\\n- \ud328\ud0a4\uc9d5\ub418\uc5b4\uc788\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc758 \uacbd\uc6b0 \ubc84\uc804\uc774 \ub3d9\uc77c\ud55c \uacbd\uc6b0\uac00 \ub9ce\uae30 \ub54c\ubb38\uc5d0 \ubc84\uc804\uc744 \uacf5\ud1b5\uc73c\ub85c \uad00\ub9ac\ud558\uba74 \ud3b8\ub9ac\ud569\ub2c8\ub2e4.\\n\\n#### libraries\\n- \uac01 \ubaa8\ub4c8\uc5d0\uc11c \uc0ac\uc6a9\ud560 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc640 \ud574\ub2f9 \ubc84\uc804\uc744 \uc815\uc758\ud569\ub2c8\ub2e4.\\n\\n#### plugins\\n- \uac01 \ubaa8\ub4c8\uc5d0\uc11c \uc0ac\uc6a9\ud560 \ud50c\ub7ec\uadf8\uc778\uacfc \ud574\ub2f9 \ubc84\uc804\uc744 \uc815\uc758\ud569\ub2c8\ub2e4.\\n\\n#### bundles\\n- \uad00\ub828\ub41c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc744 \ubb36\uc5b4\uc11c \ud55c \ubc88\uc5d0 \ucc38\uc870\ud560 \uc218 \uc788\ub3c4\ub85d \uc815\uc758\ud569\ub2c8\ub2e4.\\n- \ud544\uc694\ud55c \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc744 \ud328\ud0a4\uc9d5\ud558\uc5ec \ud55c \ubc88\uc5d0 \ucd94\uac00\ud560 \uc218 \uc788\uc5b4 \ud3b8\ub9ac\ud569\ub2c8\ub2e4.\\n\\n\uc608\uc2dc\ub85c \uc0ac\uc6a9\ud55c `libs.versions.toml`\uc740 \ub2e4\uc74c\uacfc \uac19\uc2b5\ub2c8\ub2e4.\\n\\n```toml\\n[versions]\\nkotlin = \\"2.0.21\\"\\ntarget-sdk = \\"36\\"\\njvm = \\"17\\"\\nmin-sdk = \\"26\\"\\ncompile-sdk = \\"36\\"\\nandroid-gradle-plugin = \\"8.3.2\\"\\n.\\n.\\n.\\n\\n[plugins]\\nandroid-application = { id = \\"com.android.application\\", version.ref = \\"android-gradle-plugin\\" }\\n.\\n.\\n.\\n\\n[libraries]\\nandroid-gradle-plugin = { module = \\"com.android.tools.build:gradle\\", version.ref = \\"android-gradle-plugin\\" }\\n.\\n.\\n.\\n[bundles]\\nkotlin = [\\"kotlin-stdlib\\", \\"kotlin-reflect\\"]\\n```\\n\\n\uadf8\ub9ac\uace0 \uac01 \ubaa8\ub4c8\uc758 `build.gradle.kts`\uc5d0\uc11c \ub2e4\uc74c\uacfc \uac19\uc774 \ud50c\ub7ec\uadf8\uc778\uacfc \ubc84\uc804\uc744 \ucc38\uc870\ud558\ub3c4\ub85d \ubcc0\uacbd\ud588\uc2b5\ub2c8\ub2e4.\\n\\n```kotlin\\nplugins {\\n    alias(libs.plugins.android.application)\\n    alias(libs.plugins.kotlin.android)\\n}\\n\\nandroid {\\n    compileSdk = libs.versions.compile.sdk.get().toInt()\\n\\n    defaultConfig {\\n        applicationId = \\"com.example.app\\"\\n        minSdk = libs.versions.min.sdk.get().toInt()\\n        targetSdk = libs.versions.target.sdk.get().toInt()\\n        versionCode = 1\\n        versionName = \\"1.0\\"\\n    }\\n    dependencies {\\n        implementation(libs.bundles.kotlin)\\n    }\\n}\\n```\\n\\n### \ub9c8\uce58\uba70\\n\\n\uc774\uc640 \uac19\uc774 Version Catalog\ub97c \uc801\uc6a9\ud558\uba74, \ub77c\uc774\ube0c\ub7ec\ub9ac \ubc84\uc804 \uad00\ub9ac\uac00 \uc77c\uad00\ud654\ub418\uc5b4 \uc5c5\ub370\uc774\ud2b8\ub098 \ucda9\ub3cc \ud574\uacb0\uc774 \ud6e8\uc52c \uc218\uc6d4\ud574\uc9d1\ub2c8\ub2e4.<br/>\\n\ub610\ud55c, \uc0c8\ub85c\uc6b4 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ucd94\uac00\ud560 \ub54c\ub3c4 \uc911\uc559 \ud30c\uc77c\ub9cc \uc218\uc815\ud558\uba74 \ub418\ubbc0\ub85c \uc720\uc9c0\ubcf4\uc218\uac00 \uac04\ud3b8\ud574\uc9d1\ub2c8\ub2e4.\\n\\n<div style={{textAlign: \'center\', margin: \'1.5rem 0\'}}>\\n  <img src=\\"https://media4.giphy.com/media/v1.Y2lkPTc5MGI3NjExbXlja2N5Z3Fva3F1cmJjZzA4N210aXM4NW5lODN4bGpiZTc3cWI1OCZlcD12MV9pbnRlcm5hbF9naWZfYnlfaWQmY3Q9Zw/Ala8Pjo4RN9kY/giphy.gif\\" alt=\\"Success\\" style={{maxWidth: \'100%\', borderRadius: \'8px\', maxHeight: \'250px\'}} />\\n</div>"}]}}')}}]);